    "\n"
    "const fetchers = {\n"
    "  memory:    {path:'/v1/memory',    out:'memory-out'},\n"
    "  snapshots: {path:'/v1/snapshots', out:'snapshots-out'},\n"
    "  usage:     {path:'/v1/usage',     out:'usage-out'},\n"
    "  plugins:   {path:'/v1/plugins',   out:'plugins-out'},\n"
    "  skills:    {path:'/v1/skills',    out:'skills-out'},\n"
    "  cluster:   {path:'/v1/cluster',   out:'cluster-out'},\n"
    "  metrics:   {path:'/metrics',      out:'metrics-out'},\n"
    "};\n"
    "\n"
    "/* ================= 数据加载 ================= */\n"
    "\n"
    "/* fetch one fetchers[] entry into its <pre> (used by panels that need both\n"
    " * a raw endpoint dump and a custom-rendered section) */\n"
    "async function loadFetcher(key){\n"
    "  const f = fetchers[key]; if(!f) return;\n"
    "  const r = await call('GET', f.path);\n"
    "  const el = $(f.out); if(el) renderJSON(r.obj, el);\n"
    "}\n"
    "\n"
    "let traceLoading = false;\n"
    "let traceDiagnosticSnapshot = null;\n"
    "function traceSetExpanded(open){\n"
    "  document.querySelectorAll('#trace-live details, #trace-history details').forEach(detail => { detail.open = open; });\n"
    "}\n"
    "function traceCopyDiagnostics(){\n"
    "  if(!traceDiagnosticSnapshot || (!traceDiagnosticSnapshot.live_spans.length && !traceDiagnosticSnapshot.history.length)){\n"
    "    toast('暂无可复制的诊断记录'); return;\n"
    "  }\n"
    "  copyText(JSON.stringify(traceDiagnosticSnapshot, null, 2));\n"
    "}\n"
    "function traceExpandedDetails(target){\n"
    "  if(!target) return new Set();\n"
    "  return new Set(Array.from(target.querySelectorAll('details[open][data-trace-key]'), detail => detail.dataset.traceKey));\n"
    "}\n"
    "function renderTraceSpans(target, spans, emptyText, expanded){\n"
    "  if(!target) return;\n"
    "  expanded = expanded || traceExpandedDetails(target);\n"
    "  target.replaceChildren();\n"
    "  if(!spans.length){ target.textContent = emptyText; target.classList.add('hint'); return; }\n"
    "  target.classList.remove('hint');\n"
    "  spans.forEach(s => {\n"
    "    const row = document.createElement('div'); row.className = 'trace-row';\n"
    "    const state = document.createElement('span'); state.className = 'trace-state';\n"
    "    state.style.color = s.status === 1 ? 'var(--ok)' : s.status === -1 ? 'var(--danger)' : 'var(--accent)';\n"
    "    state.textContent = s.status === 1 ? '完成' : s.status === -1 ? '失败' : '进行中';\n"
    "    const name = document.createElement('code'); name.textContent = s.name || 'span';\n"
    "    const task = document.createElement('span'); task.className = 'muted';\n"
    "    task.textContent = Number.isFinite(s.task_id) && s.task_id >= 0 ? '#' + s.task_id : '本地';\n"
    "    const time = document.createElement('span'); time.className = 'muted';\n"
    "    const duration = s.end_ms ? s.duration_ms : Math.max(0, Date.now() - (s.start_ms || Date.now()));\n"
    "    time.textContent = (s.start_ms ? new Date(s.start_ms).toLocaleTimeString() + ' · ' : '') + duration + ' ms';\n"
    "    row.append(state,name,task,time);\n"
    "    if(typeof s.command === 'string' || typeof s.result === 'string'){\n"
    "      const detail = document.createElement('details'); detail.style.gridColumn = '1 / -1';\n"
    "      detail.dataset.traceKey = JSON.stringify([s.task_id,s.id,s.start_ms]);\n"
    "      detail.open = expanded.has(detail.dataset.traceKey);\n"
    "      const summary = document.createElement('summary'); summary.textContent = '调用参数与执行结果'; detail.append(summary);\n"
    "      [['调用参数 / 执行命令',s.command,s.command_truncated],['执行结果',s.result,s.result_truncated]].forEach(([label,value,truncated]) => {\n"
    "        if(typeof value !== 'string') return;\n"
    "        const title = document.createElement('div'); title.textContent = label + (truncated ? '（预览已截断，完整记录见任务工具详情）' : '');\n"
    "        const pre = document.createElement('pre'); pre.textContent = value || '（无输出）';\n"
    "        pre.style.whiteSpace = 'pre-wrap'; pre.style.overflowWrap = 'anywhere'; detail.append(title,pre);\n"
    "      }); row.append(detail);\n"
    "    }\n"
    "    target.append(row);\n"
    "  });\n"
    "}\n"
    "\n"
    "async function loadTrace(){\n"
    "  if(traceLoading || current !== 'trace') return;\n"
    "  const field = $('trace-task-id');\n"
    "  const value = field ? field.value.trim() : '';\n"
    "  if(value && (!/^\\d+$/.test(value) || Number(value) < 0)){\n"
    "    toast('请输入有效的任务 ID'); return;\n"
    "  }\n"
    "  traceLoading = true;\n"
    "  try {\n"
    "    const filter = value ? '&task_id=' + encodeURIComponent(value) : '';\n"
    "    const [live, history] = await Promise.all([\n"
    "      call('GET', '/v1/trace' + (value ? '?task_id=' + encodeURIComponent(value) : '')),\n"
    "      call('GET', '/v1/trace/history?limit=30' + filter)\n"
    "    ]);\n"
    "    if(current !== 'trace') return;\n"
    "    const spans = Array.isArray(live.obj) ? live.obj : [];\n"
    "    const records = Array.isArray(history.obj) ? history.obj : [];\n"
    "    const persisted = new Set(records.flatMap(rec =>\n"
    "      (Array.isArray(rec.spans) ? rec.spans : []).map(s => s.id + ':' + s.start_ms)));\n"
    "    const liveOnly = spans.filter(s => !persisted.has(s.id + ':' + s.start_ms));\n"
    "    // Copy data rather than visible text: collapsed details and truncation\n"
    "    // flags are part of the diagnosis too. Preserve the displayed filter.\n"
    "    traceDiagnosticSnapshot = {task_filter:value || null, live_spans:liveOnly, history:records};\n"
    "    // Capture after the requests settle, so a click during polling is retained.\n"
    "    // Share keys across live/history when a task is journaled between polls.\n"
    "    const expanded = new Set([...traceExpandedDetails($('trace-live')), ...traceExpandedDetails($('trace-history'))]);\n"
    "    const count = $('trace-live-count'); if(count) count.textContent = '(' + liveOnly.length + ')';\n"
    "    renderTraceSpans($('trace-live'), liveOnly, live.status === 0 ? 'Trace 服务不可用' : '暂无进行中的 span', expanded);\n"
    "    const box = $('trace-history'); if(!box) return;\n"
    "    box.replaceChildren();\n"
    "    if(!records.length){ box.classList.add('hint'); box.textContent = history.status === 0 ? '任务历史不可用' : '暂无已落盘的 span'; return; }\n"
    "    box.classList.remove('hint');\n"
    "    records.slice().reverse().forEach(rec => {\n"
    "      const group = document.createElement('section'); group.className = 'trace-group';\n"
    "      const title = document.createElement('div'); title.className = 'trace-group-title';\n"
    "      title.textContent = '#' + rec.id + ' · ' + (rec.status || '?') + ' · ' +\n"
    "        (rec.session || 'default') + ' · ' + (rec.ts ? new Date(rec.ts).toLocaleString() : '');\n"
    "      group.append(title);\n"
    "      const list = document.createElement('div');\n"
    "      renderTraceSpans(list, Array.isArray(rec.spans) ? rec.spans : [], '无 span', expanded);\n"
    "      group.append(list); box.append(group);\n"
    "    });\n"
    "  } finally { traceLoading = false; }\n"
    "}\n"
    "\n"
    "async function load(panel){\n"
    "  if(panel === 'memory') return (loadFetcher('memory'), loadMemorySummary());\n"
    "  if(panel === 'models') return loadModels();\n"
    "  if(panel === 'dashboard') return loadDashboard();\n"
    "  if(panel === 'im') return renderIm();\n"
    "  if(panel === 'agents') return (loadAgents(), loadFlow(), loadFlowTasks());\n"
    "  if(panel === 'mcp') return (loadLocalDirs(), loadMcp());\n"
    "  if(panel === 'skills') return (loadLocalDirs(), loadSkillsMarket(), loadSkillsCatalog());\n"
    "  if(panel === 'plugins') return (loadFetcher('plugins'), loadPluginMarket());\n"
    "  if(panel === 'snapshots') return loadSnapshots();\n"
    "  if(panel === 'trace') return loadTrace();\n"
    "  if(panel === 'chat') return loadChat();\n"
    "  if(panel === 'cron') return loadCron();\n"
    "  if(panel === 'policy') return loadPolicy();\n"
    "  if(panel === 'flow') return (loadFlow(), loadFlowTasks());\n"
    "  if(panel === 'metrics'){\n"
    "    const r = await call('GET', '/metrics');\n"
    "    const el = $('metrics-out'); if(el) el.textContent = r.text;\n"
    "    return;\n"
    "  }\n"
    "  return loadFetcher(panel);\n"
    "}\n"
    "\n"
    "let MEMORY_SUMMARY_TIMER=null, MEMORY_SUMMARY_FETCHING=false, MEMORY_SUMMARY_ACTION=false;\n"
    "async function loadMemorySummary(){\n"
    "  const status=$('memory-summary-status');if(!status || MEMORY_SUMMARY_FETCHING===status)return;\n"
    "  clearTimeout(MEMORY_SUMMARY_TIMER);MEMORY_SUMMARY_FETCHING=status;\n"
    "  try{\n"
    "    const r=await call('GET','/v1/memory/summary');\n"
    "    if(status!==$('memory-summary-status'))return;\n"
    "    if(r.status!==200)throw Error(r.obj?.error||'摘要读取失败');\n"
    "    const saved=r.obj?.summary,job=r.obj?.job,active=['RUNNING','QUEUED'].includes(job?.status);\n"
    "    $('memory-summary-generate').disabled=active||MEMORY_SUMMARY_ACTION;\n"
    "    $('memory-summary-cancel').hidden=!active;\n"
    "    status.textContent=job?.save_error || (active?'正在生成摘要…':job && job.status!=='DONE'?\n"
    "      (job.result?.error||({CANCELLED:'已取消生成',TIMEOUT:'摘要生成超时',INTERRUPTED:'上次摘要生成被中断',FAILED:'摘要生成失败'}[job.status]||'摘要尚未完成'))+(saved?'；显示上次成功摘要':''):\n"
    "      saved?'摘要已保存':'暂无成功摘要');\n"
    "    if(saved){\n"
    "      $('memory-summary-text').textContent=saved.text;\n"
    "      $('memory-summary-copy').hidden=false;\n"
    "      const usage=saved.usage_available?`${saved.tokens_in} 输入 / ${saved.tokens_out} 输出 tokens`:'模型未提供 token 用量';\n"
    "      $('memory-summary-meta').textContent=`${new Date(saved.generated_ms).toLocaleString()} · ${saved.model} · 工作记忆 ${saved.working_count} 条 / 长期事实 ${saved.longterm_count} 条 · ${usage}`;\n"
    "    }\n"
    "    if(active)MEMORY_SUMMARY_TIMER=setTimeout(()=>{if(current==='memory')void loadMemorySummary();},1000);\n"
    "  }catch(e){if(status===$('memory-summary-status'))status.textContent=e.message+'；可点击刷新重试';}\n"
    "  finally{if(MEMORY_SUMMARY_FETCHING===status)MEMORY_SUMMARY_FETCHING=false;}\n"
    "}\n"
    "async function memorySummaryAction(method){\n"
    "  if(MEMORY_SUMMARY_ACTION)return;MEMORY_SUMMARY_ACTION=true;\n"
    "  const button=$('memory-summary-generate');if(button)button.disabled=true;\n"
    "  try{\n"
    "    const r=await call(method,'/v1/memory/summary',method==='POST'?{}:null);\n"
    "    if(r.status<200||r.status>=300)throw Error(r.obj?.error||'摘要请求失败');\n"
    "    await loadMemorySummary();\n"
    "  }catch(e){const status=$('memory-summary-status');if(status)status.textContent=e.message;}\n"
    "  finally{MEMORY_SUMMARY_ACTION=false;const currentButton=$('memory-summary-generate');if(currentButton && $('memory-summary-cancel')?.hidden)currentButton.disabled=false;}\n"
    "}\n"
    "function generateMemorySummary(){return memorySummaryAction('POST');}\n"
    "function cancelMemorySummary(){return memorySummaryAction('DELETE');}\n"
    "\n"
    "/* ================= Snapshots ================= */\n"
    "\n"
    "async function loadSnapshots(){\n"
    "  const r = await call('GET', '/v1/snapshots');\n"
    "  const el = $('snapshots-out'); if(el) renderJSON(r.obj, el);\n"
    "  renderSnapshotFiles(Array.isArray(r.obj) ? r.obj : []);\n"
    "  await loadSnapshotCfg();\n"
    "  loadJournal();\n"
    "}\n"
    "\n"
    "function renderSnapshotFiles(snapshots){\n"
    "  const box = $('snapshots-list'); if(!box) return;\n"
    "  box.replaceChildren();\n"
    "  if(!snapshots.length){ box.textContent = '暂无已提交的快照。'; updateSnapshotSelection(); return; }\n"
    "  snapshots.slice().reverse().forEach((snap, index) => {\n"
    "    const card = document.createElement('section'); card.className = 'card'; card.style.margin = '0';\n"
    "    const head = document.createElement('div'); head.className = 'card-head';\n"
    "    const title = document.createElement('b'); title.textContent = (index === 0 ? '最新 · ' : '') + (snap.id || 'snapshot');\n"
    "    const when = document.createElement('span'); when.className = 'muted'; when.textContent = snap.created || '';\n"
    "    head.append(title, when); card.append(head);\n"
    "    const paths = Array.isArray(snap.paths) ? snap.paths : [];\n"
    "    if(!paths.length){ const none = document.createElement('span'); none.className = 'muted'; none.textContent = '此快照没有文件记录。'; card.append(none); }\n"
    "    paths.forEach(path => {\n"
    "      const label = document.createElement('label'); label.className = 'row'; label.style.cssText = 'gap:8px;margin:6px 0;cursor:pointer;align-items:flex-start';\n"
    "      const cb = document.createElement('input'); cb.type = 'checkbox'; cb.className = 'snapshot-file'; cb.dataset.snapshot = snap.id || ''; cb.dataset.path = path; cb.onchange = updateSnapshotSelection;\n"
    "      const text = document.createElement('code'); text.textContent = path; text.style.overflowWrap = 'anywhere';\n"
    "      label.append(cb,text); card.append(label);\n"
    "    });\n"
    "    box.append(card);\n"
    "  });\n"
    "  updateSnapshotSelection();\n"
    "}\n"
    "function selectedSnapshotFiles(){ return [...document.querySelectorAll('.snapshot-file:checked')]; }\n"
    "function updateSnapshotSelection(){\n"
    "  const selected = selectedSnapshotFiles(), btn = $('snap-selected');\n"
    "  if(btn){ btn.disabled = !selected.length; btn.textContent = 'Rollback selected (' + selected.length + ')'; }\n"
    "}\n"
    "\n"
    "/* 任务历史（journal/checkpoint）：列出最近的任务终态记录，支持一键恢复 */\n"
    "async function loadJournal(){\n"
    "  const el = $('journal-list'); if(!el) return;\n"
    "  const r = await call('GET', '/v1/tasks/journal?limit=50');\n"
    "  const transitions = (r.obj && Array.isArray(r.obj)) ? r.obj : [];\n"
    "  const latest = new Map(); transitions.forEach(t=>latest.set(t.id,t));\n"
    "  const arr = Array.from(latest.values()).filter(t=>t.status!=='RUNNING' && t.status!=='QUEUED');\n"
    "  if(!arr.length){ el.textContent = '暂无已结束或中断的任务'; return; }\n"
    "  el.classList.remove('hint');\n"
    "  el.innerHTML = '';\n"
    "  const COL = {DONE:'var(--ok,#4ade80)',FAILED:'var(--danger,#f87171)',CANCELLED:'var(--muted)',TIMEOUT:'var(--warn,#fbbf24)',INTERRUPTED:'var(--warn,#fbbf24)'};\n"
    "  arr.slice().reverse().forEach(t => {\n"
    "    const row = document.createElement('div');\n"
    "    row.style.cssText = 'display:flex;align-items:center;gap:8px;padding:7px 10px;border:1px solid var(--border);border-radius:8px;margin-bottom:6px;font-size:12.5px';\n"
    "    const st = document.createElement('span');\n"
    "    st.style.cssText = 'color:' + (COL[t.status] || 'var(--muted)') + ';font-weight:600;min-width:72px';\n"
    "    st.textContent = t.status || '?';\n"
    "    const txt = document.createElement('span');\n"
    "    txt.style.cssText = 'flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap';\n"
    "    txt.textContent = '#' + t.id + ' ' + (t.input || '');\n"
    "    txt.title = t.input || '';\n"
    "    const when = document.createElement('span');\n"
    "    when.className = 'muted';\n"
    "    when.style.fontSize = '11px';\n"
    "    when.textContent = t.ts ? new Date(t.ts).toLocaleString() : '';\n"
    "    row.appendChild(st); row.appendChild(txt); row.appendChild(when);\n"
    "    const btn = document.createElement('button');\n"
    "    btn.className = 'sec sm'; btn.textContent = '恢复';\n"
    "    btn.onclick = async () => {\n"
    "      const rr = await call('POST', '/v1/tasks/' + t.id + '/resume', {});\n"
    "      if(rr.obj && rr.obj.id){ toast('已恢复为新任务 #' + rr.obj.id); loadJournal(); }\n"
    "      else toast('恢复失败：' + (rr.obj && rr.obj.error || rr.status));\n"
    "    };\n"
    "    row.appendChild(btn);\n"
    "    el.appendChild(row);\n"
    "  });\n"
    "}\n"
    "\n"
    "async function loadSnapshotCfg(){\n"
    "  const r = await call('GET', '/v1/config/snapshot');\n"
    "  const el = $('snap-max'); if(!el) return;\n"
    "  const v = (r.obj && typeof r.obj.max_file === 'number' && r.obj.max_file >= 0) ? r.obj.max_file : 67108864;\n"
    "  el.value = v === 0 ? 0 : Math.round(v / 1048576);\n"
    "  const st = $('snap-max-msg'); if(st) st.textContent = '';\n"
    "}\n"
    "\n"
    "async function saveSnapshotCfg(){\n"
    "  const el = $('snap-max'); if(!el) return;\n"
    "  const st = $('snap-max-msg');\n"
    "  const mb = parseInt(el.value, 10);\n"
    "  if(isNaN(mb) || mb < 0){ if(st) st.textContent = '请输入 ≥ 0 的整数（0 = 不限制）'; return; }\n"
    "  const r = await call('POST', '/v1/config/snapshot', {max_file: mb * 1048576});\n"
    "  if(st) st.textContent = (r.status === 200 && r.obj && r.obj.ok) ? '已保存' : ('失败: ' + (r.text || ('HTTP ' + r.status)).slice(0, 80));\n"
    "}\n"
    "\n"
    "/* ================= Agents ================= */\n"
    "\n"
    "let AGENTS = [];\n"
    "\n"
    "/* Fill the agent-creation model dropdown from the registered routes\n"
    " * (GET /v1/routes). Preserves the current selection when possible. */\n"
    "async function fillAgentModelSelect(){\n"
    "  const sel = $('agent-model'); if(!sel) return;\n"
    "  const keep=sel.value;\n"
    "  const r = await call('GET', '/v1/routes');\n"
    "  const routes = Array.isArray(r.obj) ? r.obj : [];\n"
    "  let html = '<option value=\"\">（当前激活模型）</option>';\n"
    "  routes.forEach(x => {\n"
    "    const val = (x.provider || '') + '|' + (x.model || '');\n"
    "    const label = (x.name || x.model || 'route') + '（' + (x.provider || '?') + ' / ' + (x.model || '?') + '）';\n"
    "    html += '<option value=\"' + esc(val) + '\">' + esc(label) + '</option>';\n"
    "  });\n"
    "  sel.innerHTML = html;\n"
    "  const has = Array.from(sel.options).some(o => o.value === keep);\n"
    "  sel.value = has ? keep : '';\n"
    "}\n"
    "\n"
    "async function loadAgents(){\n"
    "  renderAgentPresets();\n"
    "  const r = await call('GET', '/v1/agents');\n"
    "  const box = $('agents-out2');\n"
    "  if(!box) return;\n"
    "  const obj = (r.obj && typeof r.obj === 'object') ? r.obj : {};\n"
    "  AGENTS = Array.isArray(obj.agents) ? obj.agents : [];\n"
    "  flowAgentOptions();\n"
    "  /* 模型选项来自路由表：每个 agent 可单独换模型（PUT /v1/agents/<name>） */\n"
    "  const rr = await call('GET', '/v1/routes');\n"
    "  const routes = Array.isArray(rr.obj) ? rr.obj : [];\n"
    "  const modelOptions = (cur) => {\n"
    "    let h = '<option value=\"\">（当前激活模型）</option>';\n"
    "    let found = false;\n"
    "    routes.forEach(x => {\n"
    "      const v = (x.provider || '') + '|' + (x.model || '');\n"
    "      const label = (x.name || x.model || 'route') + '（' + (x.provider || '?') + ' / ' + (x.model || '?') + '）';\n"
    "      h += '<option value=\"' + esc(v) + '\"' + (v === cur ? ' selected' : '') + '>' + esc(label) + '</option>';\n"
    "      if(v === cur) found = true;\n"
    "    });\n"
    "    /* 存储的模型已被删除时保留显示，避免静默回退 */\n"
    "    if(cur && cur !== '|' && !found)\n"
    "      h += '<option value=\"' + esc(cur) + '\" selected>' + esc(cur.replace('|', ' / ')) + '（已删除的路由）</option>';\n"
    "    return h;\n"
    "  };\n"
    "  let html = '<div class=\"table-wrap\"><table><thead><tr><th>Agent</th><th>Role</th><th>Model</th><th>操作</th></tr></thead><tbody>';\n"
    "  if(!AGENTS.length) html += '<tr><td colspan=\"4\" class=\"muted\">（暂无 agent，先创建一个）</td></tr>';\n"
    "  AGENTS.forEach(a => {\n"
    "    const cur = (a.provider || '') + '|' + (a.model || '');\n"
    "    const hasModel = (a.provider || a.model) ? true : false;\n"
    "    html += '<tr><td>' + esc(a.name || '') + '</td><td>' + esc(a.role || '') + '</td>' +\n"
    "      '<td><select class=\"agent-model-sel\" style=\"max-width:240px\">' + modelOptions(hasModel ? cur : '') + '</select></td>' +\n"
    "      '<td><button class=\"sec sm\" onclick=\"agentSetModel(\\'' + esc(a.name || '') + '\\', this)\">保存模型</button> ' +\n"
    "      '<button class=\"sec sm danger\" onclick=\"agentDelete(\\'' + esc(a.name || '') + '\\')\">删除</button></td></tr>';\n"
    "  });\n"
    "  html += '</tbody></table></div>';\n"
    "  html += '<div class=\"hint\" style=\"margin-top:8px\">共享黑板 facts:</div><pre>' + esc(JSON.stringify(obj.facts || {}, null, 2)) + '</pre>';\n"
    "  box.innerHTML = html;\n"
    "  fillAgentModelSelect();\n"
    "}\n"
    "\n"
    "/* 修改指定 agent 使用的模型（PUT /v1/agents/<name>，空 = 回退当前激活模型） */\n"
    "async function agentSetModel(name, btn){\n"
    "  const tr = btn && btn.closest ? btn.closest('tr') : null;\n"
    "  const sel = tr ? tr.querySelector('select.agent-model-sel') : null;\n"
    "  if(!sel){ toast('未找到模型选择框'); return; }\n"
    "  const val = sel.value || '';\n"
    "  const i = val.indexOf('|');\n"
    "  const provider = i >= 0 ? val.slice(0, i) : '';\n"
    "  const model = i >= 0 ? val.slice(i + 1) : '';\n"
    "  const r = await call('PUT', '/v1/agents/' + encodeURIComponent(name), {provider, model});\n"
    "  if(r.status === 200) toast('已更新 ' + name + ' 的模型');\n"
    "  else toast('更新失败: ' + ((r.obj && r.obj.error) || r.text || ('HTTP ' + r.status)));\n"
    "}\n"
    "\n"
    "/* ================= 预置专业 Agent 角色 ================= */\n"
    "/* 常用角色的人设模板：点击填入创建表单，或按任务关键词「智能组队」批量注册 */\n"
    "const AGENT_PRESETS = [\n"
    "  {key:'architect', name:'architect', label:'🏗️ 架构设计', kw:['架构','设计','方案','选型','模块','拆分','结构','重构','技术路线'],\n"
    "   hint:'模块边界、接口与设计取舍', role:'你是资深软件架构师。先确认需求和约束，再交付可实施的模块边界、接口契约、数据流和关键取舍；需要文档时写入文件并检查内容，明确未验证的假设。'},\n"
    "  {key:'coder', name:'coder', label:'💻 代码开发', kw:['开发','编码','实现','写代码','功能','修复','bug','脚本','编程','交付'],\n"
    "   hint:'实现、边界处理与本地验证', role:'你是资深开发工程师。先定位现有实现，再完成真实代码改动；处理边界与异常路径，运行相关测试，最终给出修改文件、验证结果和剩余限制。不要用计划或伪代码代替交付。'},\n"
    "  {key:'reviewer', name:'reviewer', label:'🔍 代码检视', kw:['检视','审查','评审','review','质量','审计','走查','code review'],\n"
    "   hint:'正确性、安全与可复现证据', role:'你是资深代码审查员。阅读具体代码和调用链，重点检查正确性、边界条件、资源泄漏、并发和安全；每条问题给出文件位置、触发条件、影响与修复建议，避免无证据的泛泛评价。'},\n"
    "  {key:'tester', name:'tester', label:'🧪 测试', kw:['测试','用例','单测','test','qa','验证','回归','冒烟','自动化测试'],\n"
    "   hint:'覆盖正常、边界与失败路径', role:'你是资深测试工程师。设计并执行能发现缺陷的测试，覆盖正常、边界和失败路径；记录实际命令与结果。发现缺陷时提供复现步骤、预期与实际行为，并在修复后复测。'},\n"
    "  {key:'ppt', name:'ppt-expert', label:'📊 PPT专家', kw:['ppt','幻灯片','演示','汇报','slides','路演','宣讲','答辩'],\n"
    "   hint:'交付可打开的 .pptx 文件', role:'你是演示设计与制作专家。用户要求制作演示文稿时，必须实际生成可打开的 .pptx 文件，不能只给大纲或逐页文字。按受众组织叙事、控制每页信息量，优先使用 python-pptx 生成；按用户指定路径保存，未指定则保存到 deliverables/presentation.pptx。生成后重新打开文件核对页数、标题和文件大小，最终回复用反引号单独标出文件路径并给出页数；未生成时明确说明失败。'},\n"
    "  {key:'docs', name:'docs-writer', label:'📝 文档', kw:['文档','readme','说明','手册','注释','教程','guide','使用指南'],\n"
    "   hint:'准确文档与可运行示例', role:'你是资深技术文档工程师。以当前代码和配置为依据编写文档，直接修改目标文件；核对命令、路径、链接和示例，区分已实现与规划功能，并报告验证结果。'},\n"
    "  {key:'researcher', name:'researcher', label:'🔬 调研分析', kw:['调研','分析','调查','竞品','评估','对比','可行性','报告'],\n"
    "   hint:'来源、判断与可执行建议', role:'你是资深调研分析师。先核对资料来源，再给出结论、证据、限制与可执行建议；需要报告文件时实际写入并检查，清楚标识推断与未确认事实。'}\n"
    "];\n"
    "\n"
    "function renderAgentPresets(){\n"
    "  const box = $('agent-presets'); if(!box) return;\n"
    "  if(box.dataset.init) return;\n"
    "  box.dataset.init = '1';\n"
    "  box.innerHTML = AGENT_PRESETS.map(p =>\n"
    "    '<button class=\"agent-preset\" type=\"button\" onclick=\"agentPresetFill(\\'' + p.key + '\\')\" title=\"' + esc(p.role) + '\"><strong>' + esc(p.label) + '</strong><span>' + esc(p.hint) + '</span></button>').join('');\n"
    "}\n"
    "\n"
    "function agentPresetFill(key){\n"
    "  const p = AGENT_PRESETS.find(x => x.key === key); if(!p) return;\n"
    "  $('agent-name').value = p.name;\n"
    "  $('agent-role').value = p.role;\n"
    "  $('agent-role').focus();\n"
    "  if($('agent-stat')) $('agent-stat').textContent = '已填入「' + p.label + '」人设，可直接 Add';\n"
    "}\n"
    "\n"
    "/* 按任务描述匹配角色组合：命中任一关键词即入选；全不命中兜底给 coder */\n"
    "function agentMatchPresets(text){\n"
    "  const t = (text || '').toLowerCase();\n"
    "  const hits = AGENT_PRESETS.filter(p => p.kw.some(k => t.includes(k.toLowerCase())));\n"
    "  return hits.length ? hits : [AGENT_PRESETS.find(p => p.key === 'coder')];\n"
    "}\n"
    "\n"
    "async function agentTeamCompose(){\n"
    "  const task = $('agent-team-task').value.trim();\n"
    "  const st = $('agent-stat');\n"
    "  if(!task){ if(st) st.textContent = '先输入任务描述再智能组队'; return; }\n"
    "  const picks = agentMatchPresets(task);\n"
    "  const have = new Set(AGENTS.map(a => a.name));\n"
    "  const todo = picks.filter(p => !have.has(p.name));\n"
    "  const skipped = picks.filter(p => have.has(p.name)).map(p => p.name);\n"
    "  if(skipped.length) toast('已跳过已存在的 agent：' + skipped.join(', '));\n"
    "  if(!todo.length){ if(st) st.textContent = '匹配到的角色均已存在'; return; }\n"
    "  if(st) st.textContent = '创建中… ' + todo.map(p => p.name).join(', ');\n"
    "  for(const p of todo){\n"
    "    const r = await call('POST', '/v1/agents', {name: p.name, role: p.role});\n"
    "    if(r.status >= 300){\n"
    "      if(st) st.textContent = '创建 ' + p.name + ' 失败: ' + ((r.obj && r.obj.error) || r.status);\n"
    "      return;\n"
    "    }\n"
    "  }\n"
    "  if(st) st.textContent = '✔ 智能组队完成（' + todo.length + ' 个 agent）';\n"
    "  toast('🎯 按任务匹配创建：' + todo.map(p => p.label).join(' / '));\n"
    "  loadAgents();\n"
    "}\n"
    "\n"
    "function agentAdd(){\n"
    "  const name = $('agent-name').value.trim();\n"
    "  const role = $('agent-role').value.trim();\n"
    "  const st = $('agent-stat');\n"
    "  if(!name){ if(st) st.textContent = '需要 name'; return; }\n"
    "  const body = {name, role};\n"
    "  /* dropdown value is \"provider|model\" (\"\" = current active model) */\n"
    "  const pick = $('agent-model').value;\n"
    "  if(pick){\n"
    "    const sep = pick.indexOf('|');\n"
    "    const provider = sep >= 0 ? pick.slice(0, sep) : pick;\n"
    "    const model = sep >= 0 ? pick.slice(sep + 1) : '';\n"
    "    if(provider) body.provider = provider;\n"
    "    if(model) body.model = model;\n"
    "  }\n"
    "  call('POST', '/v1/agents', body).then(r => {\n"
    "    if(st) st.textContent = (r.status < 300) ? '✔ 已创建' : ((r.obj && r.obj.error) ? 'error: ' + r.obj.error : 'error ' + r.status);\n"
    "    if(r.status < 300){\n"
    "      $('agent-name').value = ''; $('agent-role').value = ''; $('agent-model').value = '';\n"
    "      loadAgents();\n"
    "      if(st) st.textContent = '✔ 已创建，可在下方 Flow 自动编排';\n"
    "      toast('agent「' + name + '」已创建，试试 Flow 自动编排');\n"
    "    }\n"
    "  });\n"
    "}\n"
    "\n"
    "async function agentDelete(name){\n"
    "  if(!name) return;\n"
    "  if(!confirm('删除 agent \"' + name + '\"？')) return;\n"
    "  await call('DELETE', '/v1/agents/' + encodeURIComponent(name));\n"
    "  loadAgents();\n"
    "}\n"
    "\n"
    "function agentPost(){\n"
    "  const name = $('agent-post-name').value.trim();\n"
    "  const key = $('agent-post-key').value.trim();\n"
    "  const val = $('agent-post-val').value.trim();\n"
    "  if(!name || !key || !val) return;\n"
    "  call('POST', '/v1/agents/' + encodeURIComponent(name) + '/post', {key, value: val}).then(r => {\n"
    "    if(r.obj && r.obj.ok){ $('agent-post-key').value = ''; $('agent-post-val').value = ''; loadAgents(); }\n"
    "  });\n"
    "}\n"
    "\n"
    "/* ================= MCP ================= */\n"
    "\n"
    "async function loadLocalDirs(){\n"
    "  const r = await call('GET', '/v1/local/dirs');\n"
    "  if(r.status >= 300 || !r.obj) return;\n"
    "  if($('local-skills-dir')) $('local-skills-dir').textContent = r.obj.skills || 'state/skills';\n"
    "  if($('local-mcp-dir')) $('local-mcp-dir').textContent = r.obj.mcp || 'state/mcp';\n"
    "}\n"
    "\n"
    "async function reloadLocalSkills(){\n"
    "  const status = $('local-skills-status');\n"
    "  if(status) status.textContent = '正在扫描本地技能…';\n"
    "  const r = await call('POST', '/v1/skills/reload', {});\n"
    "  if(status) status.textContent = r.obj?.ok ? ('已加载 ' + r.obj.loaded + ' 个本地技能') : '加载失败，请检查目录和文件格式';\n"
    "  if(r.obj?.ok) loadSkillsMarket();\n"
    "}\n"
    "\n"
    "let MCP_CONNS = [];\n"
    "\n"
    "async function loadMcp(){\n"
    "  const r = await call('GET', '/v1/mcp');\n"
    "  const box = $('mcp-list');\n"
    "  if(!box) return;\n"
    "  MCP_CONNS = Array.isArray(r.obj) ? r.obj : [];\n"
    "  if(!MCP_CONNS.length){\n"
    "    box.innerHTML = '<span class=\"muted\" style=\"font-size:12px\">（暂无连接，先添加一个）</span>';\n"
    "  } else {\n"
    "    box.innerHTML = '<div class=\"table-wrap\"><table><thead><tr><th>Name</th><th>Transport</th><th>Target</th><th>Tools</th><th>Token</th><th></th></tr></thead><tbody>' +\n"
    "      MCP_CONNS.map((c, i) => '<tr><td>' + esc(c.name) + '</td><td>' + esc(c.transport || 'http') + '</td>' +\n"
    "        '<td class=\"muted\">' + esc((c.transport === 'stdio') ? ((c.command || '') + ' ' + (c.args || '')) : c.url) + '</td>' +\n"
    "        '<td>' + (typeof c.tools === 'number' ? c.tools : '—') + '</td>' +\n"
    "        '<td>' + (c.has_token ? '已设置' : '—') + '</td>' +\n"
    "        '<td><button class=\"sec sm\" onclick=\"mcpConnTest(' + i + ')\">测试</button> ' +\n"
    "        '<button class=\"sec sm danger\" onclick=\"mcpDelete(' + i + ')\">Delete</button> ' +\n"
    "        '<button class=\"sec sm\" onclick=\"mcpSync()\">Sync</button></td></tr>').join('') +\n"
    "      '</tbody></table></div>';\n"
    "  }\n"
    "  loadMcpPlaza();\n"
    "}\n"
    "\n"
    "let MCP_PLAZA = [];\n"
    "\n"
    "async function loadMcpPlaza(){\n"
    "  const box = $('mcp-plaza');\n"
    "  if(!box) return;\n"
    "  const r = await call('GET', '/v1/catalog/mcp');\n"
    "  MCP_PLAZA = Array.isArray(r.obj) ? r.obj : [];\n"
    "  renderMcpPlaza();\n"
    "}\n"
    "\n"
    "/* 按搜索框关键字过滤渲染（名称/描述/传输类型） */\n"
    "function renderMcpPlaza(){\n"
    "  const box = $('mcp-plaza');\n"
    "  if(!box) return;\n"
    "  const q = (($('mcp-search') || {}).value || '').trim().toLowerCase();\n"
    "  const list = !q ? MCP_PLAZA : MCP_PLAZA.filter(m =>\n"
    "    [m.name, m.description, m.transport, m.url, m.command, m.repo]\n"
    "      .some(f => f && String(f).toLowerCase().includes(q)));\n"
    "  if(!MCP_PLAZA.length){ box.innerHTML = '<span class=\"muted\" style=\"font-size:12px\">（目录为空）</span>'; return; }\n"
    "  if(!list.length){ box.innerHTML = '<span class=\"muted\" style=\"font-size:12px\">（无匹配 \"' + esc(q) + '\" 的 MCP 服务器）</span>'; return; }\n"
    "  box.innerHTML = list.map((m) => {\n"
    "    const i = MCP_PLAZA.indexOf(m);\n"
    "    const isRef = m.transport === 'reference';\n"
    "    const target = isRef ? esc(m.repo || '')\n"
    "      : esc(m.transport === 'stdio' ? ((m.command || '') + ' ' + (m.args || '')) : (m.url || ''));\n"
    "    let btns = '';\n"
    "    if(isRef){\n"
    "      btns = '<a class=\"sec sm\" href=\"' + esc(m.repo) + '\" target=\"_blank\" rel=\"noopener\">查看仓库</a>';\n"
    "    } else {\n"
    "      btns = '<button class=\"sec sm\" onclick=\"mcpPlazaTest(' + i + ')\">测试</button> ' +\n"
    "             '<button class=\"sec sm\" onclick=\"mcpPlazaUse(' + i + ')\">添加连接</button>';\n"
    "    }\n"
    "    return '<div class=\"item\"><h3>' + esc(m.name) + (m.repo ? ' <a class=\"tag\" href=\"' + esc(m.repo) + '\" target=\"_blank\" rel=\"noopener\">GitHub</a>' : '') + (isRef ? ' <span class=\"tag\">参考仓库</span>' : '') + '</h3><p>' + esc(m.description) + '</p>' +\n"
    "      '<div class=\"url\">' + target + '</div>' +\n"
    "      '<div class=\"hint\">' + (isRef ? '' : (m.needs_local ? '需本地运行 · ' : '')) + esc(m.key_hint || '') + '</div>' +\n"
    "      btns + '</div>';\n"
    "  }).join('');\n"
    "}\n"
    "\n"
    "async function mcpPlazaTest(i){\n"
    "  const m = MCP_PLAZA[i]; if(!m) return;\n"
    "  if(m.transport === 'reference'){ toast('参考仓库条目无需测试，请到仓库查看'); return; }\n"
    "  toast('测试 MCP 连接 ' + m.id + ' …');\n"
    "  const body = {transport: m.transport || 'http'};\n"
    "  if(body.transport === 'stdio'){ body.command = m.command || ''; body.args = m.args || ''; }\n"
    "  else body.url = m.url;\n"
    "  if(m.needs_token && !body.token){\n"
    "    const tok = prompt('该 MCP 服务器需要凭据，请输入 ' + (m.key_hint || 'token') + '（留空则不带 token 测试）：');\n"
    "    if(tok && tok.trim()) body.token = tok.trim();\n"
    "  }\n"
    "  const r = await call('POST', '/v1/mcp/test', body);\n"
    "  if(r.obj && r.obj.ok) toast('✔ 连接成功：' + (r.obj.count || 0) + ' 个工具');\n"
    "  else toast('✘ 测试失败: ' + ((r.obj && r.obj.error) || ('HTTP ' + r.status)));\n"
    "}\n"
    "\n"
    "async function mcpPlazaUse(i){\n"
    "  const m = MCP_PLAZA[i]; if(!m) return;\n"
    "  toast('添加 MCP 连接 ' + m.id + ' …');\n"
    "  const body = {name: m.id, transport: m.transport || 'http'};\n"
    "  if(m.transport === 'stdio'){\n"
    "    body.command = m.command || '';\n"
    "    body.args = m.args || '';\n"
    "    if(!body.command){ toast('该条目缺少 stdio 命令'); return; }\n"
    "  } else {\n"
    "    body.url = m.url;\n"
    "  }\n"
    "  if(m.token && m.token_hint) body.token = m.token;\n"
    "  if(m.needs_token && !body.token){\n"
    "    const tok = prompt('该 MCP 服务器需要凭据，请输入 ' + (m.key_hint || 'token') + '：');\n"
    "    if(!tok){ toast('已取消（未填 token）'); return; }\n"
    "    body.token = tok.trim();\n"
    "    if(!body.token){ toast('已取消（未填 token）'); return; }\n"
    "  }\n"
    "  const r = await call('POST', '/v1/mcp', body);\n"
    "  if(r.status < 300) toast('✔ 已添加连接 ' + m.id);\n"
    "  else toast('添加失败: ' + ((r.obj && r.obj.error) || ('HTTP ' + r.status)));\n"
    "  loadMcp();\n"
    "}\n"
    "\n"
    "function mcpAdd(){\n"
    "  const name = $('mcp-name').value.trim();\n"
    "  const transport = $('mcp-transport') ? $('mcp-transport').value : 'http';\n"
    "  const url = $('mcp-url').value.trim();\n"
    "  const command = $('mcp-command') ? $('mcp-command').value.trim() : '';\n"
    "  const args = $('mcp-args') ? $('mcp-args').value.trim() : '';\n"
    "  const token = $('mcp-token').value.trim();\n"
    "  const st = $('mcp-stat');\n"
    "  if(!name){ if(st) st.textContent = '需要 name'; return; }\n"
    "  if(transport === 'http' && !url){ if(st) st.textContent = 'http 传输需要 url'; return; }\n"
    "  if(transport === 'stdio' && !command){ if(st) st.textContent = 'stdio 传输需要 command'; return; }\n"
    "  const body = {name, transport};\n"
    "  if(transport === 'http') body.url = url; else { body.command = command; if(args) body.args = args; }\n"
    "  if(token) body.token = token;\n"
    "  call('POST', '/v1/mcp', body).then(r => {\n"
    "    if(st) st.textContent = (r.status < 300) ? '✔ 已添加' : ((r.obj && r.obj.error) ? 'error: ' + r.obj.error : 'error ' + r.status);\n"
    "    if(r.status < 300){ $('mcp-name').value = ''; $('mcp-url').value = ''; $('mcp-command').value = ''; $('mcp-args').value = ''; $('mcp-token').value = ''; loadMcp(); }\n"
    "  });\n"
    "}\n"
    "\n"
    "async function mcpConnTest(i){\n"
    "  const c = MCP_CONNS[i]; if(!c) return;\n"
    "  toast('测试 MCP 连接 ' + c.name + ' …');\n"
    "  const body = {transport: c.transport || 'http'};\n"
    "  if(body.transport === 'stdio'){ body.command = c.command || ''; body.args = c.args || ''; }\n"
    "  else body.url = c.url;\n"
    "  const r = await call('POST', '/v1/mcp/test', body);\n"
    "  if(r.obj && r.obj.ok) toast('✔ ' + c.name + ' 连接成功：' + (r.obj.count || 0) + ' 个工具');\n"
    "  else toast('✘ ' + c.name + ' 测试失败: ' + ((r.obj && r.obj.error) || ('HTTP ' + r.status)));\n"
    "}\n"
    "\n"
    "async function mcpSync(){\n"
    "  const status = $('local-mcp-status');\n"
    "  if(status) status.textContent = '正在扫描配置并发现工具…';\n"
    "  const r = await call('POST', '/v1/mcp/sync', {});\n"
    "  if(r.status < 300){\n"
    "    const message = '已加载 ' + (r.obj?.loaded || 0) + ' 个本地配置，发现 ' + (r.obj?.registered || 0) + ' 个工具';\n"
    "    if(status) status.textContent = message;\n"
    "    toast(message);\n"
    "  } else {\n"
    "    if(status) status.textContent = '加载失败';\n"
    "    toast('同步失败: HTTP ' + r.status);\n"
    "  }\n"
    "  loadMcp();\n"
    "}\n"
    "\n"
    "function mcpDelete(i){\n"
    "  const c = MCP_CONNS[i]; if(!c) return;\n"
    "  call('DELETE', '/v1/mcp/' + encodeURIComponent(c.name)).then(() => loadMcp());\n"
    "}\n"
    "\n"
    "async function loadDashboard(){\n"
    "  const [ag, mem, plg, im, llm, usg] = await Promise.all([\n"
    "    call('GET', '/v1/agents'),\n"
    "    call('GET', '/v1/memory'),\n"
    "    call('GET', '/v1/plugins'),\n"
    "    call('GET', '/v1/im/sessions'),\n"
    "    call('GET', '/v1/config/llm'),\n"
    "    call('GET', '/v1/usage'),\n"
    "  ]);\n"
    "  const st = $('dashStats');\n"
    "  if(st){\n"
    "    const agents  = Array.isArray(ag.obj) ? ag.obj.length : (ag.obj && ag.obj.agents ? ag.obj.agents.length : 0);\n"
    "    const wmem    = (mem.obj && Array.isArray(mem.obj.working)) ? mem.obj.working.length : 0;\n"
    "    const plugins = (plg.obj && plg.obj.plugins && Array.isArray(plg.obj.plugins)) ? plg.obj.plugins.length\n"
    "                  : (Array.isArray(plg.obj) ? plg.obj.length : 0);\n"
    "    const ims     = (im.obj && im.obj.total_messages) ? im.obj.total_messages : 0;\n"
    "    const provider = (llm.obj && llm.obj.provider) ? llm.obj.provider : '?';\n"
    "    const tot = usg.obj && usg.obj.total ? usg.obj.total : {prompt:0, completion:0};\n"
    "    const cells = st.querySelectorAll('.stat .num');\n"
    "    if(cells.length >= 7){\n"
    "      cells[0].textContent = '3.1.1';\n"
    "      cells[1].textContent = provider;\n"
    "      cells[2].textContent = agents;\n"
    "      cells[3].textContent = wmem;\n"
    "      cells[4].textContent = plugins;\n"
    "      cells[5].textContent = ims;\n"
    "      cells[6].textContent = usg.obj && usg.obj.usage_available ? (tot.prompt + tot.completion + (tot.reasoning || 0)).toLocaleString() : '未提供';\n"
    "      cells[6].title = usg.obj && usg.obj.usage_available ? '输入 ' + (tot.prompt || 0).toLocaleString() + ' / 输出 ' + ((tot.completion || 0) + (tot.reasoning || 0)).toLocaleString() : '模型后端尚未提供 Token 用量';\n"
    "    }\n"
    "  }\n"
    "  /* 按模型的 token 用量明细（/v1/usage：reasoning 每轮把增量记入账本） */\n"
    "  const tk = $('dash-tokens');\n"
    "  if(tk){\n"
    "    const models = (usg.obj && usg.obj.models) ? usg.obj.models : {};\n"
    "    const keys = Object.keys(models);\n"
    "    tk.innerHTML = keys.length\n"
    "      ? keys.map(k => {\n"
    "          const m = models[k];\n"
    "          return '<div class=\"item\"><b>' + esc(k) + '</b>' +\n"
    "            '<div class=\"hint\">输入 ' + (m.prompt || 0).toLocaleString() + ' · 输出 ' + (m.completion || 0).toLocaleString() +\n"
    "            ' · 调用 ' + (m.calls || 0) + ' 次</div></div>';\n"
    "        }).join('')\n"
    "      : '<span class=\"muted\">（尚无用量记录 — 完成一次对话后显示）</span>';\n"
    "  }\n"
    "  if(tk && Array.isArray(usg.obj?.breakdown) && usg.obj.breakdown.length){\n"
    "    const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent='按天 / 任务 / 模型统计（UTC，已持久化）';details.append(summary);\n"
    "    for(const row of usg.obj.breakdown){const line=document.createElement('div');line.className='hint';line.textContent=`${row.day} · 任务 #${row.task_id} · ${row.model} · 输入 ${row.prompt} / 可见输出 ${row.completion} / 推理 ${row.reasoning} · ${row.calls} 次`;details.append(line);}tk.append(details);\n"
    "  }\n"
    "  const el = $('dash-out');\n"
    "  if(el){\n"
    "    const payload = {\n"
    "      agents: ag.obj, memory: mem.obj, plugins: plg.obj, im: im.obj\n"
    "    };\n"
    "    renderJSON(payload, el);\n"
    "  }\n"
    "}\n"
    "\n"
    "async function rollback(){\n"
    "  const r = await call('POST', '/v1/snapshots/rollback');\n"
    "  renderJSON(r.obj, $('snapshots-out'));\n"
    "  load('snapshots');\n"
    "}\n"
    "async function rollbackSelected(){\n"
    "  const selected = selectedSnapshotFiles(); if(!selected.length) return;\n"
    "  const groups = new Map();\n"
    "  selected.forEach(cb => { const id = cb.dataset.snapshot; if(!groups.has(id)) groups.set(id, []); groups.get(id).push(cb.dataset.path); });\n"
    "  for(const [id,paths] of groups){\n"
    "    const r = await call('POST', '/v1/snapshots/rollback', {id,paths});\n"
    "    if(r.status !== 200 || !r.obj?.ok){ toast('回滚失败：' + (r.obj?.error || r.status)); return; }\n"
    "  }\n"
    "  toast('已回滚 ' + selected.length + ' 个已选文件');\n"
    "  await loadSnapshots();\n"
    "}\n"
    "\n"
    "async function runSkill(){\n"
    "  const name = $('skillname').value.trim();\n"
    "  if(!name) return;\n"
    "  const r = await call('POST', '/v1/skills/run', {name});\n"
    "  if($('skills-out')) $('skills-out').style.display = 'block';\n"
    "  renderJSON(r.obj, $('skills-out'));\n"
    "}\n"
    "\n"
    "/* 已注册技能列表（供顶部搜索框过滤） */\n"
    "let SKILLS_LIST = null;\n"
    "\n"
    "function marketIcon(name){\n"
    "  const label = Array.from(String(name || '?').replace(/^[^\\p{L}\\p{N}]+/u, ''))[0] || '?';\n"
    "  let hash = 0;\n"
    "  for(const ch of String(name || '')) hash = (hash * 31 + ch.codePointAt(0)) >>> 0;\n"
    "  return '<span class=\"market-icon\" data-tone=\"' + (hash % 6) + '\" aria-hidden=\"true\">' + esc(label.toUpperCase()) + '</span>';\n"
    "}\n"
    "function marketHit(x, q){\n"
    "  return !q || [x.name, x.id, x.description, x.kind].some(v => v && String(v).toLowerCase().includes(q));\n"
    "}\n"
    "function marketUrl(raw){\n"
    "  try { const u = new URL(String(raw)); return (u.protocol === 'https:' || u.protocol === 'http:') ? u.href : '#'; }\n"
    "  catch { return '#'; }\n"
    "}\n"
    "\n"
    "function renderRegisteredSkills(){\n"
    "  if(!SKILLS_LIST) return;\n"
    "  const q = skillQ();\n"
    "  const list = SKILLS_LIST.filter(s => marketHit(s, q));\n"
    "  const box = $('skills-list');\n"
    "  if(box) box.innerHTML = list.length ? list.map(s =>\n"
    "    '<button class=\"market-installed-item\" type=\"button\" title=\"' + esc(s.name) + '\" aria-label=\"查看技能 ' + esc(s.name) + '\" onclick=\"selectInstalledSkill(' + SKILLS_LIST.indexOf(s) + ')\">' + marketIcon(s.name) + '<span class=\"market-installed-name\">' + esc(s.name) + '</span></button>').join('') : '<div class=\"market-empty\">' + (q ? '没有匹配的已安装技能' : '暂无已安装技能') + '</div>';\n"
    "  if($('skills-installed-count')) $('skills-installed-count').textContent = SKILLS_LIST.length + ' 个技能';\n"
    "  if($('skills-out')) renderJSON(list, $('skills-out'));\n"
    "}\n"
    "\n"
    "function selectInstalledSkill(i){\n"
    "  const s = (SKILLS_LIST || [])[i], box = $('skill-detail'); if(!s || !box) return;\n"
    "  const owned = (SKILL_MARKET.installed || []).some(x => x.name === s.name);\n"
    "  box.hidden = false;\n"
    "  box.innerHTML = '<h3>' + esc(s.name) + '</h3><p>' + esc(s.description || '暂无描述') + '</p><div class=\"row\"><span class=\"tag\">' + esc(s.kind || 'skill') + '</span> <button class=\"sec sm\" type=\"button\" onclick=\"runInstalledSkill(' + i + ')\">运行</button>' +\n"
    "    (owned ? ' <button class=\"sec sm danger\" type=\"button\" onclick=\"deleteInstalledSkill(' + i + ')\">删除</button>' : '') + '</div>';\n"
    "}\n"
    "function runInstalledSkill(i){\n"
    "  const s = (SKILLS_LIST || [])[i]; if(!s) return;\n"
    "  $('skillname').value = s.name;\n"
    "  $('skillname').closest('details').open = true;\n"
    "  runSkill();\n"
    "}\n"
    "function deleteInstalledSkill(i){\n"
    "  const s = (SKILLS_LIST || [])[i]; if(s) deleteSkill(s.name);\n"
    "  if($('skill-detail')) $('skill-detail').hidden = true;\n"
    "}\n"
    "\n"
    "function toggleSkillRaw(){\n"
    "  const out = $('skills-out'); if(!out) return;\n"
    "  out.style.display = out.style.display === 'none' ? 'block' : 'none';\n"
    "}\n"
    "\n"
    "/* ================= 技能广场（精选目录） ================= */\n"
    "// Keep disclosure choices when catalogs refresh; move nodes to retain handlers/forms.\n"
    "const MARKET_FOLDS = new Map();\n"
    "function marketFold(key, title, nodes){\n"
    "  const fold=document.createElement('details'); fold.className='market-fold'; fold.dataset.foldKey=key;\n"
    "  fold.open=MARKET_FOLDS.get(key) || false;\n"
    "  const summary=document.createElement('summary'); summary.textContent=title;\n"
    "  const body=document.createElement('div'); body.className='market-fold-body'; body.append(...nodes);\n"
    "  fold.append(summary,body);\n"
    "  fold.addEventListener('toggle',()=>MARKET_FOLDS.set(key,fold.open));\n"
    "  return fold;\n"
    "}\n"
    "function foldMarketGroups(box){\n"
    "  const nodes=[...box.childNodes]; let fold=null, grid=null;\n"
    "  nodes.forEach(node=>{\n"
    "    if(node.nodeType===1 && (node.classList.contains('sub') || node.tagName==='H3')){\n"
    "      const title=node.textContent;\n"
    "      fold=marketFold(box.id+':'+title,title,[]); node.replaceWith(fold);\n"
    "      grid=document.createElement('div'); grid.className=node.tagName==='H3' ? 'market-form-stack' : 'market-source-grid'; fold.lastChild.append(grid);\n"
    "    } else if(fold){ grid.append(node); }\n"
    "  });\n"
    "}\n"
    "function setMarketHTML(box, html){\n"
    "  box.querySelectorAll('[data-fold-key]').forEach(f=>MARKET_FOLDS.set(f.dataset.foldKey,f.open));\n"
    "  box.innerHTML=html; foldMarketGroups(box);\n"
    "}\n"
    "function enhanceMarketAdvanced(root){\n"
    "  root.querySelectorAll('.market-advanced>.card').forEach((card,i)=>{\n"
    "    const title=card.querySelector('h2'); if(!title)return;\n"
    "    const label=title.textContent.replace(/^⭐\\s*/,''); title.remove();\n"
    "    const fold=marketFold(current+':advanced:'+i,label,[...card.childNodes]); card.replaceWith(fold);\n"
    "    // Publication forms are a separate disclosure within their management section.\n"
    "    foldMarketGroups(fold.lastChild);\n"
    "  });\n"
    "}\n"
    "let SKILL_CATALOG = [];\n"
    "let GH_SKILLS = [];\n"
    "\n"
    "async function loadSkillsCatalog(){\n"
    "  const box = $('skill-catalog'); if(!box) return;\n"
    "  const r = await call('GET', '/v1/catalog/skills');\n"
    "  SKILL_CATALOG = Array.isArray(r.obj) ? r.obj : [];\n"
    "  renderSkillCatalog();\n"
    "  renderSkillDiscovery();\n"
    "  loadGhSkills();\n"
    "  loadSkillhubList();\n"
    "}\n"
    "\n"
    "/* 搜索过滤（技能广场全部目录共用一个关键字） */\n"
    "function skillQ(){\n"
    "  return (($('skill-search') || {}).value || '').trim().toLowerCase();\n"
    "}\n"
    "function skillHit(x, fields){\n"
    "  const q = skillQ();\n"
    "  if(!q) return true;\n"
    "  return fields.some(f => f && String(f).toLowerCase().includes(q));\n"
    "}\n"
    "function renderSkillCatalog(){\n"
    "  const box = $('skill-catalog'); if(!box) return;\n"
    "  const run = [], refs = [];\n"
    "  SKILL_CATALOG.forEach(x => (x.type === 'reference' ? refs : run).push(x));\n"
    "  const runF = run.filter(x => skillHit(x, [x.id, x.description, x.kind]));\n"
    "  const refsF = refs.filter(x => skillHit(x, [x.name, x.description, x.source]));\n"
    "  let html = '<div class=\"sub\">可安装技能（安装 → 测试运行）</div>' +\n"
    "    (runF.length ? runF.map(x => {\n"
    "      const i = SKILL_CATALOG.indexOf(x);\n"
    "      return '<div class=\"item\"><b>' + esc(x.id) + '</b> <span class=\"muted\">' + esc(x.kind) + '</span>' +\n"
    "        '<div class=\"hint\">' + esc(x.description || '') + '</div>' +\n"
    "        '<button class=\"sec sm\" onclick=\"catalogSkillTest(' + i + ')\">测试</button> ' +\n"
    "        '<button class=\"sec sm\" onclick=\"catalogSkillInstall(' + i + ')\">安装</button></div>';\n"
    "    }).join('') : '<span class=\"muted\">（空）</span>');\n"
    "  html += '<div class=\"sub\">参考仓库</div>' +\n"
    "    (refsF.length ? refsF.map(x =>\n"
    "      '<div class=\"item\"><b><a href=\"' + esc(x.source) + '\" target=\"_blank\" rel=\"noopener\">' + esc(x.name) + '</a></b> <span class=\"tag\">参考仓库</span>' +\n"
    "      '<div class=\"hint\">' + esc(x.description || '') + '</div>' +\n"
    "      '<a class=\"sec sm\" href=\"' + esc(x.source) + '\" target=\"_blank\" rel=\"noopener\">查看仓库</a></div>').join('')\n"
    "      : '<span class=\"muted\">（空）</span>');\n"
    "  setMarketHTML(box, html);\n"
    "}\n"
    "\n"
    "/* 搜索框输入时统一重渲染：已注册技能 + 精选目录实时过滤；\n"
    " * SkillHub 市场 + GitHub 全网搜索走网络，防抖 400ms 后按关键字重新拉取 */\n"
    "let SKH_Q_LAST = '';   /* 缓存列表对应的关键字（'' = 默认首页） */\n"
    "let SKH_TIMER = null;\n"
    "function renderSkillCatalogs(){\n"
    "  clearTimeout(SKH_TIMER);\n"
    "  renderRegisteredSkills();\n"
    "  renderSkillCatalog();\n"
    "  renderSkillDiscovery();\n"
    "  if(GH_SKILLS.length) renderGhSkills();\n"
    "  const q = skillQ();\n"
    "  if(!q){ loadSkillhubList(); githubSearchOnline(); return; }\n"
    "  if(q !== SKH_Q_LAST){\n"
    "    SKH_TIMER = setTimeout(onlineSkillSearch, 400);\n"
    "  } else if(SKH_SKILLS.length || SKH_Q_LAST){\n"
    "    renderSkhSkills();\n"
    "  }\n"
    "}\n"
    "\n"
    "/* 联网搜索：SkillHub 市场全量过滤 + GitHub 全网仓库搜索 */\n"
    "function onlineSkillSearch(){\n"
    "  loadSkillhubList();\n"
    "  githubSearchOnline();\n"
    "}\n"
    "\n"
    "/* GitHub 仓库真实技能：按仓库分组折叠展示，安装时后端实时拉取文件原文 */\n"
    "const GH_REPO_LABELS = {\n"
    "  'fabric': '⭐ Fabric（danielmiessler/fabric 提示词技能）',\n"
    "  'anthropics': 'Anthropic 官方技能库（anthropics/skills）',\n"
    "  'cursorrules': 'CursorRules 规则库（PatrickJS/awesome-cursorrules）'\n"
    "};\n"
    "\n"
    "async function loadGhSkills(){\n"
    "  const box = $('gh-skill-catalog'); if(!box) return;\n"
    "  box.innerHTML = '<span class=\"muted\">加载中…</span>';\n"
    "  const r = await call('GET', '/v1/catalog/github-skills');\n"
    "  GH_SKILLS = Array.isArray(r.obj) ? r.obj : [];\n"
    "  renderGhSkills();\n"
    "}\n"
    "\n"
    "/* GitHub 全网在线搜索：实时调 GitHub search API 找技能仓库（后端代理） */\n"
    "let GH_SEARCH_LAST = [];\n"
    "\n"
    "async function githubSearchOnline(){\n"
    "  const box = $('gh-online-catalog'); if(!box) return;\n"
    "  const q = skillQ();\n"
    "  if(!q){ box.innerHTML = '<span class=\"muted\">（输入关键字在线搜索 GitHub 技能仓库）</span>'; return; }\n"
    "  box.innerHTML = '<span class=\"muted\">🌐 正在 GitHub 全网搜索「' + esc(q) + '」…</span>';\n"
    "  /* issue #20: 后端把搜索放后台线程，这里轮询直到结果就绪，\n"
    "   * 不再长时间占住单线程服务器把其他面板全部卡成「加载中」 */\n"
    "  let r = null;\n"
    "  for(let i = 0; i < 60; i++){\n"
    "    r = await call('GET', '/v1/catalog/github-search?q=' + encodeURIComponent(q));\n"
    "    if(r.obj && r.obj.pending){ await new Promise(res => setTimeout(res, 700)); continue; }\n"
    "    break;\n"
    "  }\n"
    "  if(!r || (r.obj && r.obj.pending)){ box.innerHTML = '<span class=\"muted\">（搜索超时，请重试）</span>'; return; }\n"
    "  if(r.status >= 400){\n"
    "    box.innerHTML = '<span class=\"muted\">（搜索失败：' + esc((r.obj && r.obj.error) || ('HTTP ' + r.status)) + '）</span>';\n"
    "    return;\n"
    "  }\n"
    "  const list = Array.isArray(r.obj) ? r.obj : [];\n"
    "  GH_SEARCH_LAST = list;\n"
    "  if(!list.length){\n"
    "    box.innerHTML = '<span class=\"muted\">（GitHub 全网无匹配或搜索失败，可 <a href=\"https://github.com/search?q=' +\n"
    "      encodeURIComponent(q) + '&type=repositories\" target=\"_blank\" rel=\"noopener\">去 GitHub 站内搜</a>）</span>';\n"
    "    return;\n"
    "  }\n"
    "  box.innerHTML = list.map((x, i) =>\n"
    "    '<div class=\"item\"><b><a href=\"' + esc(x.url) + '\" target=\"_blank\" rel=\"noopener\">' + esc(x.repo) + '</a></b> ' +\n"
    "    '<span class=\"muted\">⭐ ' + (x.stars || 0) + '</span>' +\n"
    "    '<button class=\"sec sm\" onclick=\"ghSearchInstall(' + i + ')\">安装</button>' +\n"
    "    '<div class=\"hint\">' + esc(x.description || '') + '</div></div>').join('');\n"
    "}\n"
    "\n"
    "/* 安装 GitHub 全网搜索结果：后端拉取仓库的 SKILL.md（退回 README.md）注册为 prompt 技能 */\n"
    "const SKILL_INSTALL_PENDING = new Map();\n"
    "async function installRemoteSkill(path, body){\n"
    "  const key = path + JSON.stringify(body);\n"
    "  if(SKILL_INSTALL_PENDING.has(key)) return SKILL_INSTALL_PENDING.get(key);\n"
    "  const operation = (async () => {\n"
    "    let result = await call('POST', path, body);\n"
    "    const id = result.obj && result.obj.job_id;\n"
    "    if(!result.obj?.pending || !id) return result;\n"
    "    for(let i = 0; i < 180; i++){\n"
    "      await new Promise(resolve => setTimeout(resolve, 500));\n"
    "      result = await call('GET', path + '?job_id=' + encodeURIComponent(id));\n"
    "      // A transient poll failure must not submit another download.\n"
    "      if(result.status === 0) continue;\n"
    "      if(!result.obj?.pending) return result;\n"
    "    }\n"
    "    return {status:408,obj:{error:'下载仍未确认完成，请稍后重试或检查网络'}};\n"
    "  })();\n"
    "  SKILL_INSTALL_PENDING.set(key, operation);\n"
    "  try { return await operation; }\n"
    "  finally { SKILL_INSTALL_PENDING.delete(key); }\n"
    "}\n"
    "async function ghSearchInstall(i){\n"
    "  const x = (Array.isArray(GH_SEARCH_LAST) ? GH_SEARCH_LAST : [])[i]; if(!x) return;\n"
    "  toast('从 GitHub 拉取 ' + x.repo + ' …（首次需下载，稍候）');\n"
    "  const r = await installRemoteSkill('/v1/skills/install-github', {repo: x.repo});\n"
    "  if(r.obj && r.obj.ok) toast('✔ 已安装 ' + r.obj.name + '（仓库原文）');\n"
    "  else toast('安装失败: ' + ((r.obj && r.obj.error) || ('HTTP ' + r.status)));\n"
    "  loadSkillsMarket();\n"
    "}\n"
    "\n"
    "function renderGhSkills(){\n"
    "  const box = $('gh-skill-catalog'); if(!box) return;\n"
    "  box.querySelectorAll('[data-fold-key]').forEach(f=>MARKET_FOLDS.set(f.dataset.foldKey,f.open));\n"
    "  const groups = {};\n"
    "  GH_SKILLS.filter(x => skillHit(x, [x.name, x.description, x.repo, x.id]))\n"
    "    .forEach(x => { (groups[x.repo] = groups[x.repo] || []).push(x); });\n"
    "  let html = '';\n"
    "  for (const repo of Object.keys(groups)) {\n"
    "    const items = groups[repo];\n"
    "    html += '<details class=\"market-fold\" data-fold-key=\"github:' + esc(repo) + '\"' + (skillQ() || MARKET_FOLDS.get('github:'+repo) ? ' open' : '') + '>' +\n"
    "      '<summary style=\"cursor:pointer;font-weight:bold\">' + esc(GH_REPO_LABELS[repo] || repo) +\n"
    "      ' <span class=\"muted\">(' + items.length + ')</span></summary>' +\n"
    "      '<div class=\"market-fold-body market-source-grid\">' + items.map(x => {\n"
    "        const i = GH_SKILLS.indexOf(x);\n"
    "        return '<div class=\"item\"><b>' + esc(x.name) + '</b>' +\n"
    "          '<div class=\"hint\">' + esc(x.description || '') + '</div>' +\n"
    "          '<a class=\"sec sm\" href=\"https://github.com/' +\n"
    "            (x.repo === 'fabric' ? 'danielmiessler/fabric' :\n"
    "             x.repo === 'anthropics' ? 'anthropics/skills' :\n"
    "             'PatrickJS/awesome-cursorrules') + '\" target=\"_blank\" rel=\"noopener\">仓库</a> ' +\n"
    "          '<button class=\"sec sm\" onclick=\"ghSkillInstall(' + i + ')\">安装</button></div>';\n"
    "      }).join('') +\n"
    "      '</div></details>';\n"
    "  }\n"
    "  if (!html) {\n"
    "    html = GH_SKILLS.length\n"
    "      ? '<span class=\"muted\">（精选仓库无匹配）</span>' +\n"
    "        (skillQ() ? '<div class=\"hint\">可到 GitHub 全站搜索：<a href=\"https://github.com/search?q=' +\n"
    "          encodeURIComponent(skillQ()) + '&type=repositories\" target=\"_blank\" rel=\"noopener\">' +\n"
    "          esc(skillQ()) + ' @ GitHub</a></div>' : '')\n"
    "      : '<span class=\"muted\">（加载失败）</span>';\n"
    "  }\n"
    "  box.innerHTML = html;\n"
    "}\n"
    "\n"
    "async function ghSkillInstall(i){\n"
    "  const x = GH_SKILLS[i]; if(!x) return;\n"
    "  toast('从 GitHub 拉取 ' + x.id + ' …（首次需下载，稍候）');\n"
    "  const r = await installRemoteSkill('/v1/skills/install-remote', {repo: x.repo, id: x.id});\n"
    "  if(r.obj && r.obj.ok) toast('✔ 已安装 ' + x.id + '（内容来自仓库原文）');\n"
    "  else toast('安装失败: ' + ((r.obj && r.obj.error) || ('HTTP ' + r.status)));\n"
    "  loadSkillsMarket();\n"
    "}\n"
    "\n"
    "/* SkillHub（skillhub.cn）在线技能：列表实时来自 api.skillhub.cn，安装时后端拉取 SKILL.md 原文 */\n"
    "let SKH_SKILLS = [];\n"
    "\n"
    "async function loadSkillhubList(){\n"
    "  const box = $('skh-skill-catalog'); if(!box) return;\n"
    "  const q = skillQ();\n"
    "  if(!q){\n"
    "    SKH_SKILLS=[]; SKH_Q_LAST='';\n"
    "    box.textContent='在顶部搜索框输入关键词，搜索 SkillHub 技能。';\n"
    "    return;\n"
    "  }\n"
    "  box.innerHTML = q ? '<span class=\"muted\">🔍 正在 SkillHub 市场全量搜索「' + esc(q) + '」…</span>'\n"
    "                    : '<span class=\"muted\">加载中…（访问 api.skillhub.cn）</span>';\n"
    "  /* issue #20: 后台线程 + 轮询，搜索期间不再卡住整个 UI */\n"
    "  let r = null;\n"
    "  for(let i = 0; i < 60; i++){\n"
    "    r = await call('GET', '/v1/catalog/skillhub' + (q ? '?q=' + encodeURIComponent(q) : ''));\n"
    "    if(skillQ() !== q || !box.isConnected) return;\n"
    "    if(r.obj && r.obj.pending){ await new Promise(res => setTimeout(res, 700)); continue; }\n"
    "    break;\n"
    "  }\n"
    "  if(!r || (r.obj && r.obj.pending)){ box.innerHTML = '<span class=\"muted\">（加载超时，请重试）</span>'; return; }\n"
    "  if(r.status >= 400){\n"
    "    box.innerHTML = '<span class=\"muted\">（加载失败：' + esc((r.obj && r.obj.error) || ('HTTP ' + r.status)) + '）</span>';\n"
    "    return;\n"
    "  }\n"
    "  SKH_SKILLS = Array.isArray(r.obj) ? r.obj : [];\n"
    "  SKH_Q_LAST = q;\n"
    "  renderSkhSkills();\n"
    "}\n"
    "\n"
    "function renderSkhSkills(){\n"
    "  const box = $('skh-skill-catalog'); if(!box) return;\n"
    "  if(!SKH_SKILLS.length){\n"
    "    box.innerHTML = (skillQ() && skillQ() === SKH_Q_LAST)\n"
    "      ? '<span class=\"muted\">（市场全量搜索无匹配，换个关键字试试）</span>'\n"
    "      : '<span class=\"muted\">（加载失败：无法从 skillhub.cn 获取列表，检查网络）</span>';\n"
    "    return;\n"
    "  }\n"
    "  const list = SKH_SKILLS.filter(x => skillHit(x, [x.name, x.id, x.description]));\n"
    "  if(!list.length){ box.innerHTML = '<span class=\"muted\">（无匹配技能）</span>'; return; }\n"
    "  box.innerHTML = list.map((x) => {\n"
    "    const i = SKH_SKILLS.indexOf(x);\n"
    "    return '<div class=\"item\"><b>' + esc(x.name || x.id) + '</b> <span class=\"muted\">' + (x.skill_count || 0) + ' 技能</span>' +\n"
    "      '<div class=\"hint\">' + esc(x.description || '') + '</div>' +\n"
    "      '<a class=\"sec sm\" href=\"' + esc(x.source) + '\" target=\"_blank\" rel=\"noopener\">详情</a> ' +\n"
    "      '<button class=\"sec sm\" onclick=\"skillhubInstall(' + i + ')\">安装</button></div>';\n"
    "  }).join('');\n"
    "}\n"
    "\n"
    "async function skillhubInstall(i){\n"
    "  const x = SKH_SKILLS[i]; if(!x) return;\n"
    "  toast('从 skillhub.cn 拉取 ' + x.id + ' 的 SKILL.md …');\n"
    "  const r = await installRemoteSkill('/v1/skills/install-skillhub', {slug: x.id});\n"
    "  if(r.obj && r.obj.ok) toast('✔ 已安装 ' + r.obj.name + '（SKILL.md 原文）');\n"
    "  else toast('安装失败: ' + ((r.obj && r.obj.error) || ('HTTP ' + r.status)));\n"
    "  loadSkillsMarket();\n"
    "}\n"
    "\n"
    "async function catalogSkillInstall(i){\n"
    "  const x = SKILL_CATALOG[i]; if(!x) return;\n"
    "  const r = await call('POST', '/v1/skills/install', {id: x.id});\n"
    "  if(r.obj && r.obj.ok) toast('✔ 已安装 ' + x.id);\n"
    "  else toast('安装失败: ' + ((r.obj && r.obj.error) || ('HTTP ' + r.status)));\n"
    "  loadSkillsMarket();\n"
    "}\n"
    "\n"
    "async function catalogSkillTest(i){\n"
    "  const x = SKILL_CATALOG[i]; if(!x) return;\n"
    "  toast('安装并测试 ' + x.id + ' …');\n"
    "  const ins = await call('POST', '/v1/skills/install', {id: x.id});\n"
    "  if(!(ins.obj && ins.obj.ok)){\n"
    "    toast('安装失败: ' + ((ins.obj && ins.obj.error) || ('HTTP ' + ins.status)));\n"
    "    return;\n"
    "  }\n"
    "  const runBody = {name: x.id};\n"
    "  if(x.test_args) runBody.args = x.test_args;\n"
    "  const r = await call('POST', '/v1/skills/run', runBody);\n"
    "  const out = $('skill-test-out');\n"
    "  if(out){ out.style.display = 'block'; renderJSON(r.obj, out); }\n"
    "  if(r.obj && r.obj.ok) toast('✔ ' + x.id + ' 测试通过');\n"
    "  else toast('✘ ' + x.id + ' 测试失败');\n"
    "  loadSkillsMarket();\n"
    "}\n"
    "\n"
    "/* ================= Skills 市场 / 发布 ================= */\n"
    "let SKILL_MARKET = {templates:[], installed:[]};\n"
    "\n"
    "function renderSkillDiscovery(){\n"
    "  const box = $('skill-featured'); if(!box) return;\n"
    "  const q = skillQ(), installed = new Set((SKILLS_LIST || []).map(x => x.name));\n"
    "  const items = [];\n"
    "  (SKILL_MARKET.templates || []).forEach((x,i) => {\n"
    "    if(marketHit(x,q)) items.push({x, action:'installSkill(' + i + ')', label:installed.has(x.name) ? '更新技能' : '安装技能', done:installed.has(x.name)});\n"
    "  });\n"
    "  SKILL_CATALOG.forEach((x,i) => {\n"
    "    if(x.type !== 'reference' && marketHit(x,q) && !items.some(e => e.x.name === x.id))\n"
    "      items.push({x:{name:x.id,description:x.description,kind:x.kind},action:'catalogSkillInstall(' + i + ')',label:installed.has(x.id) ? '重新安装技能' : '安装技能',done:installed.has(x.id)});\n"
    "  });\n"
    "  box.innerHTML = items.length ? items.map(({x,action,label,done}) =>\n"
    "    '<div class=\"market-entry\">' + marketIcon(x.name) + '<div class=\"market-entry-copy\"><strong>' + esc(x.name) + '</strong><span title=\"' + esc(x.description || '') + '\">' + esc(x.description || '可运行技能') + '</span><small>' + esc(x.kind || 'SKILL') + (done ? ' · 已安装' : ' · 可安装') + '</small></div>' +\n"
    "    '<button class=\"market-action-label\" type=\"button\" aria-label=\"' + esc(label + ' ' + x.name) + '\" onclick=\"' + action + '\">' + (done ? '更新' : '安装') + '</button></div>').join('') :\n"
    "    '<div class=\"market-empty\">' + (q ? '没有匹配的技能，试试其他关键词。' : '暂无可发现的技能。') + '</div>';\n"
    "}\n"
    "\n"
    "async function loadSkillsMarket(){\n"
    "  const r = await call('GET', '/v1/skills');\n"
    "  SKILLS_LIST = Array.isArray(r.obj) ? r.obj : null;\n"
    "  renderRegisteredSkills();\n"
    "  const m = await call('GET', '/v1/skills/market');\n"
    "  SKILL_MARKET = (m.obj && typeof m.obj === 'object') ? m.obj : {templates:[], installed:[]};\n"
    "  renderSkillDiscovery();\n"
    "  const box = $('skill-market'); if(!box) return;\n"
    "  const t = SKILL_MARKET.templates || [], inst = SKILL_MARKET.installed || [], gh = SKILL_MARKET.github || [];\n"
    "  let html = '<div class=\"sub\">市场模板（点击安装）</div>' +\n"
    "    (t.length ? t.map((x,i) =>\n"
    "      '<div class=\"item\"><b>' + esc(x.name) + '</b> <span class=\"muted\">' + esc(x.kind) + '</span>' +\n"
    "      (x.installed ? ' <span class=\"tag\">已安装</span>' : '') +\n"
    "      '<div class=\"hint\">' + esc(x.description || '') + '</div>' +\n"
    "      '<button class=\"sec sm\" onclick=\"installSkill(' + i + ')\">' + (x.installed ? '重装/更新' : '安装') + '</button></div>').join('')\n"
    "      : '<span class=\"muted\">（空）</span>');\n"
    "  html += '<div class=\"sub\">GitHub 热门应用（点击安装 / 查看仓库）</div>' +\n"
    "    (gh.length ? gh.map(x =>\n"
    "      '<div class=\"item\"><b><a href=\"' + esc(marketUrl(x.repo)) + '\" target=\"_blank\" rel=\"noopener\">' + esc(x.name) + '</a></b> <span class=\"muted\">' + esc(x.kind) + '</span>' +\n"
    "      '<div class=\"hint\">' + esc(x.description || '') + '</div>' +\n"
    "      (x.winget_id ? '<button class=\"sec sm\" onclick=\"ghInstall(\\'' + esc(x.name) + '\\')\">安装（winget）</button>' : '') + '</div>').join('')\n"
    "      : '<span class=\"muted\">（空）</span>');\n"
    "  html += '<div class=\"sub\">已安装（可删除）</div>' +\n"
    "    (inst.length ? inst.map((x,i) =>\n"
    "      '<div class=\"item\"><b>' + esc(x.name) + '</b> <span class=\"muted\">' + esc(x.kind) + '</span> ' +\n"
    "      '<button class=\"sec sm danger\" onclick=\"deleteMarketSkill(' + i + ')\">删除</button></div>').join('')\n"
    "      : '<span class=\"muted\">（空）</span>');\n"
    "  setMarketHTML(box, html);\n"
    "}\n"
    "\n"
    "async function installSkill(i){\n"
    "  const t = (SKILL_MARKET.templates || [])[i]; if(!t) return;\n"
    "  const r = await call('POST', '/v1/skills/publish',\n"
    "    {name:t.name, description:t.description, kind:t.kind, body:t.body});\n"
    "  if(r.obj && r.obj.ok) toast('已' + (t.installed ? '更新 ' : '安装 ') + t.name);\n"
    "  else toast('安装失败: ' + ((r.obj && r.obj.error) || ('HTTP ' + r.status)));\n"
    "  loadSkillsMarket();\n"
    "}\n"
    "\n"
    "async function ghInstall(name){\n"
    "  toast('启动安装 ' + name + '（后台 winget）…');\n"
    "  const r = await call('POST', '/v1/tools/gh-install', {name});\n"
    "  if(r.obj && r.obj.ok) toast(name + ' 后台安装已启动，完成后可在 shell 里直接使用');\n"
    "  else toast('安装失败: ' + ((r.obj && r.obj.error) || ('HTTP ' + r.status)));\n"
    "}\n"
    "\n"
    "async function deleteSkill(n){\n"
    "  await call('DELETE', '/v1/skills/' + encodeURIComponent(n));\n"
    "  loadSkillsMarket();\n"
    "}\n"
    "function deleteMarketSkill(i){\n"
    "  const x = (SKILL_MARKET.installed || [])[i]; if(x) deleteSkill(x.name);\n"
    "}\n"
    "\n"
    "async function publishSkill(){\n"
    "  const name = $('sk-name').value.trim(), body = $('sk-body').value;\n"
    "  if(!name || !body){ if($('sk-stat')) $('sk-stat').textContent = '需要 name 和 body'; return; }\n"
    "  const r = await call('POST', '/v1/skills/publish',\n"
    "    {name, description:$('sk-desc').value, kind:$('sk-kind').value, body});\n"
    "  if($('sk-stat')) $('sk-stat').textContent = (r.obj && r.obj.ok) ? '已发布' : ('失败 ' + ((r.obj && r.obj.error) || r.status));\n"
    "  if(r.obj && r.obj.ok){ $('sk-name').value=''; $('sk-desc').value=''; $('sk-body').value=''; }\n"
    "  loadSkillsMarket();\n"
    "}\n"
    "\n"
    "/* ================= Plugins 市场 / 发布 ================= */\n"
    "let PLUGIN_MARKET = {templates:[],github:[]};\n"
    "let PLUGIN_REGISTRY = {};\n"
    "function renderPluginDiscovery(){\n"
    "  const q = (($('plugin-search') || {}).value || '').trim().toLowerCase();\n"
    "  const names = Object.keys(PLUGIN_REGISTRY).filter(n => marketHit({name:n,description:PLUGIN_REGISTRY[n] && PLUGIN_REGISTRY[n].description},q));\n"
    "  const installed = $('plugins-installed');\n"
    "  if(installed) installed.innerHTML = names.length ? names.map(n =>\n"
    "    '<button class=\"market-installed-item\" type=\"button\" title=\"' + esc(n) + '\" aria-label=\"查看插件 ' + esc(n) + '\" onclick=\"selectInstalledPlugin(' + Object.keys(PLUGIN_REGISTRY).indexOf(n) + ')\">' + marketIcon(n) + '<span class=\"market-installed-name\">' + esc(n) + '</span></button>').join('') : '<div class=\"market-empty\">' + (q ? '没有匹配的已安装插件' : '暂无已安装插件') + '</div>';\n"
    "  if($('plugins-installed-count')) $('plugins-installed-count').textContent = Object.keys(PLUGIN_REGISTRY).length + ' 个插件';\n"
    "  const featured = $('plugin-featured'); if(!featured) return;\n"
    "  const templates = (PLUGIN_MARKET.templates || []).filter(x => marketHit(x,q));\n"
    "  const github = (PLUGIN_MARKET.github || []).filter(x => marketHit(x,q));\n"
    "  let html = templates.map((x,i) => {\n"
    "    const index = (PLUGIN_MARKET.templates || []).indexOf(x);\n"
    "    return '<div class=\"market-entry\">' + marketIcon(x.name) + '<div class=\"market-entry-copy\"><strong>' + esc(x.name) + '</strong><span title=\"' + esc(x.description || '') + '\">' + esc(x.description || '插件模板') + '</span><small>创作模板 · ' + esc(x.kind || 'PLUGIN') + '</small></div>' +\n"
    "      '<button class=\"market-action-label\" type=\"button\" aria-label=\"以 ' + esc(x.name) + ' 为起点创建插件\" onclick=\"usePluginTemplate(' + index + ')\">使用模板</button></div>';\n"
    "  }).join('');\n"
    "  html += github.map(x => '<div class=\"market-entry\">' + marketIcon(x.name) + '<div class=\"market-entry-copy\"><strong>' + esc(x.name) + '</strong><span title=\"' + esc(x.description || '') + '\">' + esc(x.description || x.kind || '开源项目') + '</span><small>外部项目 · GitHub</small></div>' +\n"
    "    '<a class=\"market-action-label\" href=\"' + esc(marketUrl(x.repo)) + '\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"查看 ' + esc(x.name) + ' 仓库\">查看仓库 ↗</a></div>').join('');\n"
    "  featured.innerHTML = html || '<div class=\"market-empty\">' + (q ? '没有匹配的插件，试试其他关键词。' : '暂无推荐插件。') + '</div>';\n"
    "}\n"
    "function selectInstalledPlugin(i){\n"
    "  const n = Object.keys(PLUGIN_REGISTRY)[i], box = $('plugin-detail'); if(!n || !box) return;\n"
    "  const p = PLUGIN_REGISTRY[n] || {};\n"
    "  box.hidden = false;\n"
    "  box.innerHTML = '<h3>' + esc(n) + '</h3><p>' + esc(p.description || '已发布的插件') + '</p><div class=\"row\"><button class=\"sec sm danger\" type=\"button\" onclick=\"unpublishInstalledPlugin(' + i + ')\">下架插件</button></div>';\n"
    "}\n"
    "function unpublishInstalledPlugin(i){\n"
    "  const n = Object.keys(PLUGIN_REGISTRY)[i]; if(n) unpublishPlugin(n);\n"
    "  if($('plugin-detail')) $('plugin-detail').hidden = true;\n"
    "}\n"
    "function usePluginTemplate(i){\n"
    "  const x = (PLUGIN_MARKET.templates || [])[i]; if(!x) return;\n"
    "  $('plugin-advanced').open = true;\n"
    "  $('plugin-desc').value = '创建 ' + x.name + ' 插件：' + (x.description || '');\n"
    "  $('plugin-desc').focus();\n"
    "  $('plugin-desc').scrollIntoView({behavior:'smooth',block:'center'});\n"
    "}\n"
    "async function loadPluginMarket(){\n"
    "  const m = await call('GET', '/v1/plugins/market');\n"
    "  const box = $('plugin-market'); if(!box) return;\n"
    "  const t = (m.obj && m.obj.templates) || [];\n"
    "  const gh = (m.obj && m.obj.github) || [];\n"
    "  PLUGIN_MARKET = {templates:t,github:gh};\n"
    "  const reg = await call('GET', '/v1/plugins');\n"
    "  PLUGIN_REGISTRY = reg.obj && typeof reg.obj === 'object' && !Array.isArray(reg.obj) ? reg.obj : {};\n"
    "  const inst = Object.keys(PLUGIN_REGISTRY);\n"
    "  renderPluginDiscovery();\n"
    "  let html = '<div class=\"sub\">示例模板</div>' +\n"
    "    (t.length ? t.map(x =>\n"
    "      '<div class=\"item\"><b>' + esc(x.name) + '</b><div class=\"hint\">' + esc(x.description || '') + '</div></div>').join('')\n"
    "      : '<span class=\"muted\">（空）</span>');\n"
    "  html += '<div class=\"sub\">GitHub 热门应用（点击查看仓库）</div>' +\n"
    "    (gh.length ? gh.map(x =>\n"
    "      '<div class=\"item\"><b><a href=\"' + esc(marketUrl(x.repo)) + '\" target=\"_blank\" rel=\"noopener\">' + esc(x.name) + '</a></b> <span class=\"muted\">' + esc(x.kind) + '</span>' +\n"
    "      '<div class=\"hint\">' + esc(x.description || '') + '</div></div>').join('')\n"
    "      : '<span class=\"muted\">（空）</span>');\n"
    "  html += '<div class=\"sub\">已发布插件（可下架）</div>' +\n"
    "    (inst.length ? inst.map((n,i) =>\n"
    "      '<div class=\"item\"><b>' + esc(n) + '</b> ' +\n"
    "      '<button class=\"sec sm danger\" onclick=\"unpublishInstalledPlugin(' + i + ')\">下架</button></div>').join('')\n"
    "      : '<span class=\"muted\">（空）</span>');\n"
    "  setMarketHTML(box, html);\n"
    "}\n"
    "\n"
    "async function publishPlugin(){\n"
    "  const name = $('pl-name').value.trim(), body = $('pl-body').value;\n"
    "  if(!name || !body){ if($('pl-stat')) $('pl-stat').textContent = '需要 name 和 body'; return; }\n"
    "  const caps = ($('pl-caps').value || '').split(',').map(s=>s.trim()).filter(Boolean);\n"
    "  const r = await call('POST', '/v1/plugins/publish',\n"
    "    {name, description:$('pl-desc').value, kind:$('pl-kind').value, body, capabilities:caps});\n"
    "  if($('pl-stat')) $('pl-stat').textContent = (r.obj && r.obj.ok) ? '已发布' : ('失败 ' + ((r.obj && r.obj.error) || r.status));\n"
    "  if(r.obj && r.obj.ok){ $('pl-name').value=''; $('pl-desc').value=''; $('pl-body').value=''; $('pl-caps').value=''; }\n"
    "  loadPluginMarket();\n"
    "}\n"
    "\n"
    "async function unpublishPlugin(n){\n"
    "  await call('DELETE', '/v1/plugins/market/' + encodeURIComponent(n));\n"
    "  loadPluginMarket();\n"
    "}\n"
    "\n"
    "/* ================= 插件自生成 ================= */\n"
    "\n"
    "async function pluginGenerate(){\n"
    "  const desc = $('plugin-desc').value.trim();\n"
    "  const st = $('plugin-stat');\n"
    "  if(!desc){ if(st) st.textContent = '请输入能力描述'; return; }\n"
    "  if(st) st.textContent = '生成中…（分析→架构→生成→安全审计→注册）';\n"
    "  const r = await call('POST', '/v1/plugins/generate', {description: desc});\n"
    "  if(st) st.textContent = (r.obj && r.obj.ok) ? '✔ 已生成并注册' : ((r.obj && r.obj.error) ? 'error: ' + r.obj.error : 'error ' + r.status);\n"
    "  renderJSON(r.obj, $('plugin-result'));\n"
    "  if(r.obj && r.obj.ok) load('plugins');\n"
    "}\n"
    "\n"
    "/* ================= IM ================= */\n"
    "\n"
    "let IM_ACTIVE = null;\n"
    "let WS = null;\n"
    "let IM_CHANNELS = [];\n"
    "let IM_AGENTS = [], IM_SESSIONS = [], IM_EDITING = null;\n"
    "const IM_RUN_STATE = new Map();\n"
    "const IM_SESSION_TASK = new Map(), IM_RUN_POLL = new Set();\n"
    "const IM_THREAD_LOADS=new Map(), IM_SEND_PENDING=new Set();\n"
    "function imSendButton(){const b=$('im-send');if(b){b.disabled=IM_SEND_PENDING.has(IM_ACTIVE);b.setAttribute('aria-busy',String(b.disabled));}}\n"
    "\n"
    "function imRenderRunStatus(){\n"
    "  const el=$('im-run-status'), stop=$('im-stop'); if(!el) return;\n"
    "  const task_id=IM_SESSION_TASK.get(IM_ACTIVE), state=IM_RUN_STATE.get(task_id);\n"
    "  if(!state){ el.textContent=IM_ACTIVE===null?'选择群聊后开始讨论':'发送话题，让群内 Agent 开始讨论'; if(stop) stop.hidden=true; return; }\n"
    "  const active=state.status==='queued'||state.status==='running';\n"
    "  const round=state.discussion_round>0?'第 '+state.discussion_round+'/'+(state.discussion_rounds||3)+' 轮 · ':'';\n"
    "  const done={consensus:'全员已达成共识',round_limit:'已完成设定轮数'};\n"
    "  el.textContent=state.error || (state.stopping?'正在停止讨论，等待当前操作结束…':\n"
    "    state.status==='queued'?'已排队，等待 Agent…':\n"
    "    state.status==='running'?(state.stage==='waiting_for_executor'?(state.activity||'正在等待可用执行器')+' · '+(state.agent||'Agent'):round+(state.agent||'Agent')+' 正在讨论…'):\n"
    "    state.status==='failed'?'讨论执行失败，请查看任务 #'+task_id:\n"
    "    state.status==='timeout'?'讨论执行超时，请查看任务 #'+task_id:\n"
    "    state.status==='cancelled'?(state.reason==='new_message'?'新消息已接管本次讨论':'讨论已停止'):\n"
    "    (done[state.reason]||'讨论已完成'));\n"
    "  if(stop){stop.hidden=!active;stop.disabled=!!state.stopping;stop.textContent=state.stopping?'停止中…':'停止讨论';}\n"
    "}\n"
    "\n"
    "function imRunUpdate(m){\n"
    "  if(!Number.isInteger(m.task_id)||m.task_id<0||!Number.isInteger(m.session_id)) return;\n"
    "  const rank = {queued:1,running:2,done:3,failed:3,cancelled:3,timeout:3};\n"
    "  if(!rank[m.status]) return;\n"
    "  const previous = IM_RUN_STATE.get(m.task_id);\n"
    "  if(previous && (previous.rank>rank[m.status] || (previous.rank===2&&rank[m.status]===2&&(previous.discussion_round||0)>(m.discussion_round||0)))) return;\n"
    "  const state={...previous,...m,rank:rank[m.status]};\n"
    "  if(rank[m.status]===3){state.stopping=false;delete state.error;}\n"
    "  IM_RUN_STATE.set(m.task_id,state);\n"
    "  const latest=IM_SESSION_TASK.get(m.session_id);\n"
    "  if(latest===undefined||m.task_id>latest) IM_SESSION_TASK.set(m.session_id,m.task_id);\n"
    "  if(IM_RUN_STATE.size > 100) IM_RUN_STATE.delete(IM_RUN_STATE.keys().next().value);\n"
    "  if(IM_ACTIVE===m.session_id) imRenderRunStatus();\n"
    "  if(state.rank<3) imWatchRun(m.task_id);\n"
    "}\n"
    "\n"
    "async function imWatchRun(task_id){\n"
    "  if(IM_RUN_POLL.has(task_id)) return;\n"
    "  IM_RUN_POLL.add(task_id);\n"
    "  try {\n"
    "    while(true){\n"
    "      await new Promise(resolve=>setTimeout(resolve,1000));\n"
    "      const state=IM_RUN_STATE.get(task_id);\n"
    "      if(!state||state.rank===3||IM_SESSION_TASK.get(state.session_id)!==task_id) return;\n"
    "      const r=await call('GET','/v1/tasks/'+task_id), task=r.obj;\n"
    "      if(!task||r.status!==200) continue;\n"
    "      const terminal={DONE:'done',FAILED:'failed',CANCELLED:'cancelled',TIMEOUT:'timeout'}[task.status];\n"
    "      const status=terminal||task.im_status||({QUEUED:'queued',PENDING:'queued',RUNNING:'running'}[task.status]);\n"
    "      if(status) imRunUpdate({...state,...task,task_id,session_id:state.session_id,status});\n"
    "      if(IM_ACTIVE===state.session_id&&IM_SESSION_TASK.get(state.session_id)===task_id) await renderImThread();\n"
    "    }\n"
    "  } finally {IM_RUN_POLL.delete(task_id);}\n"
    "}\n"
    "\n"
    "async function imStop(){\n"
    "  const task_id=IM_SESSION_TASK.get(IM_ACTIVE), state=IM_RUN_STATE.get(task_id);\n"
    "  if(!state||state.rank===3||state.stopping) return;\n"
    "  state.stopping=true; delete state.error; imRenderRunStatus();\n"
    "  const r=await call('DELETE','/v1/tasks/'+task_id);\n"
    "  if(r.status<200||r.status>=300){state.stopping=false;state.error=(r.obj&&r.obj.error)||'停止失败，请重试';}\n"
    "  imRenderRunStatus();\n"
    "}\n"
    "\n"
    "function imSelectedMembers(){\n"
    "  return Array.from(document.querySelectorAll('#im-members input:checked'), el => el.value);\n"
    "}\n"
    "\n"
    "function imRenderMemberOptions(selected=imSelectedMembers()){\n"
    "  const box=$('im-members'); if(!box) return;\n"
    "  box.replaceChildren();\n"
    "  const names=new Set(IM_AGENTS.map(a=>a.name));\n"
    "  [...IM_AGENTS,...selected.filter(n=>!names.has(n)).map(name=>({name,missing:true}))].forEach(agent=>{\n"
    "    const label=document.createElement('label');\n"
    "    label.style.cssText='display:flex;align-items:center;gap:8px;padding:5px;overflow-wrap:anywhere';\n"
    "    const input=document.createElement('input'); input.type='checkbox'; input.value=agent.name;\n"
    "    input.style.cssText='width:16px;height:16px;flex:none'; input.checked=selected.includes(agent.name);\n"
    "    const text=document.createElement('span'); text.textContent=agent.name+(agent.missing?'（未注册，请移除）':agent.role?' · '+agent.role:'');\n"
    "    label.append(input,text); box.append(label);\n"
    "  });\n"
    "  if(!IM_AGENTS.length){\n"
    "    const hint=document.createElement('span'); hint.textContent='暂无已注册的 Agent。';\n"
    "    const button=document.createElement('button'); button.className='sec sm'; button.textContent='前往注册 Agent';\n"
    "    button.onclick=()=>switchPanel('agents'); box.prepend(hint,button);\n"
    "  }\n"
    "}\n"
    "\n"
    "async function imLoadAgents(){\n"
    "  const r=await call('GET','/v1/agents');\n"
    "  if(r.status!==200 || !r.obj || !Array.isArray(r.obj.agents)){\n"
    "    $('im-member-status').textContent='Agent 列表加载失败，请刷新后重试'; return false;\n"
    "  }\n"
    "  IM_AGENTS=r.obj.agents; imRenderMemberOptions(); return true;\n"
    "}\n"
    "\n"
    "function imCancelMembers(){\n"
    "  IM_EDITING=null;\n"
    "  if($('im-members-edit')) $('im-members-edit').hidden=true;\n"
    "  if($('im-create')) $('im-create').disabled=false;\n"
    "  if($('im-group')) $('im-group').disabled=false;\n"
    "  if($('im-rounds')) $('im-rounds').value='3';\n"
    "  imRenderMemberOptions([]);\n"
    "}\n"
    "\n"
    "function imEditMembers(id){\n"
    "  const session=IM_SESSIONS.find(s=>s.id===id); if(!session) return;\n"
    "  IM_EDITING=id; $('im-group').checked=true; $('im-group').disabled=true;\n"
    "  $('im-members').hidden=false; $('im-agent-hint').hidden=false;\n"
    "  $('im-rounds-field').hidden=false; $('im-rounds').value=String(session.discussion_rounds||3);\n"
    "  $('im-create').disabled=true; $('im-members-edit').hidden=false;\n"
    "  $('im-members-title').textContent='编辑 '+session.name+' 的成员与轮数（下一条新消息生效）';\n"
    "  $('im-member-status').textContent=''; imRenderMemberOptions(session.members || []);\n"
    "}\n"
    "\n"
    "function imValidateSelected(){\n"
    "  const members=imSelectedMembers(), names=new Set(IM_AGENTS.map(a=>a.name));\n"
    "  if(!members.length || members.some(n=>!names.has(n))){\n"
    "    $('im-member-status').textContent='请至少选择一位已注册的 Agent'; return null;\n"
    "  }\n"
    "  return members;\n"
    "}\n"
    "\n"
    "async function imSaveMembers(){\n"
    "  const id=IM_EDITING, members=imValidateSelected(); if(id===null || !members) return;\n"
    "  const discussion_rounds=Number($('im-rounds').value);\n"
    "  const r=await call('PUT','/v1/im/sessions/'+id+'/members',{members,discussion_rounds});\n"
    "  if(r.status!==200){ $('im-member-status').textContent=(r.obj && r.obj.error)||'成员保存失败，请重试'; return; }\n"
    "  imCancelMembers(); $('im-member-status').textContent='群成员与讨论轮数已保存'; await renderIm();\n"
    "}\n"
    "\n"
    "async function imCreate(){\n"
    "  if(IM_EDITING!==null) return;\n"
    "  const name = $('im-new').value.trim() || '新会话';\n"
    "  const isGroup = $('im-group').checked;\n"
    "  const members = isGroup ? imValidateSelected():[];\n"
    "  if(isGroup && !members) return;\n"
    "  const body = {name: name, kind: isGroup ? 'group' : 'direct'};\n"
    "  if(isGroup && members.length){body.members=members;body.discussion_rounds=Number($('im-rounds').value);}\n"
    "  const sel = $('im-channel');\n"
    "  if(sel && sel.value){ body.channel = sel.value; }\n"
    "  const r=await call('POST', '/v1/im/sessions', body);\n"
    "  if(r.status!==200){ $('im-member-status').textContent=(r.obj && r.obj.error)||'创建失败，请重试'; return; }\n"
    "  $('im-new').value = ''; $('im-member-status').textContent=''; imRenderMemberOptions([]);\n"
    "  IM_ACTIVE=r.obj.id; await renderIm();\n"
    "}\n"
    "\n"
    "function imDelete(id){\n"
    "  call('DELETE', '/v1/im/sessions/' + id).then(() => {\n"
    "    if(IM_EDITING===id) imCancelMembers();\n"
    "    if(IM_ACTIVE === id) IM_ACTIVE = null;\n"
    "    renderIm();\n"
    "  });\n"
    "}\n"
    "\n"
    "async function loadChannels(){\n"
    "  const r = await call('GET', '/v1/im/channels');\n"
    "  IM_CHANNELS = (r.obj && Array.isArray(r.obj.channels)) ? r.obj.channels : [];\n"
    "  const st = $('channels-stat');\n"
    "  if(st) st.textContent = IM_CHANNELS.length + ' 个渠道';\n"
    "  return IM_CHANNELS;\n"
    "}\n"
    "\n"
    "async function renderChannels(){\n"
    "  await loadChannels();\n"
    "  const box = $('channels-list');\n"
    "  if(!box) return;\n"
    "  if(!IM_CHANNELS.length){\n"
    "    box.innerHTML = '<span class=\"muted\" style=\"font-size:12px\">暂无渠道</span>';\n"
    "    return;\n"
    "  }\n"
    "  box.innerHTML = '';\n"
    "  IM_CHANNELS.forEach(ch => {\n"
    "    const div = document.createElement('div');\n"
    "    div.className = 'im-session';\n"
    "    div.style.justifyContent = 'space-between';\n"
    "    const left = document.createElement('span');\n"
    "    left.style.cssText = 'display:flex;align-items:center;gap:6px;min-width:0;flex:1';\n"
    "    const t = document.createElement('span'); t.className = 'badge badge-warn'; t.textContent = ch.type;\n"
    "    const nm = document.createElement('span'); nm.className = 'name'; nm.textContent = ch.name;\n"
    "    nm.title = ch.endpoint || '';\n"
    "    if(!ch.enabled) nm.style.opacity = '0.5';\n"
    "    left.appendChild(t); left.appendChild(nm); div.appendChild(left);\n"
    "    const ops = document.createElement('span'); ops.style.cssText='display:flex;gap:4px';\n"
    "    const send = document.createElement('button'); send.textContent = '发'; send.title='发送测试消息到此渠道';\n"
    "    send.onclick = (e)=>{ e.stopPropagation(); channelSendTest(ch.name); };\n"
    "    const del = document.createElement('button'); del.textContent = '✕'; del.title='删除渠道'; del.className='del';\n"
    "    del.onclick = (e)=>{ e.stopPropagation(); channelRemove(ch.name); };\n"
    "    ops.appendChild(send); ops.appendChild(del); div.appendChild(ops);\n"
    "    box.appendChild(div);\n"
    "  });\n"
    "}\n"
    "\n"
    "function channelAdd(){\n"
    "  const name = $('c-name').value.trim();\n"
    "  const type = $('c-type').value;\n"
    "  const endpoint = $('c-endpoint').value.trim();\n"
    "  const token = $('c-token').value.trim();\n"
    "  const target = $('c-target').value.trim();\n"
    "  const enabled = !!$('c-enabled').checked;\n"
    "  if(!name || !endpoint) return;\n"
    "  const body = {name, type, endpoint, enabled};\n"
    "  if(token) body.token = token;\n"
    "  if(target) body.target = target;\n"
    "  call('POST', '/v1/im/channels', body).then(r => {\n"
    "    if(r.obj && (r.obj.ok || r.obj.error === undefined)){\n"
    "      $('c-name').value=''; $('c-endpoint').value=''; $('c-token').value=''; $('c-target').value='';\n"
    "      renderIm(); renderChannels();\n"
    "    }\n"
    "  });\n"
    "}\n"
    "\n"
    "function channelRemove(name){\n"
    "  call('DELETE', '/v1/im/channels/' + encodeURIComponent(name)).then(() => {\n"
    "    renderIm(); renderChannels();\n"
    "  });\n"
    "}\n"
    "\n"
    "function channelSendTest(name){\n"
    "  call('POST', '/v1/im/channels/' + encodeURIComponent(name) + '/send', {text: '测试消息 来自 cognitive-os-agent 控制台'})\n"
    "    .then(() => toast('✉️ 已发送测试消息到 ' + name));\n"
    "}\n"
    "\n"
    "function imSelect(id){\n"
    "  IM_ACTIVE = id;\n"
    "  imSendButton();\n"
    "  imRenderRunStatus();\n"
    "  document.querySelectorAll('.im-session').forEach(s => s.classList.toggle('on', s.dataset.id === String(id)));\n"
    "  renderImThread();\n"
    "}\n"
    "\n"
    "function appendImMessage(m){\n"
    "  const t = $('im-thread');\n"
    "  if(!t) return;\n"
    "  const d = new Date(m.ts_ms || Date.now());\n"
    "  const time = d.getHours() + ':' + String(d.getMinutes()).padStart(2, '0');\n"
    "  const isMine = (m.role === 'user') && (!m.sender || m.sender === 'me');\n"
    "  const div = document.createElement('div');\n"
    "  div.className = 'im-msg ' + (isMine ? 'user' : 'assistant');\n"
    "  div.textContent = m.content || '';\n"
    "  const meta = document.createElement('div');\n"
    "  meta.className = 'meta';\n"
    "  const who = m.sender || (m.role === 'user' ? 'user' : 'assistant');\n"
    "  meta.textContent = who + (m.discussion_round?' · 第 '+m.discussion_round+' 轮':'') + ' · ' + time;\n"
    "  div.appendChild(meta);\n"
    "  t.appendChild(div);\n"
    "  t.scrollTop = t.scrollHeight;\n"
    "}\n"
    "\n"
    "async function renderImThread(){\n"
    "  const t = $('im-thread');\n"
    "  if(!t) return;\n"
    "  if(IM_ACTIVE === null){\n"
    "    t.innerHTML = '<span class=\"muted\" style=\"font-size:12px\">选择一个会话开始聊天</span>';\n"
    "    return;\n"
    "  }\n"
    "  const session=IM_ACTIVE;\n"
    "  const pending=IM_THREAD_LOADS.get(session);\n"
    "  if(pending&&pending.element===t){pending.dirty=true;return pending.promise;}\n"
    "  if(t.dataset.session!==String(session)){t.replaceChildren();t.dataset.session=String(session);}\n"
    "  if(!t.querySelector('.im-msg'))t.innerHTML='<span class=\"muted im-thread-loading\"><span class=\"spin\"></span> 加载中…</span>';\n"
    "  t.setAttribute('aria-busy','true');\n"
    "  const state={dirty:false,promise:null,element:t};IM_THREAD_LOADS.set(session,state);\n"
    "  state.promise=(async()=>{\n"
    "    try{\n"
    "      do{\n"
    "        state.dirty=false;\n"
    "        const r=await call('GET','/v1/im/sessions/'+session+'/messages');\n"
    "        if(IM_ACTIVE!==session||!t.isConnected)return;\n"
    "        if(r.status!==200||!Array.isArray(r.obj)){\n"
    "          t.querySelectorAll('.im-thread-loading,.im-thread-error').forEach(e=>e.remove());\n"
    "          const error=document.createElement('div');error.className='im-thread-error';error.setAttribute('role','alert');\n"
    "          error.textContent='消息加载失败：'+(r.obj?.error || 'HTTP '+r.status)+' ';\n"
    "          const retry=document.createElement('button');retry.className='sec sm';retry.textContent='重试';retry.onclick=()=>renderImThread();error.append(retry);t.append(error);return;\n"
    "        }\n"
    "        t.replaceChildren();r.obj.forEach(m=>appendImMessage(m));\n"
    "      }while(state.dirty&&IM_ACTIVE===session);\n"
    "    }finally{\n"
    "      if(IM_THREAD_LOADS.get(session)===state)IM_THREAD_LOADS.delete(session);\n"
    "      if(IM_ACTIVE===session)t.setAttribute('aria-busy','false');\n"
    "    }\n"
    "  })();\n"
    "  return state.promise;\n"
    "}\n"
    "\n"
    "async function renderIm(){\n"
    "  const list = $('im-sessions');\n"
    "  if(!list) return;\n"
    "  await loadChannels();\n"
    "  const sel = $('im-channel');\n"
    "  if(sel){\n"
    "    sel.innerHTML = '<option value=\"\">无关联渠道</option>';\n"
    "    IM_CHANNELS.forEach(c => {\n"
    "      const o = document.createElement('option'); o.value = c.name; o.textContent = c.name + ' (' + c.type + ')';\n"
    "      sel.appendChild(o);\n"
    "    });\n"
    "  }\n"
    "  const g = $('im-group');\n"
    "  if(g && !g.dataset.bound){\n"
    "    imCancelMembers();\n"
    "    g.dataset.bound = '1';\n"
    "    g.addEventListener('change', () => { ['im-members','im-agent-hint','im-rounds-field'].forEach(id=>{const el=$(id);if(el)el.hidden=!g.checked;}); });\n"
    "  }\n"
    "  await imLoadAgents();\n"
    "  const r = await call('GET', '/v1/im/sessions');\n"
    "  const sessions = (r.obj && Array.isArray(r.obj.sessions)) ? r.obj.sessions : [];\n"
    "  IM_SESSIONS=sessions;\n"
    "  imRenderRunStatus();\n"
    "  list.innerHTML = '';\n"
    "  if(!sessions.length){\n"
    "    list.innerHTML = '<span class=\"muted\" style=\"font-size:12px\">暂无会话，创建第一个吧</span>';\n"
    "    return;\n"
    "  }\n"
    "  sessions.forEach(s => {\n"
    "    const isGroup = s.kind === 'group';\n"
    "    const div = document.createElement('div');\n"
    "    div.className = 'im-session' + (s.id === IM_ACTIVE ? ' on' : '');\n"
    "    div.dataset.id = s.id;\n"
    "    div.onclick = () => imSelect(s.id);\n"
    "    const name = document.createElement('span');\n"
    "    name.className = 'name';\n"
    "    name.textContent = (s.name || ('#' + s.id)) + ' · ' + (s.messages || 0);\n"
    "    if(isGroup) name.textContent += ' · ' + ((s.members || []).length) + '人 · ' + (s.discussion_rounds||3) + '轮';\n"
    "    const badge = document.createElement('span');\n"
    "    badge.className = 'badge ' + (isGroup ? 'badge-ok' : 'badge-warn');\n"
    "    badge.textContent = isGroup ? '群' : '单';\n"
    "    if(s.channel){\n"
    "      const ch = document.createElement('span');\n"
    "      ch.className = 'badge badge-accent';\n"
    "      ch.textContent = '渠道:' + s.channel;\n"
    "      ch.title = '关联外部渠道';\n"
    "      name.appendChild(ch);\n"
    "    }\n"
    "    const del = document.createElement('button');\n"
    "    del.className = 'del';\n"
    "    del.textContent = '✕';\n"
    "    del.title = '删除会话';\n"
    "    del.onclick = (e) => { e.stopPropagation(); imDelete(s.id); };\n"
    "    const left = document.createElement('span');\n"
    "    left.style.cssText = 'display:flex;align-items:center;gap:6px;min-width:0;flex:1';\n"
    "    left.appendChild(badge);\n"
    "    left.appendChild(name);\n"
    "    div.appendChild(left);\n"
    "    if(isGroup){\n"
    "      const edit=document.createElement('button'); edit.className='sec sm'; edit.textContent='成员';\n"
    "      edit.setAttribute('aria-label','编辑 '+s.name+' 的成员');\n"
    "      edit.onclick=e=>{ e.stopPropagation(); imEditMembers(s.id); }; div.appendChild(edit);\n"
    "    }\n"
    "    div.appendChild(del);\n"
    "    list.appendChild(div);\n"
    "  });\n"
    "  renderChannels();\n"
    "  renderImThread();\n"
    "}\n"
    "\n"
    "async function imSend(){\n"
    "  const input = $('im-input');\n"
    "  let content = input.value.trim();\n"
    "  if(!content || IM_ACTIVE === null || IM_SEND_PENDING.has(IM_ACTIVE)) return;\n"
    "  const sender = 'me';\n"
    "  const session=IM_ACTIVE;\n"
    "  IM_SEND_PENDING.add(session);imSendButton();\n"
    "  try{\n"
    "  const r=await call('POST', '/v1/im/sessions/' + session + '/messages', {role:'user', content, sender});\n"
    "  if(r.status<200||r.status>=300||!r.obj || !r.obj.ok){if(IM_ACTIVE===session)$('im-run-status').textContent=(r.obj && r.obj.error)||'消息发送失败，请重试'; return; }\n"
    "  if(Number.isInteger(r.obj.task_id)&&r.obj.task_id>=0){\n"
    "    const room=IM_SESSIONS.find(s=>s.id===session);\n"
    "    imRunUpdate({task_id:r.obj.task_id,session_id:session,status:'queued',discussion_round:0,discussion_rounds:room?.discussion_rounds||3});\n"
    "  }\n"
    "  if(IM_ACTIVE===session){ if(input.value.trim()===content) input.value=''; renderImThread(); }\n"
    "  }finally{IM_SEND_PENDING.delete(session);imSendButton();}\n"
    "}\n"
    "\n"
    "async function imSearch(){\n"
    "  const q = $('im-search').value.trim();\n"
    "  const box = $('im-search-results');\n"
    "  if(!q){ if(box) box.innerHTML = ''; return; }\n"
    "  const r = await call('GET', '/v1/im/search?q=' + encodeURIComponent(q));\n"
    "  const hits = Array.isArray(r.obj) ? r.obj : [];\n"
    "  if(!box) return;\n"
    "  if(!hits.length){\n"
    "    box.innerHTML = '<div class=\"muted\" style=\"font-size:12px;margin:0 0 8px\">无匹配</div>';\n"
    "    return;\n"
    "  }\n"
    "  box.innerHTML = '<div class=\"chips\" style=\"margin-bottom:8px\">' + hits.map(h =>\n"
    "    '<button class=\"chip\" onclick=\"imSelect(' + h.session_id + ')\" title=\"' + esc(h.content) + '\">' +\n"
    "    '<b>' + esc(h.session_name || ('#' + h.session_id)) + '</b><span>' + esc(h.content) + '</span></button>'\n"
    "  ).join('') + '</div>';\n"
    "}\n"
    "\n"
    "/* ================= WebSocket 实时推送 ================= */\n"
    "\n"
    "function wsConnect(){\n"
    "  try {\n"
    "    const proto = location.protocol === 'https:' ? 'wss' : 'ws';\n"
    "    WS = new WebSocket(proto + '://' + location.host + '/ws');\n"
    "    WS.onmessage = (e) => {\n"
    "      try {\n"
    "        const m = JSON.parse(e.data);\n"
    "        if(m.type === 'im.message'){\n"
    "          if(current === 'im' && IM_ACTIVE === m.session_id){\n"
    "            appendImMessage(m);\n"
    "            const pending=IM_THREAD_LOADS.get(m.session_id);if(pending)pending.dirty=true;\n"
    "          } else {\n"
    "            toast('📩 新消息: ' + ((m.role === 'user') ? '用户' : '助手'));\n"
    "          }\n"
    "        } else if(m.type === 'im.run'){\n"
    "          imRunUpdate(m);\n"
    "        } else if(m.type === 'event' && m.source === 'flow'){\n"
    "          const el = $('flow-out');\n"
    "          if(el && m.payload){\n"
    "            const p = m.payload;\n"
    "            let line = '';\n"
    "            if(p.stage === 'execute') line = '→ [' + (p.node || '') + ':' + (p.agent || '') + '] ' + (p.detail || '');\n"
    "            else if(p.stage === 'done') line = (p.detail === 'ok' ? '✓' : '✗') + ' [' + (p.node || '') + ':' + (p.agent || '') + '] ' + (p.detail === 'ok' ? '已完成' : p.detail === 'error' ? '执行失败' : (p.detail || '状态未知'));\n"
    "            if(line) el.textContent += (el.textContent ? '\\n' : '') + line;\n"
    "          }\n"
    "        } else if(m.type === 'event' && m.source === 'task.progress' && m.payload){\n"
    "          const p = m.payload;\n"
    "          chatApplyProgress(p.session_id, p.task_id, p);\n"
    "        }\n"
    "      } catch(err) { /* ignore non-JSON */ }\n"
    "    };\n"
    "    WS.onclose = () => { setTimeout(wsConnect, 3000); };\n"
    "    WS.onerror = () => { try { WS.close(); } catch(e) {} };\n"
    "  } catch(e) { /* ws unsupported */ }\n"
    "}\n"
    "\n"
    "/* ================= 对话（连续多轮聊天 + 多会话标签页） ================= */\n"
    "\n"
    "let CHAT_SESSION = 'default';   // 旧版共享默认会话；打开聊天时切换到独立新会话\n"
    "let CHAT_NEW_SESSION = false;   // 新会话尚未发出首条消息（后端还没有该 id）\n"
    "let CHAT_MSGS = [];             // 当前会话气泡的本地镜像 [{role,text,pending,el}]\n"
    "// switchPanel 用 innerHTML 重绘面板，气泡若只活在 DOM 里，切页即丢；\n"
    "// 轮询循环持有的节点也会脱离文档导致任务结果更新到空中。所有渲染都从\n"
    "// CHAT_MSGS 恢复，进行中的回复以 pending 标记，切回面板后继续显示。\n"
    "// CHAT_CACHE: 每会话消息缓存（sessionId → msgs），切会话/切页时先回放缓存\n"
    "// 再等服务端历史，避免闪烁与清空。\n"
    "const CHAT_CACHE = {};\n"
    "const CHAT_RECENT_RECONCILED = new Set();\n"
    "function chatCacheStore(){ CHAT_CACHE[CHAT_SESSION] = CHAT_MSGS; }\n"
    "\n"
    "function chatRedraw(toBottom = false){\n"
    "  const box = $('chat-box'); if(!box) return;\n"
    "  const follow = toBottom || chatNearBottom();\n"
    "  box.innerHTML = '';\n"
    "  CHAT_MSGS.forEach(m => { m.el = chatAddBubble(m.role, m.text, false); if(m.images) chatRenderImages(m.el,m.images); renderChatEntry(m); });\n"
    "  updateChatHero();\n"
    "  chatScroll(follow);\n"
    "}\n"
    "\n"
    "let CHAT_WORKSPACE = localStorage.getItem('coa.workspace') || '';\n"
    "let WORKSPACES = [], WORKSPACE_DEFAULT = '';\n"
    "let FLOW_WORKSPACE=localStorage.getItem('coa.flow-workspace') || CHAT_WORKSPACE;\n"
    "const WORKSPACE_FOLDS = new Map();\n"
    "/* Registry insertion order is the creation-order fallback for pre-timestamp entries.\n"
    "   Re-registering/renaming a workspace must never move it ahead of a newer one. */\n"
    "function orderedWorkspaces(){return WORKSPACES.map((w,i)=>({w,i})).sort((a,b)=>(Number(b.w.created_ms)||0)-(Number(a.w.created_ms)||0)||b.i-a.i).map(x=>x.w);}\n"
    "function workspaceLabel(path){return WORKSPACES.find(w=>w.path===path)?.name?.trim() || path?.replace(/[\\\\/]+$/,'').split(/[\\\\/]/).pop() || path || '默认工作区';}\n"
    "async function workspaceLoad(){\n"
    "  const r=await call('GET','/v1/workspaces');\n"
    "  if(r.status!==200 || !Array.isArray(r.obj?.workspaces))return;\n"
    "  WORKSPACES=r.obj.workspaces;WORKSPACE_DEFAULT=r.obj.default_workspace || '';\n"
    "  workspaceRender(CHAT_TABS_CACHE);flowWorkspaceRender();sideRecent(CHAT_TABS_CACHE);\n"
    "}\n"
    "function flowWorkspaceRender(){\n"
    "  const select=$('flow-workspace');if(!select)return;select.replaceChildren();\n"
    "  const seen=new Set();for(const w of [...orderedWorkspaces(),{path:WORKSPACE_DEFAULT}]){\n"
    "    if(!w.path || seen.has(w.path))continue;seen.add(w.path);const o=document.createElement('option');o.value=w.path;o.textContent=workspaceLabel(w.path);o.title=w.path;select.append(o);\n"
    "  }\n"
    "  if(!seen.has(FLOW_WORKSPACE))FLOW_WORKSPACE=WORKSPACE_DEFAULT;select.value=FLOW_WORKSPACE;select.title=FLOW_WORKSPACE;\n"
    "}\n"
    "function workspaceRender(list){\n"
    "  const info=(list || []).find(s=>s.id===CHAT_SESSION) || (CHAT_SELECTED_INFO?.id===CHAT_SESSION?CHAT_SELECTED_INFO:null);\n"
    "  if(info?.workspace)CHAT_WORKSPACE=info.workspace;\n"
    "  if(!CHAT_WORKSPACE)CHAT_WORKSPACE=WORKSPACE_DEFAULT;\n"
    "  const select=$('chat-workspace');if(!select)return;select.replaceChildren();\n"
    "  const entries=[{path:WORKSPACE_DEFAULT,name:workspaceLabel(WORKSPACE_DEFAULT)},...orderedWorkspaces()];\n"
    "  if(CHAT_WORKSPACE && !entries.some(w=>w.path===CHAT_WORKSPACE))entries.push({path:CHAT_WORKSPACE,name:CHAT_WORKSPACE.split(/[\\\\/]/).pop()});\n"
    "  const seen=new Set();entries.forEach(w=>{if(!w.path || seen.has(w.path))return;seen.add(w.path);const o=document.createElement('option');o.value=w.path;o.textContent=w.name || w.path;o.title=w.path;select.append(o);});\n"
    "  select.value=CHAT_WORKSPACE;select.title=CHAT_WORKSPACE || '执行工作区';\n"
    "}\n"
    "async function workspaceSelect(path){\n"
    "  const session=CHAT_SESSION;\n"
    "  const r=await call('POST','/v1/chat/sessions/'+encodeURIComponent(session)+'/workspace',{workspace:path});\n"
    "  if(r.status!==200){toast('切换工作区失败：'+(r.obj?.error || r.status));workspaceRender(CHAT_TABS_CACHE);return;}\n"
    "  CHAT_TABS_CACHE.forEach(s=>{if(s.id===session)s.workspace=path;});\n"
    "  if(CHAT_SELECTED_INFO?.id===session)CHAT_SELECTED_INFO.workspace=path;\n"
    "  if(CHAT_SESSION===session){CHAT_WORKSPACE=path;localStorage.setItem('coa.workspace',path);workspaceRender(CHAT_TABS_CACHE);sideRecent(CHAT_TABS_CACHE);}\n"
    "}\n"
    "function workspaceDialog(){\n"
    "  let dialog=$('workspace-dialog');\n"
    "  if(!dialog){dialog=document.createElement('dialog');dialog.id='workspace-dialog';dialog.innerHTML='<form onsubmit=\"event.preventDefault();workspaceAdd()\"><h2>添加工作区</h2><label>名称（可选）<input id=\"workspace-name\" placeholder=\"例如 cognitive-os\"></label><label>本机文件夹路径<input id=\"workspace-path\" required placeholder=\"D:/AI/code/cognitive-os\" autocomplete=\"off\"></label><button type=\"button\" id=\"workspace-browse\" class=\"sec\" onclick=\"workspaceBrowse()\">从电脑选择文件夹…</button><p class=\"hint\">任务以这个目录解析相对路径和运行命令。此选择不会创建安全沙箱。</p><div class=\"row\"><span id=\"workspace-error\" role=\"alert\"></span><button type=\"button\" class=\"sec\" onclick=\"this.closest(\\'dialog\\').close()\">取消</button><button type=\"submit\">添加工作区</button></div></form>';document.body.append(dialog);}\n"
    "  if(!$('workspace-directory-picker')){const picker=document.createElement('div');picker.id='workspace-directory-picker';picker.hidden=true;picker.style.cssText='max-height:240px;overflow:auto;margin:12px 0';$('workspace-browse').after(picker);}\n"
    "  $('workspace-error').textContent='';dialog.showModal();$('workspace-path').focus();\n"
    "}\n"
    "async function workspaceAdd(){\n"
    "  const path=$('workspace-path').value.trim(),name=$('workspace-name').value.trim();\n"
    "  const r=await call('POST','/v1/workspaces',{path,name});\n"
    "  if(r.status!==200){$('workspace-error').textContent=r.obj?.error || '保存失败';return;}\n"
    "  WORKSPACES=r.obj.workspaces;WORKSPACE_DEFAULT=r.obj.default_workspace;flowWorkspaceRender();\n"
    "  const added=WORKSPACES.find(w=>w.path.replaceAll('\\\\','/').toLowerCase()===path.replaceAll('\\\\','/').toLowerCase());\n"
    "  $('workspace-dialog').close();const previous=CHAT_WORKSPACE;CHAT_WORKSPACE=added?.path || path;sideRecent(CHAT_TABS_CACHE);if(await chatNewSession()===false)CHAT_WORKSPACE=previous;\n"
    "}\n"
    "async function workspaceBrowse(){const b=$('workspace-browse');if(b)b.disabled=true;try{const r=await call('POST','/v1/workspaces/browse',{},125000);if(r.obj?.path)$('workspace-path').value=r.obj.path;else if(r.obj?.cancelled)return;else await workspaceBrowseServer($('workspace-path').value.trim());}finally{if(b)b.disabled=false;}}\n"
    "async function workspaceBrowseServer(path=''){\n"
    "  const picker=$('workspace-directory-picker');if(!picker)return;\n"
    "  const r=await call('GET','/v1/workspaces/directories'+(path?'?path='+encodeURIComponent(path):''));\n"
    "  if(r.status!==200){$('workspace-error').textContent=r.obj?.error||'无法列出文件夹，请输入路径';return;}\n"
    "  picker.hidden=false;picker.replaceChildren();\n"
    "  const title=document.createElement('div');title.textContent='服务器目录：'+r.obj.path;picker.append(title);\n"
    "  const button=(label,action)=>{const b=document.createElement('button');b.type='button';b.className='sec sm';b.textContent=label;b.onclick=action;picker.append(b);};\n"
    "  button('选择此目录',()=>{$('workspace-path').value=r.obj.path;picker.hidden=true;$('workspace-error').textContent='';});\n"
    "  if(r.obj.parent&&r.obj.parent!==r.obj.path)button('⬆ 上级目录',()=>workspaceBrowseServer(r.obj.parent));\n"
    "  for(const name of (r.obj.directories||[]).sort((a,b)=>a.localeCompare(b))){\n"
    "    button('📁 '+name,()=>workspaceBrowseServer(r.obj.path.replace(/\\/$/,'')+'/'+name));\n"
    "  }\n"
    "}\n"
    "function chatApproval(t,session){let box=$('chat-approval');if(!box){box=document.createElement('div');box.id='chat-approval';$('chat-status')?.after(box);}if(!box)return;const key=t.approval?session+':'+t.id+':'+t.approval.id:'';if(key&&box.dataset.key===key)return;box.dataset.key=key;box.replaceChildren();if(!t.approval)return;\n"
    "  box.setAttribute('role','alert');const title=document.createElement('strong');title.textContent='等待批准：'+t.approval.tool;box.append(title);\n"
    "  const args=document.createElement('pre');args.style.cssText='max-height:180px;overflow:auto;white-space:pre-wrap';args.textContent=t.approval.args;box.append(args);\n"
    "  for(const [label,allow] of [['批准本次',true],['拒绝',false]]){const b=document.createElement('button');b.textContent=label;b.onclick=async()=>{box.querySelectorAll('button').forEach(x=>x.disabled=true);const r=await call('POST','/v1/tasks/'+t.id+'/approval',{id:t.approval.id,session,allow});if(r.status!==200){toast(r.obj?.error||'审批失败');box.querySelectorAll('button').forEach(x=>x.disabled=false);}};box.append(b);}}\n"
    "\n"
    "function chatOptions(session=CHAT_SESSION){try{return JSON.parse(localStorage.getItem('coa.session-options:'+session)||'{}');}catch{return {};}}\n"
    "function chatOptionSet(name,value,session=CHAT_SESSION){const o=chatOptions(session);o[name]=value;localStorage.setItem('coa.session-options:'+session,JSON.stringify(o));}\n"
    "function chatPermissionChange(value){chatOptionSet('permission',value);}\n"
    "function syncChatPermission(){const el=$('chat-permission');if(el)el.value=chatOptions().permission || 'auto';}\n"
    "async function loadChat(){\n"
    "  syncChatPermission();\n"
    "  const box = $('chat-box'); if(!box) return;\n"
    "  if(CHAT_SESSION === 'default' && !CHAT_NEW_SESSION) await chatNewSession({ensure:true});\n"
    "  renderChatTabs(CHAT_TABS_CACHE);\n"
    "  if(CHAT_CACHE[CHAT_SESSION]?.length){ CHAT_MSGS = CHAT_CACHE[CHAT_SESSION]; chatRedraw(true); }\n"
    "  void workspaceLoad();\n"
    "  void loadChatSessions();\n"
    "  void chatLoadHistory();\n"
    "  loadUploads();\n"
    "  fillChatModelSelect();\n"
    "  chatInitDrop(); /* 粘贴图片 / 拖拽文件支持 */\n"
    "  chatAttachRender();\n"
    "  chatGateCheck(); /* 进入新聊天先检查模型配置，未配置则禁用发送 */\n"
    "  /* issue #22: 切回对话面板时恢复本会话运行中任务的「取消」按钮与状态行 */\n"
    "  syncChatTaskId();\n"
    "  if(chatIsBusy()){\n"
    "    const st = $('chat-status');\n"
    "    if(st && !st.textContent) st.textContent = '任务执行中…';\n"
    "  }\n"
    "}\n"
    "\n"
    "/* Each conversation selects a registered route without changing global config. */\n"
    "let CHAT_ROUTES = [];\n"
    "async function fillChatModelSelect(){\n"
    "  const sel = $('chat-model'); if(!sel) return;\n"
    "  const session=CHAT_SESSION;\n"
    "  const r = await call('GET', '/v1/routes');\n"
    "  CHAT_ROUTES = Array.isArray(r.obj) ? r.obj : [];\n"
    "  const cur = await call('GET', '/v1/config/llm');\n"
    "  const curProv = (cur.obj && cur.obj.provider) || '';\n"
    "  const curModel = (cur.obj && cur.obj.model) || '';\n"
    "  if(CHAT_SESSION!==session || !sel.isConnected)return;\n"
    "  let html = '<option value=\"@cur\">默认模型：'+esc(curModel || curProv)+'</option>';\n"
    "  let matched = false;\n"
    "  CHAT_ROUTES.forEach(x => {\n"
    "    const val = x.name;\n"
    "    const isCur = curProv && curProv === x.provider && (curModel || '') === (x.model || '');\n"
    "    if(isCur) matched = true;\n"
    "    html += '<option value=\"' + esc(val) + '\">' + esc((x.name || x.model || 'route') + '（' + (x.provider || '?') +\n"
    "            (x.model ? ' / ' + x.model : '') + (isCur ? ' · 默认' : '') + '）') + '</option>';\n"
    "  });\n"
    "  sel.innerHTML = html;\n"
    "  const chosen=chatOptions(session).route;\n"
    "  sel.value=chosen && CHAT_ROUTES.some(x=>x.name===chosen)?chosen:'@cur';\n"
    "\n"
    "}\n"
    "\n"
    "async function chatModelSwitch(){\n"
    "  const value=$('chat-model')?.value;chatOptionSet('route',value==='@cur'?null:value);\n"
    "  toast(value==='@cur'?'本会话使用默认模型':'已设置本会话模型');\n"
    "}\n"
    "\n"
    "/* 后端返回裸数组 [{id,title,turns,created_ms,total_ms,last_active_ms,shared_memory,task}] */\n"
    "function chatSessionList(r){\n"
    "  const o = r && r.obj;\n"
    "  if(Array.isArray(o)) return o;\n"
    "  if(o && Array.isArray(o.sessions)) return o.sessions;\n"
    "  return [];\n"
    "}\n"
    "\n"
    "let CHAT_SESSION_NEXT=null, CHAT_SESSION_CURSOR='', CHAT_SESSION_PAGED=false;\n"
    "let CHAT_SESSION_LIST_SEQ=0, CHAT_SELECTED_INFO=null;\n"
    "async function loadChatSessions(cursor=''){\n"
    "  const seq=++CHAT_SESSION_LIST_SEQ;\n"
    "  const r = await call('GET', '/v1/chat/sessions?limit=12' + (cursor ? '&cursor='+encodeURIComponent(cursor):''));\n"
    "  if(seq!==CHAT_SESSION_LIST_SEQ || r.status!==200) return;\n"
    "  CHAT_SESSION_CURSOR=cursor;\n"
    "  CHAT_SESSION_NEXT=r.obj?.next_cursor || null;\n"
    "  CHAT_SESSION_PAGED=!!(r.obj && !Array.isArray(r.obj) && Array.isArray(r.obj.sessions));\n"
    "  const list = chatSessionList(r);\n"
    "  const selected=list.find(s=>s.id===CHAT_SESSION);\n"
    "  if(selected)CHAT_SELECTED_INFO=selected;\n"
    "  CHAT_TABS_CACHE=list;\n"
    "  renderChatTabs(list);\n"
    "  void chatReconcileRecentFailures(list);\n"
    "}\n"
    "\n"
    "/* sessionStorage can outlive an app update. If an older UI cached a false\n"
    " * failure, check that task's durable journal record before showing it in\n"
    " * Recent. This is a local history request and does not invoke the model. */\n"
    "async function chatReconcileRecentFailures(list){\n"
    "  const checks = [];\n"
    "  for(const info of (Array.isArray(list) ? list : []).slice(-12)){\n"
    "    const session = info.id || 'default';\n"
    "    const messages = CHAT_CACHE[session] || (session === CHAT_SESSION ? CHAT_MSGS : null);\n"
    "    const entry = messages && [...messages].reverse().find(m => m.role === 'bot' && m.progress);\n"
    "    if(!entry || entry.pending || entry.progress.stage !== 'failed' || entry.taskId == null || chatIsBusy(session)) continue;\n"
    "    const key = session + ':' + entry.taskId;\n"
    "    if(CHAT_RECENT_RECONCILED.has(key)) continue;\n"
    "    CHAT_RECENT_RECONCILED.add(key); /* coalesce concurrent list refreshes */\n"
    "    checks.push((async()=>{\n"
    "      const r = await call('GET','/v1/chat/history?session=' + encodeURIComponent(session));\n"
    "      if(r.status !== 200 || !Array.isArray(r.obj?.runs)) { CHAT_RECENT_RECONCILED.delete(key); return; }\n"
    "      const currentMessages = CHAT_CACHE[session] || (session === CHAT_SESSION ? CHAT_MSGS : null);\n"
    "      const currentEntry = currentMessages && [...currentMessages].reverse().find(m =>\n"
    "        m.role === 'bot' && String(m.taskId) === String(entry.taskId));\n"
    "      if(!currentEntry || currentEntry.pending) return;\n"
    "      const run = chatLatestRuns(r.obj.runs).find(item => String(item.id) === String(entry.taskId));\n"
    "      if(!run) { CHAT_RECENT_RECONCILED.delete(key); return; }\n"
    "      const stage = ({DONE:'completed',FAILED:'failed',CANCELLED:'cancelled',TIMEOUT:'timed_out',\n"
    "        INTERRUPTED:'interrupted',RUNNING:'interrupted',QUEUED:'interrupted'})[run.status];\n"
    "      if(!stage) { CHAT_RECENT_RECONCILED.delete(key); return; }\n"
    "      currentEntry.progress = {...currentEntry.progress,stage};\n"
    "      if(run.output && run.output !== '(no output)') currentEntry.text = run.output;\n"
    "      CHAT_CACHE[session] = currentMessages;\n"
    "      if(session === CHAT_SESSION){ CHAT_MSGS = currentMessages; chatRedraw(); }\n"
    "      else sideRecent(list);\n"
    "      chatPersist();\n"
    "    })());\n"
    "  }\n"
    "  await Promise.all(checks);\n"
    "}\n"
    "\n"
    "/* 会话时长格式化（total_ms → 「1分23秒」） */\n"
    "function fmtDur(ms){\n"
    "  if(!ms || ms < 1000) return '';\n"
    "  const s = Math.floor(ms / 1000);\n"
    "  if(s < 60) return s + '秒';\n"
    "  return Math.floor(s / 60) + '分' + (s % 60) + '秒';\n"
    "}\n"
    "\n"
    "/* 最近一次从服务端拿到的会话列表。chatNewSession / chatSwitchSession 刷新\n"
    " * 中途用空列表重绘（避免闪烁/清空），此时用缓存渲染，否则点「＋ 新会话」\n"
    " * 会把所有已有标签覆盖掉，只剩新的待发送会话 */\n"
    "let CHAT_TABS_CACHE = [];\n"
    "\n"
    "function renderChatTabs(list){\n"
    "  workspaceRender(list);\n"
    "  const bar = $('chat-tabs');\n"
    "  if(bar) bar.innerHTML = '';\n"
    "  if(list.length) CHAT_TABS_CACHE = list;\n"
    "  else if(CHAT_TABS_CACHE.length) list = CHAT_TABS_CACHE;\n"
    "  /* Hidden legacy tabs must not allocate a DOM node per stored session. */\n"
    "  const byId = new Map(list.map(s => [s.id || 'default',s]));\n"
    "  const ids = [...byId.keys()].slice(-12);\n"
    "  /* 当前会话的标签必须无条件可见：新建会话在后端注册前、发送首条消息后\n"
    "   * 的刷新空档，服务端列表都还不含它——缺失即补上，否则标签会被列表\n"
    "   * 重绘\"覆盖\"掉（新会话闪现后消失，或旧标签全被清空只剩新的）。 */\n"
    "  if(CHAT_SESSION !== 'default' && !ids.includes(CHAT_SESSION)) ids.push(CHAT_SESSION);\n"
    "  if(bar) ids.forEach(id => {\n"
    "    const info = byId.get(id);\n"
    "    const tab = document.createElement('span');\n"
    "    tab.className = 'chat-tab' + (id === CHAT_SESSION ? ' on' : '');\n"
    "    const name = document.createElement('span');\n"
    "    name.className = 'name';\n"
    "    const label = (info && info.title) ? info.title : (id === 'default' ? '默认会话' : id);\n"
    "    name.textContent = label.length > 18 ? label.slice(0, 18) + '…' : label;\n"
    "    name.title = chatSessionTip(info, id);\n"
    "    tab.appendChild(name);\n"
    "    if(info && info.turns != null){\n"
    "      const n = document.createElement('span');\n"
    "      n.style.cssText = 'color:var(--muted);font-size:11px';\n"
    "      n.textContent = info.turns;\n"
    "      tab.appendChild(n);\n"
    "    }\n"
    "    if(id !== 'default'){\n"
    "      const del = document.createElement('button');\n"
    "      del.className = 'del'; del.title = '清空该会话（保留会话）'; del.textContent = '×';\n"
    "      del.onclick = async (e) => { e.stopPropagation(); await chatClearSession(id); };\n"
    "      tab.appendChild(del);\n"
    "    }\n"
    "    /* issue #24: 彻底删除会话（含聊天记录文件），与「×清空」区分 */\n"
    "    const rm = document.createElement('button');\n"
    "    rm.className = 'del'; rm.title = '删除该会话（含聊天记录，不可恢复）'; rm.textContent = '🗑';\n"
    "    rm.style.marginLeft = '2px';\n"
    "    rm.onclick = async (e) => { e.stopPropagation(); await chatDeleteSession(id); };\n"
    "    tab.appendChild(rm);\n"
    "    tab.onclick = () => chatSwitchSession(id);\n"
    "    b.oncontextmenu=e=>{e.preventDefault();chatSessionMenu(e,id,label);};\n"
    "    bar.appendChild(tab);\n"
    "  });\n"
    "  if(bar){\n"
    "    const plus = document.createElement('span');\n"
    "    plus.className = 'chat-tab new';\n"
    "    plus.textContent = '＋ 新会话';\n"
    "    plus.onclick = chatNewSession;\n"
    "    bar.appendChild(plus);\n"
    "  }\n"
    "  sideRecent(list);\n"
    "  syncChatSettings();\n"
    "}\n"
    "\n"
    "/* 会话提示文本：标题 / 轮次 / 创建时间 / 累计执行时长 / 共享记忆 */\n"
    "function chatSessionTip(info, id){\n"
    "  if(!info) return id;\n"
    "  const bits = [];\n"
    "  bits.push((info.title || id) + '（' + (info.turns || 0) + ' 轮）');\n"
    "  if(info.created_ms) bits.push('创建 ' + new Date(info.created_ms).toLocaleString());\n"
    "  if(info.total_ms) bits.push('累计执行 ' + fmtDur(info.total_ms));\n"
    "  bits.push(info.shared_memory === true ? '记忆：共享' : '记忆：私有');\n"
    "  return bits.join(' · ');\n"
    "}\n"
    "\n"
    "/* 侧边栏「最近」会话列表（ChatGPT 风格）：新建的会话自动归档到这里 */\n"
    "function sideRecent(list){\n"
    "  const box = $('side-recent'); if(!box) return;\n"
    "  const nav = $('nav'), scrollTop = nav?.scrollTop || 0;\n"
    "  box.querySelectorAll('.workspace-group').forEach(d=>WORKSPACE_FOLDS.set(d.dataset.path,d.open));\n"
    "  box.innerHTML = '';\n"
    "  const add=document.createElement('button');add.className='sec sm';add.textContent='＋ 添加工作区';add.onclick=workspaceDialog;box.append(add);\n"
    "  const groups=new Map();\n"
    "  function group(path){\n"
    "    path=path || WORKSPACE_DEFAULT || '';\n"
    "    if(groups.has(path))return groups.get(path);\n"
    "    const details=document.createElement('details');details.className='workspace-group';details.dataset.path=path;\n"
    "    details.open=WORKSPACE_FOLDS.has(path)?WORKSPACE_FOLDS.get(path):true;\n"
    "    const summary=document.createElement('summary');summary.innerHTML='<svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" aria-hidden=\"true\"><path d=\"M3 7V5a2 2 0 0 1 2-2h5l3 3h6a2 2 0 0 1 2 2v2M3 8h18l-3 12H2z\"/></svg>';\n"
    "    const label=document.createElement('span');label.textContent=workspaceLabel(path);summary.title=path;summary.append(label);\n"
    "    const create=document.createElement('button');create.textContent='＋';create.title='在此工作区新建聊天';create.setAttribute('aria-label','在 '+label.textContent+' 新建聊天');\n"
    "    create.onclick=async e=>{e.preventDefault();e.stopPropagation();CHAT_WORKSPACE=path;await chatNewSession();if(current!=='chat')switchPanel('chat');};\n"
    "    summary.append(create);details.append(summary);box.append(details);groups.set(path,details);return details;\n"
    "  }\n"
    "  orderedWorkspaces().forEach(w=>group(w.path));\n"
    "  /* The API list preserves session creation order. Recent must reflect\n"
    "   * activity, including conversations revisited after a newer one was made. */\n"
    "  const ordered = [...list].sort((a,b) => {\n"
    "    const activity = s => Number(s.last_active_ms) || Number(s.created_ms) || 0;\n"
    "    return activity(b) - activity(a);\n"
    "  });\n"
    "  const ids = ordered.map(s => s.id || 'default');\n"
    "  /* Keep the selected conversation visible even when an older list response\n"
    "   * excludes it or twelve older rows have later activity timestamps. */\n"
    "  if(CHAT_SESSION !== 'default'){\n"
    "    const index=ids.indexOf(CHAT_SESSION);\n"
    "    if(index>=0) ids.splice(index,1);\n"
    "    ids.unshift(CHAT_SESSION);\n"
    "  }\n"
    "  const windowSize=CHAT_SESSION_PAGED ? 13:12;\n"
    "  const visibleIds=new Set(ids.slice(0,windowSize));\n"
    "  const visible = new Map(ordered.filter(s=>visibleIds.has(s.id || 'default')).map(s=>[s.id || 'default',s]));\n"
    "  ids.slice(0,windowSize).forEach(id => {\n"
    "    const info = visible.get(id) || (CHAT_SELECTED_INFO?.id===id ? CHAT_SELECTED_INFO:null);\n"
    "    const row = document.createElement('div');\n"
    "    row.className = 'side-recent-row';\n"
    "    const b = document.createElement('button');\n"
    "    b.className = id === CHAT_SESSION ? 'on' : '';\n"
    "    const label = (info && info.title) ? info.title : (id === 'default' ? '默认会话' : id);\n"
    "    const title = document.createElement('span'); title.className = 'recent-session-title';\n"
    "    title.textContent = label;\n"
    "    const messages = CHAT_CACHE[id] || [];\n"
    "    const latest = [...messages].reverse().find(m => m.role === 'bot' && m.progress);\n"
    "    const active = chatTaskOf(id) !== null || info?.running === true;\n"
    "    const persisted=info?.last_run;\n"
    "    const usePersisted=persisted && (!latest || latest.taskId==null || Number(persisted.id)>=Number(latest.taskId));\n"
    "    const stage = usePersisted ? ({DONE:'completed',FAILED:'failed',CANCELLED:'cancelled',TIMEOUT:'timed_out',INTERRUPTED:'interrupted',RUNNING:'running',QUEUED:'running'})[persisted.status] : latest?.progress?.stage;\n"
    "    const taskStatus = document.createElement('small'); taskStatus.className = 'recent-task-status';\n"
    "    taskStatus.setAttribute('role','status');\n"
    "    taskStatus.dataset.state = active ? 'running' : (stage || 'idle');\n"
    "    taskStatus.textContent = active || stage === 'running' ? '执行中' : stage === 'completed' ? '已完成' :\n"
    "      stage === 'failed' ? '失败' : stage === 'timed_out' ? '超时' : stage === 'cancelled' ? '已取消' :\n"
    "      stage === 'interrupted' ? '已中断' : '空闲';\n"
    "    taskStatus.style.color = active ? 'var(--accent)' : stage === 'failed' ? 'var(--danger)' : 'var(--muted)';\n"
    "    taskStatus.style.marginLeft = '0';\n"
    "    b.append(taskStatus, title);\n"
    "    b.title = chatSessionTip(info, id);\n"
    "    b.onclick = () => chatSwitchSession(id);\n"
    "    b.oncontextmenu=e=>{e.preventDefault();chatSessionMenu(e,id,label);};\n"
    "    row.appendChild(b);\n"
    "    const del = document.createElement('button');\n"
    "    del.className = 'side-recent-delete';\n"
    "    del.title = '删除该会话及聊天记录';\n"
    "    del.setAttribute('aria-label', del.title);\n"
    "    del.textContent = '🗑';\n"
    "    del.onclick = async (e) => { e.stopPropagation(); await chatDeleteSession(id); };\n"
    "    row.appendChild(del);\n"
    "    group(info?.workspace || WORKSPACE_DEFAULT).appendChild(row);\n"
    "  });\n"
    "  if(CHAT_SESSION_NEXT){\n"
    "    const more=document.createElement('button');more.id='recent-older';more.textContent='更早会话';\n"
    "    more.onclick=()=>loadChatSessions(CHAT_SESSION_NEXT);box.appendChild(more);\n"
    "  }\n"
    "  if(CHAT_SESSION_CURSOR){\n"
    "    const newest=document.createElement('button');newest.id='recent-newest';newest.textContent='返回最近会话';\n"
    "    newest.onclick=()=>loadChatSessions();box.appendChild(newest);\n"
    "  }\n"
    "  if(nav) nav.scrollTop = scrollTop;\n"
    "}\n"
    "\n"
    "/* ===== 新聊天设置区（模型配置 / 共享记忆）===== */\n"
    "\n"
    "function chatToggleSettings(){\n"
    "  const el = $('chat-settings');\n"
    "  if(!el) return;\n"
    "  const open = el.style.display === 'none';\n"
    "  el.style.display = open ? '' : 'none';\n"
    "  $('chat-wrap')?.classList.toggle('settings-open',open);\n"
    "}\n"
    "\n"
    "let SSH_ENVIRONMENTS = [];\n"
    "async function sshSessionLoad(){\n"
    "  const session = CHAT_SESSION;\n"
    "  const r = await call('GET','/v1/ssh/session?session=' + encodeURIComponent(session));\n"
    "  if(session !== CHAT_SESSION) return;\n"
    "  const list = $('ssh-session-list'); if(!list) return;\n"
    "  list.innerHTML = '';\n"
    "  if(r.status !== 200 || !Array.isArray(r.obj)){ list.textContent = '会话环境加载失败'; return; }\n"
    "  if(!r.obj.length){ list.textContent = '本会话尚无 SSH 连接'; return; }\n"
    "  for(const env of r.obj){\n"
    "    const item = document.createElement('span'); item.className = 'chip';\n"
    "    item.textContent = (env.environment || env.host || 'SSH') +\n"
    "      (env.user ? ' · ' + env.user : '') + ':' + (env.port || 22) +\n"
    "      (env.has_password ? ' · 已托管密码' : ' · 私钥/agent');\n"
    "    const forget = document.createElement('button');\n"
    "    forget.className = 'sec sm'; forget.textContent = '忘记';\n"
    "    forget.title = '移除本会话中的这条连接和凭据';\n"
    "    forget.onclick = () => sshSessionForget(session,env.key);\n"
    "    item.appendChild(forget); list.appendChild(item);\n"
    "  }\n"
    "}\n"
    "async function sshSessionForget(session,key){\n"
    "  const r = await call('DELETE','/v1/ssh/session?session=' + encodeURIComponent(session) + '&key=' + encodeURIComponent(key));\n"
    "  toast(r.status < 300 ? '已忘记本会话的 SSH 连接' : '移除失败');\n"
    "  if(r.status < 300 && session === CHAT_SESSION) await sshSessionLoad();\n"
    "}\n"
    "async function sshEnvironmentLoad(){\n"
    "  const r = await call('GET', '/v1/ssh/environments');\n"
    "  const list = $('ssh-environment-list');\n"
    "  if(!list) return;\n"
    "  if(r.status !== 200 || !Array.isArray(r.obj)){\n"
    "    list.textContent = '环境加载失败'; return;\n"
    "  }\n"
    "  SSH_ENVIRONMENTS = r.obj;\n"
    "  list.innerHTML = '';\n"
    "  if(!SSH_ENVIRONMENTS.length){ list.textContent = '暂无 SSH 环境'; return; }\n"
    "  for(const env of SSH_ENVIRONMENTS){\n"
    "    const b = document.createElement('button');\n"
    "    b.className = 'sec sm';\n"
    "    b.textContent = env.name + ' · ' + env.host + (env.has_password ? ' · 已托管密码' : ' · 私钥/agent');\n"
    "    b.onclick = () => {\n"
    "      $('ssh-env-name').value = env.name || '';\n"
    "      $('ssh-env-host').value = env.host || '';\n"
    "      $('ssh-env-user').value = env.user || '';\n"
    "      $('ssh-env-port').value = env.port || 22;\n"
    "      $('ssh-env-identity').value = env.identity_file || '';\n"
    "      $('ssh-env-known').value = env.known_hosts || '';\n"
    "      $('ssh-env-password').value = '';\n"
    "    };\n"
    "    const del = document.createElement('button');\n"
    "    del.className = 'sec sm'; del.textContent = '删除 ' + env.name;\n"
    "    del.onclick = () => sshEnvironmentDelete(env.name);\n"
    "    list.append(b, del);\n"
    "  }\n"
    "}\n"
    "\n"
    "async function sshEnvironmentSave(){\n"
    "  const name = $('ssh-env-name')?.value.trim();\n"
    "  const host = $('ssh-env-host')?.value.trim();\n"
    "  const status = $('ssh-env-status');\n"
    "  if(!name || !host){ if(status) status.textContent = '请填写环境名称和主机'; return; }\n"
    "  const body = {name, host, user:$('ssh-env-user').value.trim(),\n"
    "    port:Number($('ssh-env-port').value) || 22,\n"
    "    identity_file:$('ssh-env-identity').value.trim(),\n"
    "    known_hosts:$('ssh-env-known').value.trim()};\n"
    "  const password = $('ssh-env-password').value;\n"
    "  if(password) body.password = password;\n"
    "  const r = await call('POST', '/v1/ssh/environments', body);\n"
    "  $('ssh-env-password').value = '';\n"
    "  if(status) status.textContent = r.status < 300 ? '已保存 ' + name : '保存失败：' + (r.obj?.error || r.status);\n"
    "  if(r.status < 300) await sshEnvironmentLoad();\n"
    "}\n"
    "\n"
    "async function sshEnvironmentDelete(name){\n"
    "  const r = await call('DELETE', '/v1/ssh/environments/' + encodeURIComponent(name));\n"
    "  const status = $('ssh-env-status');\n"
    "  if(status) status.textContent = r.status < 300 ? '已删除 ' + name : '删除失败：' + (r.obj?.error || r.status);\n"
    "  if(r.status < 300) await sshEnvironmentLoad();\n"
    "}\n"
    "async function sshCredentialClear(){\n"
    "  const host = $('ssh-env-host').value.trim();\n"
    "  const user = $('ssh-env-user').value.trim();\n"
    "  const port = Number($('ssh-env-port').value) || 22;\n"
    "  const status = $('ssh-env-status');\n"
    "  if(!host){ if(status) status.textContent = '请先填写要清除凭据的主机'; return; }\n"
    "  const r = await call('DELETE','/v1/ssh/credentials',{host,user,port});\n"
    "  if(status) status.textContent = r.status < 300 ? '已清除该主机的直连凭据' : '清除失败：' + (r.obj?.error || r.status);\n"
    "}\n"
    "\n"
    "/* 用当前会话信息同步设置区（共享记忆勾选 + 会话元数据） */\n"
    "function syncChatSettings(){\n"
    "  const info = CHAT_TABS_CACHE.find(s => (s.id || 'default') === CHAT_SESSION);\n"
    "  const cb = $('chat-shared');\n"
    "  if(cb) cb.checked = CHAT_TABS_CACHE[0]?.shared_memory === true;\n"
    "  syncChatThinkingToggle();syncChatPermission();void fillChatModelSelect();\n"
    "  const meta = $('chat-session-meta');\n"
    "  if(meta){\n"
    "    const bits = [];\n"
    "    if(info && info.created_ms) bits.push('创建 ' + new Date(info.created_ms).toLocaleString());\n"
    "    if(info && info.total_ms) bits.push('累计执行 ' + fmtDur(info.total_ms));\n"
    "    meta.textContent = bits.length ? bits.join(' · ') : '新会话';\n"
    "  }\n"
    "}\n"
    "\n"
    "function chatSessionMenu(e,id,title){\n"
    "  document.getElementById('session-menu')?.remove();\n"
    "  const menu=document.createElement('div');menu.id='session-menu';menu.setAttribute('role','menu');\n"
    "  menu.style.cssText='position:fixed;z-index:200;background:var(--card);border:1px solid var(--border);border-radius:10px;padding:6px;box-shadow:0 8px 24px #0003';\n"
    "  const edit=document.createElement('button');edit.textContent='修改会话标题 / 简介';edit.setAttribute('role','menuitem');\n"
    "  edit.onclick=()=>{menu.remove();chatRenameSession(id,title);};menu.append(edit);document.body.append(menu);\n"
    "  menu.style.left=Math.min(e.clientX,innerWidth-menu.offsetWidth-8)+'px';menu.style.top=Math.min(e.clientY,innerHeight-menu.offsetHeight-8)+'px';edit.focus();\n"
    "  const close=event=>{if(!menu.contains(event.target)){menu.remove();document.removeEventListener('pointerdown',close);}};\n"
    "  document.addEventListener('pointerdown',close);menu.onkeydown=event=>{if(event.key==='Escape'){menu.remove();document.removeEventListener('pointerdown',close);}};\n"
    "}\n"
    "function chatRenameSession(id,title){\n"
    "  document.getElementById('session-rename')?.remove();const d=document.createElement('dialog');d.id='session-rename';\n"
    "  d.innerHTML='<form><h3>修改会话标题 / 简介</h3><input aria-label=\"会话标题\" required maxlength=\"40\"><p role=\"alert\"></p><button type=\"button\">取消</button> <button type=\"submit\">保存</button></form>';\n"
    "  const input=d.querySelector('input');input.value=title;d.querySelector('button').onclick=()=>d.close();\n"
    "  d.querySelector('form').onsubmit=async e=>{e.preventDefault();const value=input.value.trim();if(!value)return;\n"
    "    const r=await call('POST','/v1/chat/sessions/'+encodeURIComponent(id)+'/title',{title:value});\n"
    "    if(r.status!==200){d.querySelector('p').textContent=r.obj?.error || '保存失败';return;}\n"
    "    CHAT_TABS_CACHE.forEach(s=>{if(s.id===id)s.title=value;});if(CHAT_SELECTED_INFO?.id===id)CHAT_SELECTED_INFO.title=value;sideRecent(CHAT_TABS_CACHE);d.close();};\n"
    "  d.onclose=()=>d.remove();document.body.append(d);d.showModal();input.select();\n"
    "}\n"
    "function chatThinkingEnabled(){\n"
    "  try { return localStorage.getItem('cognitive-thinking-mode:' + CHAT_SESSION) === '1'; } catch(e) { return false; }\n"
    "}\n"
    "function syncChatThinkingToggle(){\n"
    "  const btn = $('chat-thinking-toggle');\n"
    "  if(!btn) return;\n"
    "  const enabled = chatThinkingEnabled();\n"
    "  btn.classList.toggle('on', enabled);\n"
    "  btn.setAttribute('aria-pressed', String(enabled));\n"
    "  btn.querySelector('span').textContent=enabled?'深度思考 · 已开启':'深度思考';\n"
    "  btn.title = enabled ? '深度思考已开启：允许额外规划轮次' : '深度思考：允许额外规划轮次，适合复杂问题';\n"
    "}\n"
    "function chatThinkingToggle(enabled){\n"
    "  try { localStorage.setItem('cognitive-thinking-mode:' + CHAT_SESSION, enabled ? '1' : '0'); } catch(e) {}\n"
    "  syncChatThinkingToggle();\n"
    "  toast(enabled ? '已开启深度思考：复杂问题可进行额外规划。' : '已关闭深度思考：优先直接回答或执行必要工具。');\n"
    "}\n"
    "\n"
    "/* 全局共享记忆开关，兼容旧的会话设置 API。 */\n"
    "async function chatSharedToggle(shared){\n"
    "  const r = await call('POST', '/v1/chat/sessions/' + encodeURIComponent(CHAT_SESSION) + '/shared', {shared: !!shared});\n"
    "  if(r.status < 300){\n"
    "    toast(shared ? '已开启全局共享记忆' : '已关闭全局共享记忆');\n"
    "    CHAT_TABS_CACHE.forEach(info => { info.shared_memory = shared; });\n"
    "  } else {\n"
    "    toast('设置失败：' + (r.obj && r.obj.error || r.status));\n"
    "    syncChatSettings();\n"
    "  }\n"
    "}\n"
    "\n"
    "/* ===== 模型配置门禁：未配置模型不能使用新聊天 ===== */\n"
    "\n"
    "async function chatGateCheck(){\n"
    "  const gate = $('chat-gate'), send = $('chat-send'), input = $('chat-input');\n"
    "  let ok = false, prov = '', keySet = false;\n"
    "  try {\n"
    "    const r = await call('GET', '/v1/config/llm');\n"
    "    const o = r.obj || {};\n"
    "    prov = o.provider || '';\n"
    "    keySet = !!o.api_key_set;\n"
    "    ok = !!(prov && prov !== 'mock' && keySet);\n"
    "  } catch(e) {}\n"
    "  if(gate) gate.style.display = ok ? 'none' : '';\n"
    "  if(send) send.disabled = !ok;\n"
    "  if(input) input.disabled = !ok;\n"
    "  return ok;\n"
    "}\n"
    "\n"
    "async function chatLoadHistory(){\n"
    "  const box = $('chat-box'); if(!box) return;\n"
    "  if(!chatLoadHistory._seq) chatLoadHistory._seq = 0;\n"
    "  const seq = ++chatLoadHistory._seq;\n"
    "  // 先回放本地缓存（切页/切会话不闪空），再让服务端历史兜底刷新\n"
    "  const cached = CHAT_CACHE[CHAT_SESSION];\n"
    "  if(cached && cached.length && !CHAT_MSGS.length){ CHAT_MSGS = cached; chatRedraw(); }\n"
    "  // 有进行中的回复时不要用服务端历史覆盖本地视图（本轮 q/a 还没入库）\n"
    "  if(CHAT_MSGS.some(m => m.pending)){ return; }\n"
    "  const session = CHAT_SESSION;\n"
    "  $('chat-history-loading')?.remove();\n"
    "  const loading=document.createElement('div');loading.id='chat-history-loading';loading.className='hint';loading.setAttribute('role','status');loading.textContent='正在完整加载会话记录…';box.before(loading);\n"
    "  const r = await call('GET', '/v1/chat/history?session=' + encodeURIComponent(session)).catch(()=>({status:0}));\n"
    "  if(session !== CHAT_SESSION || chatIsBusy(session) || seq !== chatLoadHistory._seq){loading.remove();return;}\n"
    "  if(r.status !== 200 || !r.obj || !Array.isArray(r.obj.turns)){\n"
    "    loading.textContent='历史记录加载失败，已有内容已保留。';\n"
    "    const retry=document.createElement('button');retry.textContent='重新加载';retry.onclick=()=>chatLoadHistory();loading.append(retry);return;\n"
    "  }\n"
    "  /* The request may finish after the user has switched away and back again.\n"
    "     Keep a monotonically increasing per-load token so only the newest fetch\n"
    "     * for this session can replace its local view. */\n"
    "  if(session !== CHAT_SESSION || seq !== chatLoadHistory._seq) return;\n"
    "  const old = CHAT_MSGS;\n"
    "  CHAT_MSGS = chatHistoryEntries(r.obj.turns, r.obj.runs);\n"
    "  // Preserve attachment identities for repeated questions in their original order.\n"
    "  const imageMessages = old.filter(m=>m.role==='user' && m.images?.length);\n"
    "  for(const m of CHAT_MSGS){\n"
    "    if(m.role !== 'user') continue;\n"
    "    const i=imageMessages.findIndex(x=>x.text===m.text);\n"
    "    if(i>=0) m.images=imageMessages.splice(i,1)[0].images;\n"
    "  }\n"
    "  chatRedraw();\n"
    "  loading.textContent='历史记录已完整加载 · '+r.obj.turns.length+' 轮对话';\n"
    "}\n"
    "\n"
    "/* The durable journal appends one record for each task transition (RUNNING,\n"
    " * then DONE/FAILED, etc.). Keep only the latest record per task before\n"
    " * matching journal rows to turns; otherwise the first RUNNING row can mask a\n"
    " * later successful completion and make an old chat look failed. */\n"
    "function chatLatestRuns(runs){\n"
    "  const latest = new Map(), unkeyed = [];\n"
    "  for(const run of Array.isArray(runs) ? runs : []){\n"
    "    if(!run) continue;\n"
    "    if(run.id == null){ unkeyed.push(run); continue; }\n"
    "    const key = String(run.id), previous = latest.get(key);\n"
    "    if(!previous || (Number(run.ts) || 0) >= (Number(previous.ts) || 0)) latest.set(key, run);\n"
    "  }\n"
    "  return [...latest.values(), ...unkeyed].sort((a,b)=>(Number(a.ts)||0)-(Number(b.ts)||0));\n"
    "}\n"
    "\n"
    "function chatHistoryEntries(turns, runs){\n"
    "  const rows = turns.filter(t => t.q).map(t => ({q:t.q, a:t.a || '', run:null}));\n"
    "  const failures = [];\n"
    "  let next = 0;\n"
    "  for(const run of chatLatestRuns(runs)){\n"
    "    if(!run || !run.input) continue;\n"
    "    let match = -1;\n"
    "    for(let i = next; i < rows.length; i++){\n"
    "      const row = rows[i];\n"
    "      if(row.run || !run.input.startsWith(row.q)) continue;\n"
    "      if(run.output && row.a && !run.output.startsWith(row.a) && !row.a.startsWith(run.output)) continue;\n"
    "      match = i; break;\n"
    "    }\n"
    "    if(match >= 0){ rows[match].run = run; next = match + 1; }\n"
    "    else if(run.status && run.status !== 'DONE'){\n"
    "      const fallback = ({RUNNING:'任务运行状态已丢失（服务可能重启），会话记录已保留，可点击“恢复”继续。',\n"
    "        QUEUED:'任务尚未开始且执行状态已丢失，会话记录已保留，可点击“恢复”继续。',\n"
    "        INTERRUPTED:'任务已中断，会话记录已保留，可点击“恢复”继续。',\n"
    "        FAILED:'任务未能完成，会话记录已保留，可点击“恢复”重试。',\n"
    "        CANCELLED:'任务已取消，会话记录已保留。',\n"
    "        TIMEOUT:'任务执行超时，会话记录已保留，可点击“恢复”重试。'})[run.status] || '任务状态异常，会话记录已保留，可点击“恢复”重试。';\n"
    "      failures.push({q:run.input, a:run.output || fallback, run});\n"
    "    }\n"
    "  }\n"
    "  for(const failed of failures){\n"
    "    const after = rows.findIndex(row => row.run && row.run.ts > failed.run.ts);\n"
    "    rows.splice(after < 0 ? rows.length : after, 0, failed);\n"
    "  }\n"
    "  const messages = [];\n"
    "  for(const row of rows){\n"
    "    const events = Array.isArray(row.run?.trace) ? row.run.trace : [];\n"
    "    const started = events.find(p => Number(p.started_ms)>0)?.started_ms;\n"
    "    messages.push({role:'user',text:row.q,pending:false,el:null,timestamp_ms:started || row.run?.ts || 0});\n"
    "    if(!row.a && !row.run) continue;\n"
    "    const run = row.run;\n"
    "    const trace = Array.isArray(run?.trace) ? run.trace : [];\n"
    "    const last = trace[trace.length - 1] || {};\n"
    "    const stage = ({DONE:'completed',FAILED:'failed',CANCELLED:'cancelled',TIMEOUT:'timed_out',\n"
    "      INTERRUPTED:'interrupted',RUNNING:'interrupted',QUEUED:'interrupted'})[run?.status] || 'failed';\n"
    "    messages.push({role:'bot',text:row.a,pending:false,el:null,timestamp_ms:run?.ts || 0,\n"
    "      ...(run ? {taskId:run.id,progress:{...last,stage},progressEvents:trace} : {})});\n"
    "  }\n"
    "  return messages;\n"
    "}\n"
    "\n"
    "async function chatSwitchSession(id){\n"
    "  chatApproval({},id);\n"
    "  if(id === CHAT_SESSION){ switchPanel('chat'); chatFocusComposer(id); return; }\n"
    "  chatCacheStore(); // 保存当前会话消息，切回时即时回放\n"
    "  CHAT_SELECTED_INFO=CHAT_TABS_CACHE.find(s=>s.id===id) || null;\n"
    "  CHAT_SESSION = id;\n"
    "  chatAttachActivate(id);\n"
    "  if($('ssh-session-details')?.open) void sshSessionLoad();\n"
    "  CHAT_NEW_SESSION = false;\n"
    "  CHAT_MSGS = CHAT_CACHE[id] || [];\n"
    "  if(current !== 'chat') switchPanel('chat');\n"
    "  else { renderChatTabs(CHAT_TABS_CACHE); chatRedraw(true); void chatLoadHistory(); }\n"
    "  void loadChatSessions();\n"
    "  void chatGateCheck().then(() => chatFocusComposer(id));\n"
    "  /* issue #22: 切回的会话若任务仍在执行，恢复「取消」按钮与状态行 */\n"
    "  syncChatTaskId();\n"
    "  if(chatIsBusy(id)){\n"
    "    const st = $('chat-status');\n"
    "    if(st) st.textContent = '任务执行中…';\n"
    "  }\n"
    "}\n"
    "\n"
    "function chatFocusComposer(session){\n"
    "  requestAnimationFrame(() => {\n"
    "    if(current !== 'chat' || CHAT_SESSION !== session) return;\n"
    "    chatScroll(true);\n"
    "    const input = $('chat-input');\n"
    "    if(input && !input.disabled) input.focus({preventScroll:true});\n"
    "  });\n"
    "}\n"
    "\n"
    "let CHAT_NEW_SESSION_REQUEST = null;\n"
    "async function chatNewSession(options={}){\n"
    "  chatApproval({},CHAT_SESSION);\n"
    "  /* Panel initialization may join an in-flight creation. An explicit New Chat\n"
    "     click must create its own session, even while the previous creation is\n"
    "     still loading configuration; queue it instead of selecting that session. */\n"
    "  if(CHAT_NEW_SESSION_REQUEST){\n"
    "    if(options?.ensure === true) return CHAT_NEW_SESSION_REQUEST;\n"
    "    await CHAT_NEW_SESSION_REQUEST;\n"
    "    return chatNewSession(options);\n"
    "  }\n"
    "  const request = (async()=>{\n"
    "  if(options?.discardCurrent !== true)\n"
    "    chatCacheStore(); // 保存当前会话消息（切回时即时回放）；旧会话自动归档到「最近」\n"
    "  /* Create a durable session before switching the visible conversation. */\n"
    "  const r = await call('POST', '/v1/chat/sessions', CHAT_WORKSPACE ? {workspace:CHAT_WORKSPACE} : {});\n"
    "  const id = r.obj && r.obj.id;\n"
    "  if(r.status < 200 || r.status >= 300 || typeof id !== 'string' || !id){\n"
    "    const reason = r.obj && r.obj.error || (r.status === 0 ? '连接失败' : 'HTTP ' + r.status);\n"
    "    const status = $('chat-status');\n"
    "    if(status) status.textContent = '新建聊天失败：' + reason;\n"
    "    toast('新建聊天失败：' + reason);\n"
    "    return false;\n"
    "  }\n"
    "  CHAT_SELECTED_INFO={id,workspace:r.obj.workspace,turns:0,created_ms:Date.now()};\n"
    "  CHAT_SESSION = id;\n"
    "  chatAttachActivate(CHAT_SESSION);\n"
    "  if($('ssh-session-details')?.open) void sshSessionLoad();\n"
    "  CHAT_NEW_SESSION = false; /* 后端已注册时无需等首条消息 */\n"
    "  CHAT_TABS_CACHE = [...CHAT_TABS_CACHE.filter(s => (s.id || 'default') !== id), {id, workspace:r.obj.workspace, turns:0, created_ms:Date.now(), last_active_ms:Date.now()}];\n"
    "  CHAT_MSGS = [];\n"
    "  renderChatTabs([]);\n"
    "  const box = $('chat-box'); if(box) box.innerHTML = '';\n"
    "  updateChatHero();\n"
    "  const st = $('chat-status');\n"
    "  if(st) st.textContent = '新会话已创建，正在检查模型配置…';\n"
    "  syncChatTaskId(); /* 新会话无任务，隐藏「取消」按钮 */\n"
    "  chatFocusComposer(CHAT_SESSION);\n"
    "  /* Model configuration is separate from session creation. A slow provider\n"
    "     must not keep New Chat locked to an already-created conversation. */\n"
    "  void chatGateCheck().then(ok=>{\n"
    "    if(CHAT_SESSION !== id || current !== 'chat') return;\n"
    "    const status = $('chat-status');\n"
    "    if(status) status.textContent = ok ? '新会话：已就绪' : '尚未配置模型，请在上方设置里先配置对话模型';\n"
    "    void fillChatModelSelect();\n"
    "    chatFocusComposer(id);\n"
    "  });\n"
    "  void loadChatSessions();\n"
    "  return true;\n"
    "  })();\n"
    "  CHAT_NEW_SESSION_REQUEST = request;\n"
    "  try { return await request; }\n"
    "  finally { if(CHAT_NEW_SESSION_REQUEST === request) CHAT_NEW_SESSION_REQUEST = null; }\n"
    "}\n"
    "\n"
    "async function chatClearSession(id){\n"
    "  if(chatIsBusy(id)){ toast('该会话任务执行中，请先取消或等待完成'); return; }\n"
    "  await call('DELETE', '/v1/chat/sessions/' + encodeURIComponent(id));\n"
    "  CHAT_ATTACH_DRAFTS.delete(id);\n"
    "  if(id===CHAT_SESSION) chatAttachActivate(id);\n"
    "  if(id === CHAT_SESSION){\n"
    "    CHAT_MSGS = [];\n"
    "    const box = $('chat-box'); if(box) box.innerHTML = '';\n"
    "  }\n"
    "  CHAT_NEW_SESSION = false;\n"
    "  loadChatSessions();\n"
    "  toast(id === 'default' ? '默认会话已清空' : ('会话 ' + id + ' 已清空'));\n"
    "}\n"
    "\n"
    "/* issue #24: 彻底删除会话（注册表 + 元数据索引 + 聊天记录文件），与「清空」不同 */\n"
    "async function chatDeleteSession(id){\n"
    "  const label = id === 'default' ? '默认会话' : ('会话 ' + id);\n"
    "  if(!confirm('删除' + label + '及其全部聊天记录？此操作不可恢复。')) return;\n"
    "  if(chatIsBusy(id)){ toast('该会话任务执行中，请先取消或等待完成'); return; }\n"
    "  const r = await call('POST', '/v1/chat/sessions/' + encodeURIComponent(id) + '/delete', {});\n"
    "  if(r.status >= 300){ toast('删除失败：' + ((r.obj && r.obj.error) || r.status)); return; }\n"
    "  delete CHAT_CACHE[id];\n"
    "  CHAT_ATTACH_DRAFTS.delete(id);\n"
    "  CHAT_TABS_CACHE = CHAT_TABS_CACHE.filter(s => (s.id || 'default') !== id);\n"
    "  if(id === CHAT_SESSION){\n"
    "    CHAT_MSGS = [];\n"
    "    const rest = CHAT_TABS_CACHE;\n"
    "    if(rest.length){\n"
    "      await chatSwitchSession(rest[rest.length - 1].id || 'default');\n"
    "    } else {\n"
    "      await chatNewSession({discardCurrent:true});\n"
    "    }\n"
    "  } else {\n"
    "    renderChatTabs([]);\n"
    "  }\n"
    "  loadChatSessions();\n"
    "  toast(label + '已删除');\n"
    "}\n"
    "\n"
    "function chatImageSource(value){\n"
    "  if(/^data:image\\/(png|jpeg|webp|gif);base64,[a-z0-9+/=\\s]+$/i.test(value || '')) return value;\n"
    "  try { const url=new URL(value,location.href); return /^https?:$/.test(url.protocol) ? url.href : ''; } catch(e){ return ''; }\n"
    "}\n"
    "function chatImageButton(src,name){\n"
    "  const button=document.createElement('button'); button.type='button'; button.className='chat-image-button';\n"
    "  const image=document.createElement('img'); image.className='chat-image'; image.alt=name || '聊天图片'; image.style.cssText='width:auto;height:auto'; image.src=src; image.referrerPolicy='no-referrer';\n"
    "  button.append(image); button.title='点击放大图片';\n"
    "  button.onclick=()=>{\n"
    "    const dialog=document.createElement('dialog'); dialog.style.maxWidth='95vw';\n"
    "    const close=document.createElement('button'); close.textContent='关闭'; close.onclick=()=>dialog.close();\n"
    "    const full=document.createElement('img'); full.src=src; full.alt=image.alt; full.style.cssText='display:block;max-width:85vw;max-height:80vh;object-fit:contain';\n"
    "    dialog.append(close,full); document.body.append(dialog); dialog.addEventListener('close',()=>dialog.remove(),{once:true}); dialog.showModal();\n"
    "  };\n"
    "  return button;\n"
    "}\n"
    "function chatRenderInline(el,text){\n"
    "  const pattern=/!\\[([^\\]\\n]*)\\]\\(([^\\s)]+)\\)/g;\n"
    "  let start=0, match;\n"
    "  while((match=pattern.exec(text || ''))){\n"
    "    const src=chatImageSource(match[2]); if(!src) continue;\n"
    "    el.append(document.createTextNode(text.slice(start,match.index)),chatImageButton(src,match[1])); start=pattern.lastIndex;\n"
    "  }\n"
    "  el.append(document.createTextNode((text || '').slice(start)));\n"
    "}\n"
    "function chatRenderText(el,text){\n"
    "  const lines=String(text||'').split('\\n');let code=null;\n"
    "  for(const line of lines){\n"
    "    if(/^\\s*```/.test(line)){\n"
    "      if(code){el.append(code);code=null;}else{code=document.createElement('code');code.style.cssText='display:block;white-space:pre-wrap;background:var(--bg);padding:12px;border-radius:8px';}\n"
    "      continue;\n"
    "    }\n"
    "    if(code){code.append(document.createTextNode(line+'\\n'));continue;}\n"
    "    const heading=/^(#{1,6})\\s+(.*)$/.exec(line);\n"
    "    const row=document.createElement(heading?'h'+heading[1].length:'div');\n"
    "    row.style.whiteSpace='pre-wrap';\n"
    "    const content=heading?heading[2]:line;\n"
    "    const parts=content.split(/(\\*\\*[^*]+\\*\\*|`[^`]+`)/g);\n"
    "    for(const part of parts){\n"
    "      if(part.startsWith('**')&&part.endsWith('**')){const strong=document.createElement('strong');strong.textContent=part.slice(2,-2);row.append(strong);}\n"
    "      else if(part.startsWith('`')&&part.endsWith('`')){const span=document.createElement('code');span.textContent=part.slice(1,-1);row.append(span);}\n"
    "      else chatRenderInline(row,part);\n"
    "    }\n"
    "    if(!content)row.append(document.createElement('br'));\n"
    "    el.append(row);\n"
    "  }\n"
    "  if(code)el.append(code);\n"
    "}\n"
    "function chatRenderImages(wrap,images){\n"
    "  if(!wrap || !images?.length) return;\n"
    "  wrap.querySelector('.chat-images')?.remove();\n"
    "  const box=document.createElement('div'); box.className='chat-images';\n"
    "  // Verified delivery images belong to the answer, after its explanatory text,\n"
    "  // rather than above the entire execution/trace card.\n"
    "  const answer=wrap.querySelector('.chat-answer');\n"
    "  if(answer)answer.append(box);else wrap.append(box);\n"
    "  for(const item of images){\n"
    "    const label=document.createElement('span'); label.textContent='图片加载中：'+item.name; box.append(label);\n"
    "    call('GET','/v1/uploads/preview?id='+encodeURIComponent(item.id)+'&session='+encodeURIComponent(item.session)).then(r=>{\n"
    "      if(!box.isConnected) return;\n"
    "      const src=r.status===200 && chatImageSource(r.obj?.data_url);\n"
    "      if(src) label.replaceWith(chatImageButton(src,item.name)); else label.textContent='图片暂不可预览：'+item.name;\n"
    "    }).catch(()=>{ label.textContent='图片加载失败：'+item.name; });\n"
    "  }\n"
    "}\n"
    "function chatAppendCopy(wrap, getText){\n"
    "  const copy = document.createElement('button');\n"
    "  copy.className = 'chat-copy'; copy.type = 'button'; copy.textContent = '复制';\n"
    "  copy.title = '复制这条消息'; copy.setAttribute('aria-label','复制这条消息');\n"
    "  copy.onclick = () => copyText(getText() || '');\n"
    "  wrap.appendChild(copy);\n"
    "}\n"
    "function chatAddBubble(role, text, push = true){\n"
    "  const box = $('chat-box'); if(!box) return null;\n"
    "  const follow = CHAT_FOLLOW || chatNearBottom();\n"
    "  const wrap = document.createElement('div');\n"
    "  wrap.className = 'chat-message ' + role;\n"
    "  if(role === 'bot'){\n"
    "    const pre = document.createElement('pre');\n"
    "    pre.className = 'chat-answer';\n"
    "    chatRenderText(pre,text);\n"
    "    wrap.appendChild(pre);\n"
    "  } else {\n"
    "    chatRenderText(wrap,text);\n"
    "  }\n"
    "  if(text) chatAppendCopy(wrap, () => text);\n"
    "  box.appendChild(wrap);\n"
    "  if(push){\n"
    "    const entry={role,text,pending:false,el:wrap,timestamp_ms:Date.now()};\n"
    "    CHAT_MSGS.push(entry);chatRenderTimestamp(entry);\n"
    "  }\n"
    "  updateChatHero();\n"
    "  if(follow) chatScroll(true);\n"
    "  return wrap;\n"
    "}\n"
    "\n"
    "/* ChatGPT 首页体验：还没有消息时显示居中问候语 + 建议项 */\n"
    "function updateChatHero(){\n"
    "  const h = $('chat-hero');\n"
    "  if(h) h.style.display = ($('chat-box') && $('chat-box').children.length) ? 'none' : '';\n"
    "}\n"
    "\n"
    "function chatSuggest(text){\n"
    "  const input = $('chat-input');\n"
    "  if(!input) return;\n"
    "  input.value = text;\n"
    "  chatSend();\n"
    "}\n"
    "\n"
    "let CHAT_FOLLOW = true;\n"
    "function chatScroll(force = false){\n"
    "  const box = $('chat-box');\n"
    "  if(!box) return;\n"
    "  if(!box.dataset.scrollFollow){\n"
    "    box.dataset.scrollFollow='1';\n"
    "    let previous=box.scrollTop;\n"
    "    box.addEventListener('scroll',()=>{\n"
    "      if(box.scrollTop < previous-2) CHAT_FOLLOW=false;\n"
    "      if(chatNearBottom()) CHAT_FOLLOW=true;\n"
    "      previous=box.scrollTop;\n"
    "    },{passive:true});\n"
    "    box.addEventListener('wheel',e=>{if(e.deltaY<0) CHAT_FOLLOW=false;},{passive:true});\n"
    "  }\n"
    "  if(force) CHAT_FOLLOW=true;\n"
    "  if(CHAT_FOLLOW){\n"
    "    box.scrollTop=box.scrollHeight;\n"
    "    requestAnimationFrame(()=>{if(CHAT_FOLLOW && box.isConnected) box.scrollTop=box.scrollHeight;});\n"
    "  }\n"
    "}\n"
    "\n"
    "let CHAT_ROUND = 0;\n"
    "let CHAT_TASK_ID = null; /* 当前会话运行中的任务 id（供「取消」按钮使用） */\n"
    "let CHAT_RESUME_OK = false; /* 最近一次任务以取消/失败/超时结束，可「恢复」 */\n"
    "/* issue #21/#22: 会话 → 运行中任务 的映射。执行任务不再全局锁死 UI：\n"
    " * 切会话 / 切面板 / 新建会话随时可用，每个会话独立跟踪自己的任务；\n"
    " * 任务终态时从映射中移除。 */\n"
    "const CHAT_TASKS = {}; /* sessionId → running taskId */\n"
    "function chatTaskOf(sess){ return Object.prototype.hasOwnProperty.call(CHAT_TASKS,sess) ? CHAT_TASKS[sess] : null; }\n"
    "function chatIsBusy(sess){ const id = sess === undefined ? CHAT_SESSION : sess; return chatTaskOf(id) !== null || CHAT_SUBMITTING.has(id); }\n"
    "/* 当前会话的任务状态同步到 CHAT_TASK_ID / 取消按钮（切会话、切回面板时调用） */\n"
    "function syncChatTaskId(){\n"
    "  CHAT_TASK_ID = chatTaskOf(CHAT_SESSION);\n"
    "  CHAT_RESUME_OK = false;\n"
    "  chatBusyUI(CHAT_TASK_ID !== null);\n"
    "}\n"
    "\n"
    "function chatBusyUI(busy){\n"
    "  const cancel = $('chat-cancel'), resume = $('chat-resume');\n"
    "  const send = $('chat-send'); if(send) send.disabled = CHAT_SUBMITTING.has(CHAT_SESSION) || !!$('chat-input')?.disabled;\n"
    "  if(cancel) cancel.style.display = (busy && CHAT_TASK_ID !== null) ? '' : 'none';\n"
    "  if(send) send.style.display = (busy && CHAT_TASK_ID !== null) ? 'none' : '';\n"
    "  if(resume) resume.style.display = (!busy && CHAT_RESUME_OK) ? '' : 'none';\n"
    "}\n"
    "\n"
    "/* Flow 容器任务进度：各节点执行状态（flow_nodes 来自 /v1/tasks/<id>） */\n"
    "function flowNodesText(t){\n"
    "  if(!t || !Array.isArray(t.flow_nodes) || !t.flow_nodes.length) return '';\n"
    "  const ICON = {queued:'⏸', running:'⏳', ok:'✓', error:'✗', blocked:'⊘'};\n"
    "  const now = Date.now();\n"
    "  return t.flow_nodes.map(n => {\n"
    "    let state = n.status === 'running'\n"
    "      ? (n.cur_tool ? '正在执行 ' + n.cur_tool : (n.round ? '正在规划第 ' + n.round + ' 轮' : '正在启动'))\n"
    "      : ({queued:'等待中', ok:'已完成', error:'失败', blocked:'已阻断（前置步骤未完成）'}[n.status] || n.status || '未知');\n"
    "    let s = (ICON[n.status] || '·') + ' ' + state + ' · ' + (n.id || '?');\n"
    "    let ms = 0;\n"
    "    if(n.status === 'running' && n.start_ms) ms = now - n.start_ms;\n"
    "    else if((n.status === 'ok' || n.status === 'error') && n.start_ms && n.end_ms) ms = n.end_ms - n.start_ms;\n"
    "    if(ms > 0) s += ' ' + Math.floor(ms / 1000) + 's';\n"
    "    /* 运行中节点显示引擎内部进度：第N轮 · 工具×N（当前工具） · LLM 耗时 */\n"
    "    if(n.status === 'running'){\n"
    "      const d = [];\n"
    "      if(n.round) d.push('第' + n.round + '轮');\n"
    "      if(n.tool_calls !== undefined) d.push('已调用工具 ' + (n.tool_calls || 0) + ' 次');\n"
    "      if(n.llm_ms) d.push('LLM ' + Math.floor(n.llm_ms / 1000) + 's');\n"
    "      if(d.length) s += ' · ' + d.join(' · ');\n"
    "    }\n"
    "    return s;\n"
    "  }).join('\\n');\n"
    "}\n"
    "\n"
    "/* 任务实时进度行：耗时 / 轮次 / 工具调用 / token —— 数据来自\n"
    " * /v1/tasks/<id> 的 live 进度字段（RUNNING 时返回） */\n"
    "function taskProgressText(t){\n"
    "  if(!t) return '';\n"
    "  /* Flow 容器任务：引擎计数器恒为 0，显示节点级进度才有意义 */\n"
    "  if(t.flow_nodes) return flowNodesText(t);\n"
    "  const bits = [];\n"
    "  if(t.elapsed_ms !== undefined){\n"
    "    const sec = Math.floor((t.elapsed_ms || 0) / 1000);\n"
    "    bits.push(Math.floor(sec / 60) + ':' + String(sec % 60).padStart(2, '0'));\n"
    "  }\n"
    "  if(t.round) bits.push('第' + t.round + '轮');\n"
    "  if(t.tool_calls !== undefined) bits.push('工具×' + (t.tool_calls || 0) + (t.cur_tool ? '（' + t.cur_tool + '）' : ''));\n"
    "  if(t.llm_ms !== undefined){\n"
    "    const ls = ((t.llm_ms || 0) / 1000).toFixed(1);\n"
    "    const ts = ((t.tool_ms || 0) / 1000).toFixed(1);\n"
    "    bits.push('LLM ' + ls + 's×' + (t.llm_calls || 0) + ' · 工具 ' + ts + 's');\n"
    "  }\n"
    "  if(t.tokens_in || t.tokens_out)\n"
    "    bits.push('tokens ' + (t.tokens_in + t.tokens_out) + '（↑' + t.tokens_in + ' ↓' + t.tokens_out + '）');\n"
    "  return bits.join(' · ');\n"
    "}\n"
    "function flowTaskStatus(t){\n"
    "  const detail = taskProgressText(t);\n"
    "  return '状态: ' + t.status + (detail ? (t.flow_nodes ? '\\n' : ' · ') + detail : '');\n"
    "}\n"
    "function flowLiveProgress(t){\n"
    "  FLOW_MIRROR.live=t;\n"
    "  let box=$('flow-live');if(!box){box=document.createElement('div');box.id='flow-live';const anchor=$('flow-out');if(!anchor)return;anchor.before(box);}\n"
    "  const expanded=new Map(Array.from(box.querySelectorAll('details[data-key]'),d=>[d.dataset.key,d.open]));\n"
    "  box.replaceChildren();box.setAttribute('role','status');box.setAttribute('aria-live','polite');\n"
    "  const title=document.createElement('strong');const nodes=Array.isArray(t.flow_nodes)?t.flow_nodes:[];\n"
    "  title.textContent='任务 #'+t.id+' · '+t.status+' · '+(t.activity||'')+' · '+nodes.filter(n=>n.status==='ok').length+'/'+nodes.length+' 节点完成';box.append(title);\n"
    "  if(!nodes.length){const p=document.createElement('p');p.textContent='等待节点进度；连接正常时会自动更新。';box.append(p);return;}\n"
    "  for(const n of nodes){const row=document.createElement('details');row.dataset.key=t.id+':'+n.id;row.open=expanded.has(row.dataset.key)?expanded.get(row.dataset.key):n.status==='running'||n.status==='error';\n"
    "    const summary=document.createElement('summary');const token=n.usage_available!==false&&n.tokens_in!==undefined&&n.tokens_out!==undefined?(n.tokens_in+n.tokens_out):'未提供';\n"
    "    const elapsed=n.elapsed_ms!==undefined?Math.floor(n.elapsed_ms/1000)+'秒':'未提供';\n"
    "    summary.textContent=(n.id||'?')+' · '+(n.agent||'Agent')+' · '+({running:'执行中',queued:'等待依赖',ok:'已完成',error:'失败',blocked:'已阻断',cancelled:'已取消',timeout:'超时'}[n.status]||n.status)+' · '+(n.activity||n.stage||'')+' · 耗时 '+elapsed+' · 模型请求 '+(n.llm_calls?? '未提供')+' · 工具 '+(n.tool_calls?? '未提供')+' · tokens '+token;row.append(summary);\n"
    "    if(n.model_error||n.reason){const p=document.createElement('p');p.textContent=n.model_error||n.reason;row.append(p);}\n"
    "    for(const [index,s] of (n.steps||[]).entries()){const detail=document.createElement('details');detail.dataset.key=row.dataset.key+':tool:'+index;detail.open=expanded.get(detail.dataset.key)||false;const label=document.createElement('summary');label.textContent=(s.tool||'工具')+' · '+(s.ok===1?'成功':'失败')+' · '+(s.ms??0)+'ms';detail.append(label);const pre=document.createElement('pre');pre.style.cssText='white-space:pre-wrap;overflow-wrap:anywhere;max-height:240px;overflow:auto';pre.textContent=(s.args||'')+'\\n'+(s.out||'');detail.append(pre);row.append(detail);}box.append(row);}\n"
    "}\n"
    "\n"
    "/* Claude-Code 风格步骤化执行显示：● Tool(args) + ⎿ 输出首行摘要（不刷屏）；\n"
    " * RUNNING 时末尾显示 ⏳ 思考中…；无步骤数据时回退到过程日志尾部。\n"
    " * Flow 容器任务：显示运行中节点（stepN:agent）已执行的步骤 */\n"
    "function stepLines(s){\n"
    "  const mark = s.ok === 1 ? '●' : (s.ok === 0 ? '✗' : '⊘');\n"
    "  const args = (s.args || '').replace(/\\s+/g, ' ').trim();\n"
    "  const out = (s.out || '').split('\\n').map(x => x.trim()).filter(Boolean)[0] || '';\n"
    "  const outClean = out.replace(/^\\[[^\\]]+\\]\\s*/, '');\n"
    "  const ls = [mark + ' ' + (s.tool || '?') + '(' + (args.length > 90 ? args.slice(0, 90) + '…' : args) + ')'];\n"
    "  if(outClean) ls.push('  ⎿ ' + (outClean.length > 110 ? outClean.slice(0, 110) + '…' : outClean));\n"
    "  return ls;\n"
    "}\n"
    "function flowRunningNodes(t){\n"
    "  return (t && Array.isArray(t.flow_nodes))\n"
    "    ? t.flow_nodes.filter(n => n.status === 'running' && n.steps && n.steps.length) : [];\n"
    "}\n"
    "function stepsText(t){\n"
    "  const lines = [];\n"
    "  const frun = flowRunningNodes(t);\n"
    "  for(const n of frun){\n"
    "    lines.push('[' + (n.id || '?') + ':' + (n.agent || '') + ']');\n"
    "    for(const s of n.steps) lines.push(...stepLines(s));\n"
    "  }\n"
    "  if(!frun.length){\n"
    "    const steps = t && t.steps;\n"
    "    if(steps && steps.length){\n"
    "      for(const s of steps) lines.push(...stepLines(s));\n"
    "    } else if(t && t.process_log){\n"
    "      for(const l of t.process_log.split('\\n').filter(x => x.trim()).slice(-25)) lines.push(l);\n"
    "    }\n"
    "  }\n"
    "  if(t && t.status === 'RUNNING') lines.push('⏳ 思考中…');\n"
    "  return lines.join('\\n');\n"
    "}\n"
    "\n"
    "async function uploadFile(inp){\n"
    "  const f = inp.files && inp.files[0];\n"
    "  if(!f) return;\n"
    "  await uploadBlob(f.name, f);\n"
    "  inp.value = '';\n"
    "  loadUploads();\n"
    "}\n"
    "\n"
    "/* ===== 聊天附件：粘贴图片 / 拖拽文件 / ＋按钮 统一走这里 =====\n"
    " * 上传成功后加入待发送队列（chip 展示），发送时在消息前附 [附件: ...]，\n"
    " * 让 agent 知道有哪些文件（内容已由 /v1/upload 入库 RAG）。 */\n"
    "function attachmentSummary(a){\n"
    "  if(a.status==='uploading') return '上传与解析中';\n"
    "  if(a.status!=='ready') return a.status==='failed'?'解析失败':'暂不可用';\n"
    "  if(a.kind==='video') return '视频 · '+(a.framesCount || a.frames?.length || 0)+' 个画面';\n"
    "  if(a.pageCount || a.page_count) return '文档 · '+(a.pageCount || a.page_count)+' 页';\n"
    "  return a.kind==='image'?'图片':'可读取';\n"
    "}\n"
    "let CHAT_ATTACH = [];\n"
    "const CHAT_ATTACH_DRAFTS = new Map();\n"
    "function chatAttachActivate(session){\n"
    "  CHAT_ATTACH = CHAT_ATTACH_DRAFTS.get(session) || [];\n"
    "  CHAT_ATTACH_DRAFTS.set(session,CHAT_ATTACH);\n"
    "  chatAttachRender();\n"
    "}\n"
    "\n"
    "function chatAttachRender(){\n"
    "  const el = $('chat-attach'); if(!el) return;\n"
    "  el.style.display = CHAT_ATTACH.length ? 'flex' : 'none';\n"
    "  el.innerHTML = CHAT_ATTACH.map((a, i) =>\n"
    "    '<span class=\"tag\" style=\"cursor:pointer\" onclick=\"chatAttachRemove(' + i + ')\" title=\"点击移除\">📎 ' + esc(a.name) + ' · ' + esc(attachmentSummary(a)) + ' ×</span>').join('');\n"
    "  const images=CHAT_ATTACH.filter(a=>a.kind==='image' && a.id).map(a=>({id:a.id,name:a.name,session:CHAT_SESSION}));\n"
    "  if(images.length) chatRenderImages(el,images);\n"
    "}\n"
    "\n"
    "function chatAttachRemove(i){\n"
    "  CHAT_ATTACH.splice(i, 1);\n"
    "  chatAttachRender();\n"
    "}\n"
    "\n"
    "async function uploadBlob(name, blob){\n"
    "  if(blob.size > 64*1024*1024){ toast('附件不能超过 64 MiB'); return; }\n"
    "  const session = CHAT_SESSION;\n"
    "  const draft = CHAT_ATTACH_DRAFTS.get(session) || CHAT_ATTACH;\n"
    "  CHAT_ATTACH_DRAFTS.set(session,draft);\n"
    "  const entry = {name,status:'uploading'};\n"
    "  draft.push(entry); chatAttachRender();\n"
    "  entry.upload = (async () => {\n"
    "    const controller = new AbortController();\n"
    "    const timer = setTimeout(()=>controller.abort(),90000);\n"
    "    try {\n"
    "      const resp = await fetch('/v1/upload?name=' + encodeURIComponent(name) + '&session=' + encodeURIComponent(session),\n"
    "        {method:'POST',body:blob,signal:controller.signal});\n"
    "      const obj = await resp.json().catch(()=>({}));\n"
    "      if(!resp.ok || !obj.ok) throw new Error(obj.error || ('HTTP ' + resp.status));\n"
    "      Object.assign(entry,{id:obj.id,name:obj.name || name,status:obj.status || 'unsupported',kind:obj.kind,\n"
    "        framesCount:obj.frames?.length || 0,pageCount:obj.page_count || 0});\n"
    "      toast(entry.status === 'ready' ? '附件已就绪 ' + entry.name : '文件已保存，但无法用于对话：' + (obj.error || entry.status));\n"
    "    } catch(e){ entry.status='failed'; toast('上传失败: ' + e.message); }\n"
    "    finally { clearTimeout(timer); if(CHAT_SESSION===session) chatAttachRender(); }\n"
    "  })();\n"
    "  await entry.upload;\n"
    "}\n"
    "\n"
    "/* 粘贴图片（clipboardData 里的文件项）+ 整个聊天区拖拽文件 */\n"
    "function chatInitDrop(){\n"
    "  const input = $('chat-input');\n"
    "  const wrap = $('chat-wrap');\n"
    "  if(!input || !wrap || wrap.dataset.dropInit) return;\n"
    "  wrap.dataset.dropInit = '1';\n"
    "  input.addEventListener('paste', (e) => {\n"
    "    const items = (e.clipboardData && e.clipboardData.items) || [];\n"
    "    let handled = false;\n"
    "    for(const it of items){\n"
    "      if(it.kind === 'file'){\n"
    "        const f = it.getAsFile();\n"
    "        if(f){\n"
    "          handled = true;\n"
    "          const name = f.name || ('粘贴图片-' + new Date().toISOString().replace(/[:.]/g, '-') + '.png');\n"
    "          uploadBlob(name, f);\n"
    "        }\n"
    "      }\n"
    "    }\n"
    "    if(handled) e.preventDefault();\n"
    "  });\n"
    "  ['dragenter', 'dragover'].forEach(ev =>\n"
    "    wrap.addEventListener(ev, (e) => { e.preventDefault(); wrap.classList.add('drop'); }));\n"
    "  ['dragleave', 'drop'].forEach(ev =>\n"
    "    wrap.addEventListener(ev, (e) => {\n"
    "      e.preventDefault();\n"
    "      if(ev === 'dragleave' && e.target !== wrap) return; /* 内部元素间移动不算离开 */\n"
    "      wrap.classList.remove('drop');\n"
    "    }));\n"
    "  wrap.addEventListener('drop', (e) => {\n"
    "    const files = (e.dataTransfer && e.dataTransfer.files) || [];\n"
    "    for(const f of files) uploadBlob(f.name, f);\n"
    "  });\n"
    "}\n"
    "\n"
    "async function loadUploads(){\n"
    "  const el = $('uploads-list'); if(!el) return;\n"
    "  const r = await call('GET', '/v1/uploads');\n"
    "  const files = (r.obj && Array.isArray(r.obj.files)) ? r.obj.files : [];\n"
    "  el.innerHTML = files.length\n"
    "    ? files.map(f => '<span class=\"chip\">' + esc(f.name) + ' <span class=\"muted\">' + esc(attachmentSummary(f)) + ' (' + (f.size/1024).toFixed(1) + ' KB)</span> <button class=\"sec sm\" onclick=\"delUpload(\\'' + esc(f.id || f.name).replace(/'/g,\"\\\\'\") + '\\')\">✕</button></span>').join('')\n"
    "    : '<span class=\"muted\">（暂无上传）</span>';\n"
    "}\n"
    "\n"
    "async function delUpload(name){\n"
    "  const r = await call('DELETE', '/v1/uploads/' + encodeURIComponent(name));\n"
    "  if(r.status === 200) { toast('已删除 ' + name); loadUploads(); }\n"
    "  else toast('删除失败');\n"
    "}\n"
    "\n"
    "/* Enter 发送 */\n"
    "document.addEventListener('keydown', (e) => {\n"
    "  if(e.key === 'Enter' && !e.shiftKey && e.target && e.target.id === 'chat-input'){\n"
    "    e.preventDefault();\n"
    "    chatSend();\n"
    "  }\n"
    "});\n"
    "\n"
    "/* ================= Flow（自动编排 + 手写 DAG） ================= */\n"
    "\n"
    "let FLOW_BUSY = false;\n"
    "\n"
    "/* Flow 面板状态镜像：switchPanel 用 innerHTML 重建面板，DOM 里的任务输入、\n"
    " * DAG 编辑器、执行输出和状态行（耗时/token/工具统计）在切换后全部丢失。\n"
    " * 镜像保存在 JS 变量里，切回面板时恢复；轮询循环通过 flowStatus 同时写\n"
    " * 镜像和（若存在的）当前 DOM 元素，即使人不在 Flow 页统计也不丢。 */\n"
    "let FLOW_MIRROR = {task:'', json:'', out:'', gen:'', run:'', follow:''};\n"
    "\n"
    "/* which: 'gen-status' | 'status' | 'follow-status'（对应 flow-*-status 元素）。\n"
    " * 每次都用 $() 现查元素：面板被 innerHTML 重建后，轮询循环里捕获的旧节点\n"
    " * 已脱离文档，写它无效；现查则切回面板后统计行继续实时刷新。 */\n"
    "function flowStatus(which, text){\n"
    "  FLOW_MIRROR[which === 'gen-status' ? 'gen' : which === 'follow-status' ? 'follow' : 'run'] = text;\n"
    "  const el = $('flow-' + which);\n"
    "  if(!el) return;\n"
    "  el.replaceChildren();\n"
    "  const lines = text.split('\\n');\n"
    "  lines.forEach((line, index) => {\n"
    "    if(index === 0){ el.append(document.createTextNode(line)); return; }\n"
    "    const row = document.createElement('span'); row.className = 'flow-progress-line';\n"
    "    const at = line.indexOf('⏳');\n"
    "    if(at >= 0){\n"
    "      row.append(document.createTextNode(line.slice(0, at)));\n"
    "      const spinner = document.createElement('span'); spinner.className = 'flow-spinner';\n"
    "      spinner.setAttribute('aria-label', '运行中'); row.append(spinner);\n"
    "      row.append(document.createTextNode(line.slice(at + 1)));\n"
    "    } else row.textContent = line;\n"
    "    el.append(row);\n"
    "  });\n"
    "}\n"
    "\n"
    "function flowSaveState(){\n"
    "  const t = $('flow-task'), j = $('flow-json'), o = $('flow-out');\n"
    "  if(t) FLOW_MIRROR.task = t.value;\n"
    "  if(j) FLOW_MIRROR.json = j.value;\n"
    "  if(o && o.textContent) FLOW_MIRROR.out = o.textContent;\n"
    "}\n"
    "\n"
    "function flowRestoreState(){\n"
    "  if($('flow-agent-mode'))$('flow-agent-mode').value=FLOW_ROLE_MODE;\n"
    "  flowAgentOptions();\n"
    "  if(FLOW_MIRROR.live)flowLiveProgress(FLOW_MIRROR.live);\n"
    "  const t = $('flow-task'), j = $('flow-json'), o = $('flow-out');\n"
    "  if(t && FLOW_MIRROR.task) t.value = FLOW_MIRROR.task;\n"
    "  if(j && FLOW_MIRROR.json) j.value = FLOW_MIRROR.json;\n"
    "  flowStatus('gen-status', FLOW_MIRROR.gen || '');\n"
    "  flowStatus('status', FLOW_MIRROR.run || '');\n"
    "  flowStatus('follow-status', FLOW_MIRROR.follow || '');\n"
    "  if(o && FLOW_MIRROR.out) o.textContent = FLOW_MIRROR.out;\n"
    "}\n"
    "\n"
    "/* 生成 DAG：LLM 分解总任务 → 填入下方编辑器（不执行，可修改） */\n"
    "let FLOW_ROLE_NAMES=[],FLOW_ROLE_MODE='auto';\n"
    "function flowAgentOptions(){\n"
    " FLOW_ROLE_MODE=$('flow-agent-mode')?.value||'auto';\n"
    " const box=$('flow-agent-options');if(!box)return;box.hidden=$('flow-agent-mode')?.value!=='manual';if(box.hidden)return;box.replaceChildren();\n"
    " for(const a of AGENTS){const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.value=a.name;check.checked=FLOW_ROLE_NAMES.includes(a.name);check.onchange=()=>{FLOW_ROLE_NAMES=Array.from(box.querySelectorAll('input:checked')).map(x=>x.value);};label.append(check,document.createTextNode(a.name+' · '+(a.role||'')));box.append(label);}\n"
    "}\n"
    "const FLOW_ROLE_SCOPES=new Map();\n"
    "function flowTaskText(value,id){try{const scope=JSON.parse(value);if(scope.coa_flow_scope===1&&typeof scope.task==='string'){FLOW_ROLE_SCOPES.set(id,scope);return scope.task;}}catch(e){}return value||'';}\n"
    "function flowSelectedAgents(){\n"
    " if($('flow-agent-mode')?.value!=='manual')return undefined;\n"
    " const agents=Array.from(document.querySelectorAll('#flow-agent-options input:checked')).map(x=>x.value);\n"
    " if(!agents.length)throw new Error('请至少选择一个 Agent');return agents;\n"
    "}\n"
    "async function flowGen(){\n"
    "  const input = $('flow-task'), st = $('flow-gen-status'), ta = $('flow-json');\n"
    "  if(!input || !st) return;\n"
    "  const task = input.value.trim();\n"
    "  if(!task){ flowStatus('gen-status', '请先输入总任务'); return; }\n"
    "  flowStatus('gen-status', '分解中…');\n"
    "  let agents;try{agents=flowSelectedAgents();}catch(e){flowStatus('gen-status',e.message);return;}\n"
    "  const c = await call('POST', '/v1/flows/decompose', {task,agents});\n"
    "  if(c.status === 200 && c.obj && c.obj.dag){\n"
    "    if(ta) ta.value = JSON.stringify(c.obj.dag, null, 2);\n"
    "    flowStatus('gen-status', '已生成，可在下方修改后执行');\n"
    "  } else {\n"
    "    flowStatus('gen-status', '生成失败: ' + ((c.obj && c.obj.error) || c.text || ('HTTP ' + c.status)));\n"
    "  }\n"
    "}\n"
    "\n"
    "/* 自动执行：分解→执行→综合答案一步完成 */\n"
    "async function flowAuto(){\n"
    "  if(FLOW_BUSY) return;\n"
    "  const input = $('flow-task'), st = $('flow-gen-status'), out = $('flow-out');\n"
    "  if(!input) return;\n"
    "  const task = input.value.trim();\n"
    "  if(!task){ flowStatus('gen-status', '请先输入总任务'); return; }\n"
    "  let agents;try{agents=flowSelectedAgents();}catch(e){flowStatus('gen-status',e.message);return;}\n"
    "  FLOW_BUSY = true;\n"
    "  flowStatus('gen-status', '已提交（分解→执行→综合）…');\n"
    "  FLOW_MIRROR.out = '';\n"
    "  if(out) out.textContent = '';\n"
    "  const c = await call('POST', '/v1/orchestrate', {task,agents,workspace:$('flow-workspace')?.value || FLOW_WORKSPACE});\n"
    "  const id = c.obj && c.obj.id;\n"
    "  if(id === undefined){\n"
    "    flowStatus('gen-status', '提交失败: ' + (c.text || ('HTTP ' + c.status)));\n"
    "    FLOW_BUSY = false;\n"
    "    return;\n"
    "  }\n"
    "  await loadFlowTasks();\n"
    "  for(let i = 0; ; i++){\n"
    "    const r = await call('GET', '/v1/tasks/' + id);\n"
    "    if(r.status === 404){\n"
    "      flowStatus('gen-status', '任务丢失（服务可能已重启），请重新提交');\n"
    "      toast('任务丢失（服务可能已重启）');\n"
    "      FLOW_BUSY = false;\n"
    "      return;\n"
    "    }\n"
    "    const t = r.obj;\n"
    "    if(t?.status)flowLiveProgress(t);\n"
    "    if(t && t.status && t.status !== 'DONE')\n"
    "      flowStatus('gen-status', flowTaskStatus(t));\n"
    "    if(t && (t.status === 'DONE' || t.status === 'FAILED' || t.status === 'CANCELLED' || t.status === 'TIMEOUT')){\n"
    "      FLOW_LAST_OUTPUT = t.output || '';\n"
    "      FLOW_MIRROR.out = FLOW_LAST_OUTPUT ? ('—— 综合答案 ——\\n' + FLOW_LAST_OUTPUT) : '(无输出)';\n"
    "      if(out && out.isConnected) out.textContent = FLOW_MIRROR.out;\n"
    "      const zh = {FAILED: '失败', CANCELLED: '已取消', TIMEOUT: '超时'}[t.status];\n"
    "      if(zh){\n"
    "        flowStatus('gen-status', '❌ 任务' + zh + (FLOW_LAST_OUTPUT && FLOW_LAST_OUTPUT !== '(no output)' ? '：' + FLOW_LAST_OUTPUT.slice(0, 300) : '（无输出）'));\n"
    "        toast('任务' + zh);\n"
    "      } else {\n"
    "        flowStatus('gen-status', '');\n"
    "      }\n"
    "      FLOW_BUSY = false;\n"
    "      loadFlow();\n"
    "      return;\n"
    "    }\n"
    "    await new Promise(res => setTimeout(res, 300));\n"
    "  } /* poll until terminal status — no timeout */\n"
    "}\n"
    "\n"
    "/* ================= 策略规则 ================= */\n"
    "\n"
    "let POLICY_TOOLS_LOADED = false;\n"
    "async function loadPolicyTools(){\n"
    "  const sel = $('pol-tool'); if(!sel) return;\n"
    "  if(POLICY_TOOLS_LOADED) return;\n"
    "  const r = await call('GET', '/v1/tools');\n"
    "  const tools = Array.isArray(r.obj) ? r.obj : [];\n"
    "  if(!tools.length) return;\n"
    "  const cur = sel.value || '*';\n"
    "  sel.innerHTML = '<option value=\"*\">*</option>' +\n"
    "    tools.map(t => '<option value=\"' + esc(t.name) + '\">' + esc(t.name) + '</option>').join('');\n"
    "  sel.value = [...sel.options].some(o => o.value === cur) ? cur : '*';\n"
    "  POLICY_TOOLS_LOADED = true;\n"
    "}\n"
    "\n"
    "async function loadPolicy(){\n"
    "  const el = $('pol-list'); if(!el) return;\n"
    "  loadPolicyTools();\n"
    "  const r = await call('GET', '/v1/policy/rules');\n"
    "  const rules = (r.obj && r.obj.rules) ? r.obj.rules : [];\n"
    "  if(!rules.length){\n"
    "    el.innerHTML = '<span class=\"muted\" style=\"font-size:12px\">暂无规则（默认全放行）</span>';\n"
    "    return;\n"
    "  }\n"
    "  const parts = [];\n"
    "  for(const g of rules){\n"
    "    const deny = g.action === 'deny';\n"
    "    const color = deny ? '#e74c3c' : (g.action === 'ask' ? '#f39c12' : '#27ae60');\n"
    "    parts.push('<div style=\"display:flex;align-items:center;gap:8px;margin:6px 0\">' +\n"
    "      '<span style=\"font-family:monospace;color:' + color + ';font-weight:600\">' + esc(g.action) + '</span>' +\n"
    "      '<span style=\"font-family:monospace\">' + esc(g.tool) + '</span>' +\n"
    "      (g.reason ? '<span class=\"muted\" style=\"font-size:12px\">' + esc(g.reason) + '</span>' : '') +\n"
    "      '<span style=\"flex:1\"></span>' +\n"
    "      '<button class=\"sec sm\" onclick=\"policyDelete(' + g.index + ')\">删除</button>' +\n"
    "      '</div>');\n"
    "  }\n"
    "  el.innerHTML = parts.join('');\n"
    "}\n"
    "\n"
    "async function policyAdd(){\n"
    "  const tool = $('pol-tool'), act = $('pol-action'), reason = $('pol-reason'), st = $('pol-stat');\n"
    "  if(!tool || !act) return;\n"
    "  const t = tool.value.trim();\n"
    "  if(!t){ if(st) st.textContent = 'tool 名不能为空'; return; }\n"
    "  const c = await call('POST', '/v1/policy/rules',\n"
    "    {tool: t, action: act.value, reason: reason ? reason.value.trim() : ''});\n"
    "  if(c.status === 200){\n"
    "    if(st) st.textContent = '已添加' + (c.obj && c.obj.saved ? '并持久化' : '（持久化失败，重启会丢失）');\n"
    "    tool.value = '*'; if(reason) reason.value = '';\n"
    "    loadPolicy();\n"
    "  } else {\n"
    "    if(st) st.textContent = '添加失败: ' + (c.text || ('HTTP ' + c.status));\n"
    "  }\n"
    "}\n"
    "\n"
    "async function policyDelete(idx){\n"
    "  const c = await call('DELETE', '/v1/policy/rules/' + idx);\n"
    "  if(c.status === 200) loadPolicy();\n"
    "  else toast('删除失败');\n"
    "}\n"
    "\n"
    "/* ================= Flow DAG 执行 ================= */\n"
    "\n"
    "async function loadFlow(){\n"
    "  const el = $('flow-board'); if(!el) return;\n"
    "  const r = await call('GET', '/v1/blackboard');\n"
    "  /* /v1/blackboard 返回扁平 JSON：键是黑板 key（如 flow/trace），值是内容 */\n"
    "  const facts = (r.obj && typeof r.obj === 'object' && !Array.isArray(r.obj)) ? r.obj : {};\n"
    "  const parts = [];\n"
    "  for(const k of Object.keys(facts)){\n"
    "    if(k === 'flow/trace' || k.indexOf('flow/') === 0){\n"
    "      const value = String(facts[k]);\n"
    "      const resultId = 'flow-result-' + parts.length;\n"
    "      parts.push('<details style=\"margin:8px 0\"' + (k === 'flow/trace' ? '' : ' open') + '>' +\n"
    "        '<summary style=\"cursor:pointer\"><b>' + esc(k) + '</b> · ' + value.length + ' 字符</summary>' +\n"
    "        '<div class=\"row\" style=\"justify-content:flex-end\"><button class=\"sec sm\" onclick=\"copyPre(\\'' +\n"
    "        resultId + '\\')\">复制完整结果</button></div>' +\n"
    "        '<pre id=\"' + resultId + '\" style=\"margin:2px 0;white-space:pre-wrap;font-size:12px;max-height:480px;overflow:auto\">' +\n"
    "        esc(value) + '</pre></details>');\n"
    "    }\n"
    "  }\n"
    "  el.innerHTML = parts.length ? parts.join('')\n"
    "    : '<span class=\"muted\" style=\"font-size:12px\">暂无 Flow 记录</span>';\n"
    "}\n"
    "\n"
    "/* ===== 协作任务列表（state/flows.json 持久化）===== */\n"
    "function flowStatusBadge(s){\n"
    "  const c = {'RUNNING':'#b58900','DONE':'#2da44e','FAILED':'#cf222e','CANCELLED':'#6e7781','TIMEOUT':'#cf222e','INTERRUPTED':'#b58900'}[s] || '#6e7781';\n"
    "  const label={RUNNING:'执行中',DONE:'已完成',FAILED:'失败',CANCELLED:'已取消',TIMEOUT:'超时',INTERRUPTED:'已中断'}[s] || s || '?';\n"
    "  return '<span class=\"flow-task-status\" role=\"status\" style=\"color:#fff;background:' + c + ';border-radius:8px;padding:1px 8px;font-size:11px\">' + esc(label) + '</span>';\n"
    "}\n"
    "\n"
    "const FLOW_TASK_TRACKED = new Set();\n"
    "async function loadFlowTasks(){\n"
    "  const el = $('flow-tasks'); if(!el) return;\n"
    "  const r = await call('GET', '/v1/flows/list');\n"
    "  if(r.status !== 200){ el.innerHTML = '<span class=\"muted\" style=\"font-size:12px\">加载失败: ' + esc(r.text || ('HTTP ' + r.status)) + '</span>'; return; }\n"
    "  const recs = (r.obj && r.obj.records) ? r.obj.records : [];\n"
    "  if(!recs.length){ el.innerHTML = '<span class=\"muted\" style=\"font-size:12px\">暂无协作任务记录</span>'; return; }\n"
    "  const rows = recs.map(x => {\n"
    "    const id = x.id, s = x.status || '?';\n"
    "    const live = (s === 'RUNNING');\n"
    "    const editable = !live;\n"
    "    const resume = (!live && s !== 'DONE') ? '<button class=\"sec sm\" onclick=\"flowTaskResume(' + id + ')\">继续</button>' : '';\n"
    "    const cancel = live ? '<button class=\"sec sm\" onclick=\"flowTaskCancel(' + id + ')\">取消</button>' : '';\n"
    "    const edit = editable ? '<button class=\"sec sm\" onclick=\"flowTaskEdit(' + id + ')\">修改</button>' : '';\n"
    "    const key = id + ':' + x.task_id;\n"
    "    if(live) FLOW_TASK_TRACKED.add(key);\n"
    "    const tid = x.task_id != null && x.task_id >= 0 && FLOW_TASK_TRACKED.has(key) ? x.task_id : null;\n"
    "    return '<div id=\"flow-task-' + id + '\" data-flow-record-id=\"' + id + '\"' + (tid != null ? ' data-flow-task-id=\"' + tid + '\"' : '') + ' data-flow-status=\"' + esc(s) + '\" style=\"border:1px solid var(--bd,#ddd);border-radius:8px;padding:8px 10px;margin:6px 0\">' +\n"
    "      '<div class=\"flow-task-heading\"><span class=\"flow-record-status\">' + flowStatusBadge(s) + '</span>' +\n"
    "      '<b>#' + id + '</b>' +\n"
    "      '<span class=\"flow-task-title\" title=\"' + esc(x.name || flowTaskText(x.input,x.id)) + '\">' + esc(x.name || flowTaskText(x.input,x.id).slice(0, 60) || '(无名称)') + '</span>' +\n"
    "      '<span class=\"flow-record-actions\">' + resume + cancel + edit + '</span>' +\n"
    "      '</div>' +\n"
    "      (x.workspace ? '<div class=\"muted\" style=\"font-size:12px;overflow-wrap:anywhere\">工作区：'+esc(x.workspace)+'</div>' : '') +\n"
    "      (x.input ? '<div class=\"muted\" style=\"font-size:11.5px;margin-top:4px;white-space:pre-wrap\">' + esc(flowTaskText(x.input,x.id)).slice(0, 200) + '</div>' : '') +\n"
    "      '<div class=\"muted\" style=\"font-size:11px;margin-top:2px\">创建: ' + new Date(x.created_ms).toLocaleString() + ' · 更新: ' + new Date(x.updated_ms).toLocaleString() + '</div>' +\n"
    "      '<div class=\"flow-record-progress\" role=\"status\" aria-live=\"polite\" style=\"white-space:pre-wrap;overflow-wrap:anywhere;margin-top:6px\">' + (tid != null ? '正在读取执行进度…' : '历史执行记录；可点击继续开始新任务。') + '</div>' +\n"
    "      '<div id=\"flow-task-edit-' + id + '\"></div>' +\n"
    "      '</div>';\n"
    "  });\n"
    "  el.innerHTML = rows.join('');\n"
    "  await refreshFlowTaskProgress();\n"
    "}\n"
    "\n"
    "let FLOW_TASK_PROGRESS_BUSY = false;\n"
    "async function refreshFlowTaskProgress(){\n"
    "  const list = $('flow-tasks');\n"
    "  if(!list || FLOW_TASK_PROGRESS_BUSY) return;\n"
    "  FLOW_TASK_PROGRESS_BUSY = true;\n"
    "  try {\n"
    "    await Promise.all(Array.from(list.querySelectorAll('[data-flow-task-id]')).map(async row => {\n"
    "      if(row.dataset.progressLoaded && row.dataset.flowStatus !== 'RUNNING' && row.dataset.flowStatus !== 'QUEUED') return;\n"
    "      const tid = row.dataset.flowTaskId;\n"
    "      const r = await call('GET', '/v1/tasks/' + tid);\n"
    "      if(!row.isConnected || $('flow-tasks') !== list) return;\n"
    "      const progress = row.querySelector('.flow-record-progress');\n"
    "      if(r.status !== 200 || !r.obj || !r.obj.status){\n"
    "        delete progress.dataset.rendered;\n"
    "        progress.textContent = r.status === 404\n"
    "          ? '执行任务 #' + tid + ' 的实时记录已不可用（服务可能重启）；持久化记录仍保留。'\n"
    "          : '执行进度暂时获取失败，将自动重试。';\n"
    "        return;\n"
    "      }\n"
    "      const t = r.obj, id = row.dataset.flowRecordId;\n"
    "      row.dataset.flowStatus = t.status;\n"
    "      row.dataset.progressLoaded = 'true';\n"
    "      row.querySelector('.flow-record-status').innerHTML = flowStatusBadge(t.status);\n"
    "      const live = t.status === 'RUNNING' || t.status === 'QUEUED';\n"
    "      row.querySelector('.flow-record-actions').innerHTML = live\n"
    "        ? '<button class=\"sec sm\" onclick=\"flowTaskCancel(' + id + ')\">取消</button>'\n"
    "        : (t.status !== 'DONE' ? '<button class=\"sec sm\" onclick=\"flowTaskResume(' + id + ')\">继续</button>' : '') + '<button class=\"sec sm\" onclick=\"flowTaskEdit(' + id + ')\">修改</button>';\n"
    "      const nodes = Array.isArray(t.flow_nodes) ? t.flow_nodes : [];\n"
    "      const counters = nodes.map(n => (n.id || '?') + (n.agent ? ' (' + n.agent + ')' : '') +\n"
    "        ' · 模型请求 ' + (n.llm_calls ?? '未知') + ' · 工具 ' + (n.tool_calls ?? '未知') +\n"
    "        ' · token ' + (n.tokens_in != null && n.tokens_out != null ? n.tokens_in + n.tokens_out : '未知')).join('\\n');\n"
    "      const recent = nodes.flatMap(n => (n.steps || []).slice(-2).flatMap(s => ['[' + (n.id || '?') + '] ' + stepLines(s).join('\\n')])).slice(-6).join('\\n');\n"
    "      const text = '执行任务 #' + tid + '\\n' + flowTaskStatus(t) + (counters ? '\\n' + counters : '') + (recent ? '\\n最近动作：\\n' + recent : '');\n"
    "      // Keep existing result disclosure and scroll position during unchanged polls.\n"
    "      const html = '<div>' + esc(text) + '</div>' + (!live && t.output ? '<details><summary>执行结果</summary><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere\">' + esc(t.output) + '</pre></details>' : '');\n"
    "      if(progress.dataset.rendered !== html){ progress.innerHTML = html; progress.dataset.rendered = html; }\n"
    "    }));\n"
    "  } finally {\n"
    "    FLOW_TASK_PROGRESS_BUSY = false;\n"
    "    // A panel replacement during an in-flight request needs its own first poll.\n"
    "    if($('flow-tasks') && $('flow-tasks') !== list) refreshFlowTaskProgress();\n"
    "  }\n"
    "}\n"
    "\n"
    "async function flowTaskResume(id){\n"
    "  const r = await call('POST', '/v1/flows/' + id + '/resume', {});\n"
    "  const tid = r.obj && r.obj.id;\n"
    "  if(r.status === 200 && tid != null) toast('已继续: 新任务 #' + tid);\n"
    "  else toast('继续失败: ' + (r.text || ('HTTP ' + r.status)));\n"
    "  await loadFlowTasks();\n"
    "  if(r.status === 200 && tid != null){\n"
    "    const row = $('flow-tasks')?.querySelector('[data-flow-task-id=\"' + tid + '\"]');\n"
    "    if(row) row.scrollIntoView({block:'nearest',behavior:'smooth'});\n"
    "  }\n"
    "}\n"
    "\n"
    "async function flowTaskCancel(id){\n"
    "  /* id = record id；取消运行中的任务要用 scheduler task id */\n"
    "  const r0 = await call('GET', '/v1/flows/list');\n"
    "  const recs = (r0.obj && r0.obj.records) ? r0.obj.records : [];\n"
    "  const x = recs.find(t => String(t.id) === String(id));\n"
    "  const tid = (x && x.task_id != null && x.task_id >= 0) ? x.task_id : null;\n"
    "  if(tid == null){ toast('该记录没有运行中的任务（无需取消）'); return; }\n"
    "  const r = await call('DELETE', '/v1/tasks/' + tid);\n"
    "  if(r.status === 200) toast('已请求取消 #' + id);\n"
    "  else toast('取消失败: ' + (r.text || ('HTTP ' + r.status)));\n"
    "  setTimeout(loadFlowTasks, 500);\n"
    "}\n"
    "\n"
    "function flowTaskEdit(id){\n"
    "  const box = $('flow-task-edit-' + id); if(!box || box.innerHTML) return;\n"
    "  call('GET', '/v1/flows/list').then(r => {\n"
    "    const recs = (r.obj && r.obj.records) ? r.obj.records : [];\n"
    "    const x = recs.find(t => String(t.id) === String(id));\n"
    "    if(!x){ toast('记录不存在'); return; }\n"
    "    box.innerHTML =\n"
    "      '<textarea id=\"flow-task-input-' + id + '\" style=\"width:100%;min-height:40px;font-size:12px;margin-top:6px\" placeholder=\"任务描述\">' + esc(flowTaskText(x.input,x.id)) + '</textarea>' +\n"
    "      (x.automatic ? '<p class=\"muted\">自动编排任务：继续执行时会按任务描述重新生成 DAG。</p>' : '<textarea id=\"flow-task-dag-' + id + '\" style=\"width:100%;min-height:120px;font-family:monospace;font-size:12px;margin-top:4px\">' + esc(x.dag || '') + '</textarea>') +\n"
    "      '<div class=\"row\" style=\"margin-top:4px\">' +\n"
    "      '<input id=\"flow-task-name-' + id + '\" type=\"text\" placeholder=\"名称\" style=\"flex:1;min-width:120px\" value=\"' + esc(x.name || '') + '\">' +\n"
    "      '<button class=\"sm\" onclick=\"flowTaskSave(' + id + ')\">保存</button>' +\n"
    "      '<button class=\"sec sm\" onclick=\"loadFlowTasks()\">放弃</button>' +\n"
    "      '<span id=\"flow-task-save-status-' + id + '\" class=\"muted\" style=\"font-size:12px\"></span></div>';\n"
    "  });\n"
    "}\n"
    "\n"
    "async function flowTaskSave(id){\n"
    "  const st = $('flow-task-save-status-' + id);\n"
    "  const name = ($('flow-task-name-' + id) || {}).value;\n"
    "  const input = ($('flow-task-input-' + id) || {}).value;\n"
    "  const dagRaw = (($('flow-task-dag-' + id) || {}).value || '').trim();\n"
    "  let body = {};\n"
    "  if(name !== undefined) body.name = name;\n"
    "  if(input !== undefined) body.input = FLOW_ROLE_SCOPES.has(id)?JSON.stringify({...FLOW_ROLE_SCOPES.get(id),task:input}):input;\n"
    "  try { if(dagRaw) body.dag = JSON.parse(dagRaw); }\n"
    "  catch(e){ toast('DAG JSON 语法错误: ' + e.message); return; }\n"
    "  const r = await call('PUT', '/v1/flows/' + id, body);\n"
    "  const ok = (r.status === 200);\n"
    "  if(st) st.textContent = ok ? '已保存' : '保存失败: ' + (r.text || ('HTTP ' + r.status));\n"
    "  if(ok) setTimeout(loadFlowTasks, 600);\n"
    "}\n"
    "\n"
    "async function flowTasksResumeAll(){\n"
    "  const r = await call('GET', '/v1/flows/list');\n"
    "  const recs = (r.obj && r.obj.records) ? r.obj.records : [];\n"
    "  const ids = recs.filter(x => x.status && x.status !== 'RUNNING' && x.status !== 'DONE').map(x => x.id);\n"
    "  if(!ids.length){ toast('没有可继续的任务'); return; }\n"
    "  for(const id of ids) await call('POST', '/v1/flows/' + id + '/resume', {});\n"
    "  toast('已继续 ' + ids.length + ' 个任务');\n"
    "  loadFlowTasks();\n"
    "}\n"
    "\n"
    "let FLOW_LAST_OUTPUT = '';\n"
    "\n"
    "/* 把 Flow 执行结果 + 追加指令交给 LLM（走 /v1/chat，保留对话上下文） */\n"
    "async function flowChat(promptPrefix, statusEl){\n"
    "  if(FLOW_BUSY) return;\n"
    "  const out = $('flow-out'), inp = $('flow-follow');\n"
    "  /* 综合答案写 flow-status，继续对话写 flow-follow-status —— 轮询期间面板\n"
    "   * 可能被重建，状态一律走 flowStatus（镜像 + 现查元素） */\n"
    "  const which = (statusEl && statusEl.id === 'flow-follow-status') ? 'follow-status' : 'status';\n"
    "  if(!FLOW_LAST_OUTPUT){\n"
    "    flowStatus(which, '请先执行 Flow（或加载黑板记录）');\n"
    "    return;\n"
    "  }\n"
    "  FLOW_BUSY = true;\n"
    "  flowStatus(which, 'LLM 处理中…');\n"
    "  const tail = FLOW_LAST_OUTPUT.length > 3000 ? FLOW_LAST_OUTPUT.slice(-3000) : FLOW_LAST_OUTPUT;\n"
    "  const message = promptPrefix.replace('%RESULTS%', tail) + ((inp && inp.value.trim()) ? ('\\n\\n' + inp.value.trim()) : '');\n"
    "  const c = await call('POST', '/v1/chat', {message, session: CHAT_SESSION});\n"
    "  const id = c.obj && c.obj.id;\n"
    "  if(id === undefined){\n"
    "    flowStatus(which, '提交失败: ' + (c.text || ('HTTP ' + c.status)));\n"
    "    FLOW_BUSY = false;\n"
    "    return;\n"
    "  }\n"
    "  for(let i = 0; ; i++){\n"
    "    const r = await call('GET', '/v1/tasks/' + id);\n"
    "    const t = r.obj;\n"
    "    if(r.status === 404 || (r.obj && r.obj.error && !t.status)){\n"
    "      flowStatus(which, '⚠ 任务 #' + id + ' 已丢失（服务可能重启过）');\n"
    "      FLOW_BUSY = false;\n"
    "      return;\n"
    "    }\n"
    "    if(r.status === 0){\n"
    "      flowStatus(which, '⚠ 服务连接失败，等待服务恢复…（' + (i + 1) + '）');\n"
    "      if(i > 200){ flowStatus(which, '⚠ 服务长时间无响应，停止轮询'); FLOW_BUSY = false; return; }\n"
    "      await new Promise(res => setTimeout(res, 300));\n"
    "      continue;\n"
    "    }\n"
    "    if(t?.status)flowLiveProgress(t);\n"
    "    if(t && t.status && t.status !== 'DONE')\n"
    "      flowStatus(which, flowTaskStatus(t));\n"
    "    if(t && (t.status === 'DONE' || t.status === 'FAILED' || t.status === 'CANCELLED' || t.status === 'TIMEOUT')){\n"
    "      FLOW_MIRROR.out = (FLOW_MIRROR.out ? FLOW_MIRROR.out + '\\n\\n' : '') + '—— LLM 回答 ——\\n' + (t.output || '(无输出)');\n"
    "      if(out && out.isConnected) out.textContent = FLOW_MIRROR.out;\n"
    "      flowStatus(which, '');\n"
    "      if(inp) inp.value = '';\n"
    "      FLOW_BUSY = false;\n"
    "      return;\n"
    "    }\n"
    "    await new Promise(res => setTimeout(res, 300));\n"
    "  } /* poll until terminal status — no timeout */\n"
    "}\n"
    "\n"
    "/* LLM 综合 Flow 各节点结果为最终结论 */\n"
    "function flowMerge(){\n"
    "  flowChat('请综合以下 Flow 执行结果，给出最终结论（直接回答，不要复述过程）：\\n\\n%RESULTS%', $('flow-status'));\n"
    "}\n"
    "\n"
    "/* 继续对话：带着 Flow 结果追问 */\n"
    "function flowFollow(){\n"
    "  flowChat('以下是刚才 Flow 的执行结果：\\n\\n%RESULTS%\\n\\n请基于以上结果继续。', $('flow-follow-status'));\n"
    "}\n"
    "\n"
    "async function flowRun(){\n"
    "  if(FLOW_BUSY) return;\n"
    "  const ta = $('flow-json'), st = $('flow-status'), out = $('flow-out');\n"
    "  if(!ta) return;\n"
    "  let dag;\n"
    "  try { dag = JSON.parse(ta.value); }\n"
    "  catch(e){ if(st) st.textContent = 'JSON 解析失败: ' + e.message; return; }\n"
    "  if(!dag.nodes){ if(st) st.textContent = '缺少 nodes 数组'; return; }\n"
    "  FLOW_BUSY = true;\n"
    "  flowStatus('status', '提交中…');\n"
    "  FLOW_MIRROR.out = '';\n"
    "  if(out) out.textContent = '';\n"
    "  const c = await call('POST', '/v1/flows', {flow:dag,input:$('flow-task')?.value || '',workspace:$('flow-workspace')?.value || FLOW_WORKSPACE});\n"
    "  const id = c.obj && c.obj.id;\n"
    "  if(id === undefined){\n"
    "    flowStatus('status', '提交失败: ' + (c.obj && c.obj.error ? c.obj.error : (c.text || ('HTTP ' + c.status))));\n"
    "    FLOW_BUSY = false;\n"
    "    return;\n"
    "  }\n"
    "  await loadFlowTasks();\n"
    "  for(let i = 0; ; i++){\n"
    "    const r = await call('GET', '/v1/tasks/' + id);\n"
    "    const t = r.obj;\n"
    "    if(r.status === 404 || (r.obj && r.obj.error && !t.status)){\n"
    "      /* 任务不存在：服务重启后内存任务表清空（协作任务记录仍在 flows.json，可「继续」） */\n"
    "      flowStatus('status', '⚠ 任务 #' + id + ' 已丢失（服务可能重启过）。可在下方「协作任务」列表里点「继续」恢复执行。');\n"
    "      if(out && out.isConnected) out.textContent = FLOW_MIRROR.out + '\\n\\n⚠ 任务已丢失（服务重启），到「协作任务」列表点「继续」可恢复。';\n"
    "      FLOW_BUSY = false;\n"
    "      loadFlowTasks();\n"
    "      return;\n"
    "    }\n"
    "    if(r.status === 0){\n"
    "      /* 网络失败：服务可能崩溃/重启中，短暂等待重试（看门狗 ~20s 内拉起） */\n"
    "      flowStatus('status', '⚠ 服务连接失败，等待服务恢复…（' + (i + 1) + '）');\n"
    "      if(i > 200){ flowStatus('status', '⚠ 服务长时间无响应，停止轮询。服务恢复后到「协作任务」列表点「继续」。'); FLOW_BUSY = false; return; }\n"
    "      await new Promise(res => setTimeout(res, 300));\n"
    "      continue;\n"
    "    }\n"
    "    if(t?.status)flowLiveProgress(t);\n"
    "    flowStatus('status', (t && t.status && t.status !== 'DONE')\n"
    "      ? flowTaskStatus(t) : '');\n"
    "    if(t && (t.status === 'DONE' || t.status === 'FAILED' || t.status === 'CANCELLED' || t.status === 'TIMEOUT')){\n"
    "      FLOW_LAST_OUTPUT = t.output || '';\n"
    "      FLOW_MIRROR.out = FLOW_LAST_OUTPUT ? ('—— Flow 输出 ——\\n' + FLOW_LAST_OUTPUT) : '(无输出)';\n"
    "      if(out && out.isConnected) out.textContent = FLOW_MIRROR.out;\n"
    "      flowStatus('status', '');\n"
    "      FLOW_BUSY = false;\n"
    "      loadFlow();\n"
    "      loadFlowTasks();\n"
    "      return;\n"
    "    }\n"
    "    await new Promise(res => setTimeout(res, 300));\n"
    "  } /* poll until terminal status — no timeout */\n"
    "}\n"
    "\n"
    "/* ================= 模型路由 ================= */\n"
    "\n"
    "const PROVIDER_PRESETS = {\n"
    "  mock:      {provider:'mock',      base:'',                                                                 model:''},\n"
    "  openai:    {provider:'openai',    base:'https://api.openai.com/v1',                                        model:'gpt-4o'},\n"
    "  anthropic: {provider:'anthropic', base:'https://api.anthropic.com',                                        model:'claude-sonnet-4-6'},\n"
    "  deepseek:  {provider:'openai',    base:'https://api.deepseek.com/v1',                                      model:'deepseek-chat'},\n"
    "  deepseek_a:{provider:'anthropic', base:'https://api.deepseek.com/anthropic',                               model:'deepseek-v4-pro'},\n"
    "  ollama:    {provider:'openai',    base:'http://localhost:11434/v1',                                        model:'llama3'},\n"
    "  gemini:    {provider:'openai',    base:'https://generativelanguage.googleapis.com/v1beta/openai',          model:'gemini-2.0-flash'},\n"
    "  groq:      {provider:'openai',    base:'https://api.groq.com/openai/v1',                                   model:'llama-3.3-70b-versatile'},\n"
    "  together:  {provider:'openai',    base:'https://api.together.xyz/v1',                                      model:'meta-llama/Llama-3.3-70B-Instruct-Turbo'},\n"
    "  nvidia:    {provider:'openai',    base:'https://integrate.api.nvidia.com/v1',                              model:'z-ai/glm-5.3-flash'},\n"
    "  vllm:      {provider:'openai',    base:'http://localhost:8080/v1',                                         model:''},\n"
    "};\n"
    "\n"
    "function presetProvider(){\n"
    "  return (PROVIDER_PRESETS[$('r-provider').value] || PROVIDER_PRESETS.openai).provider;\n"
    "}\n"
    "\n"
    "let ROUTES = [];\n"
    "let ACTIVE = {provider:'', model:'', api_key_set:false};\n"
    "\n"
    "let MODEL_PLAZA = [];\n"
    "\n"
    "async function loadModelPlaza(){\n"
    "  const box = $('model-plaza');\n"
    "  if(!box) return;\n"
    "  const r = await call('GET', '/v1/catalog/models');\n"
    "  MODEL_PLAZA = Array.isArray(r.obj) ? r.obj : [];\n"
    "  if(!MODEL_PLAZA.length){ box.innerHTML = '<span class=\"muted\" style=\"font-size:12px\">（目录为空）</span>'; return; }\n"
    "  box.innerHTML = MODEL_PLAZA.map((m, i) =>\n"
    "    '<div class=\"item\"><h3>' + esc(m.name) + '</h3><p>' + esc(m.note || '') + '</p>' +\n"
    "    '<div class=\"url\">' + esc(m.base_url) + ' · ' + esc(m.model || '任意模型') + '</div>' +\n"
    "    '<div class=\"hint\">' + (m.local\n"
    "        ? '本地运行 · 无需 key'\n"
    "        : 'key: ' + esc(m.key_hint || '')) +\n"
    "      (m.signup_url\n"
    "        ? ' <a href=\"' + esc(m.signup_url) + '\" target=\"_blank\" rel=\"noopener\">申请 key ↗</a>'\n"
    "        : '') + '</div>' +\n"
    "    '<div class=\"row\"><button class=\"sec sm\" onclick=\"modelPlazaUse(' + i + ')\">配置</button>' +\n"
    "    '<button class=\"sec sm\" onclick=\"modelPlazaTest(' + i + ')\">测试</button>' +\n"
    "    '<button class=\"sm\" onclick=\"modelPlazaSet(' + i + ')\">配置并设为当前</button></div></div>'\n"
    "  ).join('');\n"
    "}\n"
    "\n"
    "function modelPlazaFill(i){\n"
    "  const m = MODEL_PLAZA[i]; if(!m) return;\n"
    "  $('r-name').value = m.id;\n"
    "  $('r-base').value = m.base_url;\n"
    "  $('r-model').value = m.model;\n"
    "}\n"
    "\n"
    "function modelPlazaUse(i){\n"
    "  modelPlazaFill(i);\n"
    "  toast('已填入表单，填好 key（如需）后点 Add route');\n"
    "}\n"
    "\n"
    "async function modelPlazaSet(i){\n"
    "  const m = MODEL_PLAZA[i]; if(!m) return;\n"
    "  modelPlazaFill(i);\n"
    "  const key = ($('r-key') && $('r-key').value.trim()) || '';\n"
    "  const r = await call('POST', '/v1/config/llm', {provider: m.provider, base_url: m.base_url, model: m.model, api_key: key});\n"
    "  toast((r.obj && r.obj.ok) ? '已切换为 ' + (m.model || m.name) : '切换失败: ' + ((r.obj && r.obj.error) || r.status));\n"
    "  loadModels();\n"
    "}\n"
    "\n"
    "async function modelPlazaTest(i){\n"
    "  const m = MODEL_PLAZA[i]; if(!m) return;\n"
    "  const key = ($('r-key') && $('r-key').value.trim()) || '';\n"
    "  await testLlm({provider: m.provider, base_url: m.base_url, model: m.model, api_key: key},\n"
    "                (m.model || m.name) + ' ');\n"
    "}\n"
    "\n"
    "function sleep(ms){ return new Promise(r => setTimeout(r, ms)); }\n"
    "\n"
    "async function loadModels(){\n"
    "  const r   = await call('GET', '/v1/routes');\n"
    "  const cfg = await call('GET', '/v1/config/llm');\n"
    "  ROUTES = Array.isArray(r.obj) ? r.obj : [];\n"
    "  ACTIVE = (cfg.obj && typeof cfg.obj === 'object') ? cfg.obj : ACTIVE;\n"
    "  loadModelPlaza();\n"
    "  const rp = $('r-provider');\n"
    "  if(rp && !rp.dataset.bound){\n"
    "    rp.dataset.bound = '1';\n"
    "    rp.addEventListener('change', () => {\n"
    "      const p = PROVIDER_PRESETS[$('r-provider').value] || PROVIDER_PRESETS.openai;\n"
    "      const rb = $('r-base'), rm = $('r-model');\n"
    "      if(rb) rb.value = p.base;\n"
    "      if(rm){ rm.placeholder = p.model || 'model (可选)'; if(!rm.value) rm.value = p.model; }\n"
    "    });\n"
    "  }\n"
    "  const st = $('models-stat');\n"
    "  if(st && !LLM_TEST_IN_FLIGHT) st.textContent = 'active: ' + (ACTIVE.provider || '?')\n"
    "      + (ACTIVE.model ? ' / ' + ACTIVE.model : '')\n"
    "      + (ACTIVE.api_key_set ? '' : '（未配置 api_key）');\n"
    "  const t = $('routes-body');\n"
    "  if(!t) return;\n"
    "  if(!ROUTES.length){ t.innerHTML = '<tr><td colspan=\"8\" class=\"muted\">（暂无路由）</td></tr>'; return; }\n"
    "  const ap = ACTIVE.provider || '';\n"
    "  t.innerHTML = ROUTES.map((x, i) => {\n"
    "    /* active = 路由与当前激活 LLM 的 provider+model+base_url 一致（自动路由已不再按名对应） */\n"
    "    const isActive = (x.provider || '') === ap\n"
    "      && (x.model || '') === (ACTIVE.model || '')\n"
    "      && (x.base_url || '') === (ACTIVE.base_url || '');\n"
    "    return '<tr class=\"' + (isActive ? 'active-row' : '') + '\">'\n"
    "      + '<td>' + esc(x.name || '') + (isActive ? ' <span class=\"badge badge-ok\">active</span>' : '') + '</td>'\n"
    "      + '<td>' + esc(x.provider || '') + '</td>'\n"
    "      + '<td>' + esc(x.model || '') + '</td>'\n"
    "      + '<td class=\"muted\">' + esc(x.base_url || '') + '</td>'\n"
    "      + '<td>' + routeContextLabel(x) + '</td>'\n"
    "      + '<td>' + (x.weight != null ? x.weight : 1) + '</td>'\n"
    "      + '<td>' + (x.calls != null ? x.calls : 0) + '</td>'\n"
    "      + '<td><button onclick=\"testRoute(' + i + ')\" class=\"sec sm\">Test</button> '\n"
    "      + '<button onclick=\"editRouteKey(' + i + ')\" class=\"sec sm\">改Key</button> '\n"
    "      + '<button onclick=\"setRouteContext(' + i + ')\" class=\"sec sm\">上下文</button> '\n"
    "      + '<button onclick=\"refreshRouteContext(' + i + ')\" class=\"sec sm\">核实上下文</button> '\n"
    "      + '<button onclick=\"setActive(' + i + ')\" class=\"sec sm\"' + (isActive ? ' disabled' : '') + '>Set active</button> '\n"
    "      + '<button onclick=\"deleteRoute(' + i + ')\" class=\"sec sm danger\">Delete</button></td></tr>';\n"
    "  }).join('');\n"
    "}\n"
    "\n"
    "async function setActive(i){\n"
    "  const x = ROUTES[i]; if(!x) return;\n"
    "  const st = $('models-stat'); if(st) st.textContent = 'switching…';\n"
    "  const r = await call('POST', '/v1/config/llm', {\n"
    "    provider: x.provider, base_url: x.base_url || '', model: x.model || '', api_key: x.api_key || ''\n"
    "  });\n"
    "  if(st) st.textContent = (r.obj && r.obj.ok)\n"
    "      ? 'switched to ' + (x.model || x.provider)\n"
    "      : (r.obj && r.obj.error) ? 'error: ' + r.obj.error : 'error ' + r.status;\n"
    "  loadModels();\n"
    "}\n"
    "\n"
    "async function deleteRoute(i){\n"
    "  const x = ROUTES[i]; if(!x) return;\n"
    "  await call('DELETE', '/v1/routes/' + encodeURIComponent(x.name));\n"
    "  loadModels();\n"
    "}\n"
    "\n"
    "/* 修改已有路由的 api key：upsert 同名路由，其余字段保持不变 */\n"
    "async function editRouteKey(i){\n"
    "  const x = ROUTES[i]; if(!x) return;\n"
    "  const k = prompt('路由 ' + x.name + ' 的新 API Key：');\n"
    "  if(k === null) return;\n"
    "  const st = $('models-stat'); if(st) st.textContent = 'updating key…';\n"
    "  const r = await call('POST', '/v1/routes', {\n"
    "    name: x.name, provider: x.provider, base_url: x.base_url || '', model: x.model || '',\n"
    "    api_key: k.trim(), weight: x.weight != null ? x.weight : 1\n"
    "  });\n"
    "  if(st) st.textContent = (r.status < 300) ? 'API Key 已更新' : 'error ' + r.status;\n"
    "  loadModels();\n"
    "}\n"
    "\n"
    "/* 手动设置路由的真实上下文窗口：供应商元数据/目录都拿不到时的兜底，\n"
    " * 经 POST /v1/routes 以 context_source=configured 持久化 */\n"
    "async function setRouteContext(i){\n"
    "  const x = ROUTES[i]; if(!x) return;\n"
    "  const cur = Number(x.context_window || x.context_window_tokens) || '';\n"
    "  const k = prompt('路由 ' + x.name + ' 的真实上下文窗口（tokens，1024–4000000）：', cur);\n"
    "  if(k === null) return;\n"
    "  const v = Number(String(k).trim().replace(/[,，\\s_]/g, ''));\n"
    "  if(!Number.isInteger(v) || v < 1024 || v > 4000000){ toast('无效的上下文窗口值（需 1024–4000000 的整数）'); return; }\n"
    "  const st = $('models-stat'); if(st) st.textContent = 'updating context…';\n"
    "  const r = await call('POST', '/v1/routes', {\n"
    "    name: x.name, provider: x.provider, base_url: x.base_url || '', model: x.model || '',\n"
    "    api_key: x.api_key || '', weight: x.weight != null ? x.weight : 1,\n"
    "    context_window: v, context_source: 'configured', max_output_tokens: Number(x.max_output_tokens) || 0\n"
    "  });\n"
    "  if(st) st.textContent = (r.status < 300) ? '上下文窗口已更新' : 'error ' + r.status;\n"
    "  loadModels();\n"
    "}\n"
    "\n"
    "/* ===== 拉取供应商可用模型列表（issue #18）===== */\n"
    "let FETCHED_MODELS = [];\n"
    "\n"
    "function routeContextLabel(model){\n"
    "  const raw = Number(model && (model.context_window || model.context_window_tokens));\n"
    "  const source = model && model.context_source || 'fallback';\n"
    "  /* fallback 值是路由默认 262144，并非模型真实窗口——不得当作已测得的值展示 */\n"
    "  if(!(Number.isInteger(raw) && raw >= 1024) || source === 'fallback')\n"
    "    return esc('上下文未核实 · 默认按 262,144 预估');\n"
    "  const labels = {provider_metadata:'供应商元数据', catalog:'已核实能力目录', configured:'已有配置'};\n"
    "  return esc(raw.toLocaleString() + ' tokens · ' + (labels[source] || '已配置'));\n"
    "}\n"
    "function fetchedModelMetadata(model){\n"
    "  const value = Number(model && (model.context_window || model.context_window_tokens));\n"
    "  const known = Number.isInteger(value) && value >= 1024 && value <= 4000000;\n"
    "  return {context_window: known ? value : 262144,\n"
    "    context_source: known ? (model.context_source || 'provider_metadata') : 'fallback',\n"
    "    max_output_tokens: Number(model && model.max_output_tokens) || 0};\n"
    "}\n"
    "function fetchedModelId(model){\n"
    "  return typeof model === 'string' ? model : String(model && model.id || '');\n"
    "}\n"
    "\n"
    "async function refreshRouteContext(i){\n"
    "  const route=ROUTES[i]; if(!route) return;\n"
    "  const st=$('models-stat'); if(st) st.textContent='正在向供应商核实上下文…';\n"
    "  const started=await call('POST','/v1/routes/models',{route_name:route.name});\n"
    "  if(started.status>=300 || started.obj?.running){ if(st) st.textContent='模型查询忙或启动失败，请稍后重试'; return; }\n"
    "  for(let n=0;n<80;n++){\n"
    "    await new Promise(resolve=>setTimeout(resolve,500));\n"
    "    const result=await call('GET','/v1/routes/models');\n"
    "    if(result.obj?.pending) continue;\n"
    "    await loadModels();\n"
    "    const updated=ROUTES.find(x=>x.name===route.name);\n"
    "    if(st) st.textContent=result.obj?.ok ? (updated?.context_source==='fallback' ? '供应商未公开此模型的上下文；可手动设置已核实值' : '已刷新并保存上下文信息') : ('核实失败：'+(result.obj?.error||'查询无结果'));\n"
    "    return;\n"
    "  }\n"
    "  if(st) st.textContent='查询仍在进行，请稍后刷新';\n"
    "}\n"
    "async function fetchModels(){\n"
    "  const st = $('models-fetch-stat');\n"
    "  const box = $('fetched-models');\n"
    "  const btn = $('models-addall');\n"
    "  const provider = presetProvider();\n"
    "  const base = $('r-base').value.trim();\n"
    "  const key = $('r-key').value.trim();\n"
    "  if(!base){ if(st) st.textContent = '先填 base_url'; return; }\n"
    "  if(st) st.textContent = '请求中…';\n"
    "  if(box) box.innerHTML = '<span class=\"muted\" style=\"font-size:12px\">请求中…</span>';\n"
    "  const r0 = await call('POST', '/v1/routes/models', {provider, base_url: base, api_key: key});\n"
    "  if(!(r0.status < 300)){\n"
    "    if(st) st.textContent = '❌ ' + ((r0.obj && r0.obj.error) || ('HTTP ' + r0.status));\n"
    "    return;\n"
    "  }\n"
    "  for(let i = 0; i < 40; i++){ /* 最多等 20s */\n"
    "    const r = await call('GET', '/v1/routes/models');\n"
    "    const o = r.obj || {};\n"
    "    if(o.pending){ await new Promise(res => setTimeout(res, 500)); continue; }\n"
    "    if(!o.ok){\n"
    "      FETCHED_MODELS = [];\n"
    "      if(box) box.innerHTML = '<span class=\"muted\" style=\"font-size:12px\">（拉取失败：' + esc(o.error || '未知错误') + '）</span>';\n"
    "      if(st) st.textContent = '❌ ' + (o.error || '拉取失败');\n"
    "      if(btn) btn.style.display = 'none';\n"
    "      return;\n"
    "    }\n"
    "    FETCHED_MODELS = Array.isArray(o.models) ? o.models : [];\n"
    "    renderFetchedModels();\n"
    "    if(st) st.textContent = '✅ 拉取到 ' + FETCHED_MODELS.length + ' 个模型，点击即创建路由并激活，也可全部创建';\n"
    "    return;\n"
    "  }\n"
    "  if(st) st.textContent = '❌ 拉取超时';\n"
    "}\n"
    "\n"
    "function renderFetchedModels(){\n"
    "  const box = $('fetched-models');\n"
    "  const btn = $('models-addall');\n"
    "  if(!box) return;\n"
    "  if(!FETCHED_MODELS.length){\n"
    "    box.innerHTML = '<span class=\"muted\" style=\"font-size:12px\">（无可用模型）</span>';\n"
    "    if(btn) btn.style.display = 'none';\n"
    "    return;\n"
    "  }\n"
    "  box.innerHTML = FETCHED_MODELS.map((m, i) => {\n"
    "    const id = fetchedModelId(m);\n"
    "    const context = Number(m && (m.context_window || m.context_window_tokens)) || 0;\n"
    "    const title = context ? '上下文窗口：' + context.toLocaleString() + ' tokens' : '模型未提供上下文元数据，使用默认 256K';\n"
    "    return '<button class=\"sec sm\" onclick=\"pickFetchedModel(' + i + ')\" title=\"' + esc(title) + '\">' + esc(id) + '</button>';\n"
    "  }).join(' ');\n"
    "  if(btn) btn.style.display = '';\n"
    "}\n"
    "\n"
    "/* 点模型 chip = 直接创建该模型的路由（不存在才建）并立即激活 */\n"
    "async function pickFetchedModel(index){\n"
    "  const modelInfo = typeof index === 'number' ? FETCHED_MODELS[index] : index;\n"
    "  const m = fetchedModelId(modelInfo);\n"
    "  if(!m) return;\n"
    "  const provider = presetProvider();\n"
    "  const base = $('r-base') ? $('r-base').value.trim() : '';\n"
    "  const key = $('r-key') ? $('r-key').value.trim() : '';\n"
    "  const name = (provider + '-' + String(m).replace(/[^A-Za-z0-9._-]/g, '-')).slice(0, 60);\n"
    "  const existing = ROUTES.find(x => x.name === name);\n"
    "  const r = await call('POST', '/v1/routes', {name, provider, base_url: base, model: m,\n"
    "    api_key: key || (existing && existing.api_key) || '', weight: existing && existing.weight != null ? existing.weight : 1,\n"
    "    ...fetchedModelMetadata(modelInfo)});\n"
    "  if(!(r.status < 300)){ toast('创建路由失败：HTTP ' + r.status); return; }\n"
    "  const inp = $('r-model'); if(inp) inp.value = m;\n"
    "  const st = $('models-stat'); if(st) st.textContent = 'switching…';\n"
    "  const a = await call('POST', '/v1/config/llm', {provider, base_url: base, model: m, api_key: key});\n"
    "  if(st) st.textContent = (a.obj && a.obj.ok) ? 'switched to ' + m : 'error: ' + ((a.obj && a.obj.error) || a.status);\n"
    "  toast('已创建并激活 ' + m + '，其他模型点 chip 即可切换');\n"
    "  loadModels();\n"
    "}\n"
    "\n"
    "/* 一键把拉取到的模型全部建成路由：命名 <provider>-<model>，重名自动跳过 */\n"
    "async function addFetchedModels(){\n"
    "  if(!FETCHED_MODELS.length) return;\n"
    "  const st = $('models-fetch-stat');\n"
    "  const provider = presetProvider();\n"
    "  const base = $('r-base').value.trim();\n"
    "  const key = $('r-key').value.trim();\n"
    "  const have = new Set(ROUTES.map(x => x.name));\n"
    "  let created = 0, skipped = 0;\n"
    "  for(const modelInfo of FETCHED_MODELS){\n"
    "    const m = fetchedModelId(modelInfo);\n"
    "    if(!m) continue;\n"
    "    const name = (provider + '-' + m.replace(/[^A-Za-z0-9._-]/g, '-')).slice(0, 60);\n"
    "    if(have.has(name)){ skipped++; continue; }\n"
    "    have.add(name);\n"
    "    const r = await call('POST', '/v1/routes', {name, provider, base_url: base, model: m, api_key: key, weight: 1, ...fetchedModelMetadata(modelInfo)});\n"
    "    if(r.status < 300) created++; else skipped++;\n"
    "  }\n"
    "  if(st) st.textContent = '✔ 已创建 ' + created + ' 条路由' + (skipped ? '（跳过 ' + skipped + ' 条已存在）' : '');\n"
    "  toast('已创建 ' + created + ' 条模型路由，可在 Model routes 里 Set active 切换');\n"
    "  loadModels();\n"
    "}\n"
    "\n"
    "async function addRoute(){\n"
    "  const name = $('r-name').value.trim();\n"
    "  const provider = presetProvider();\n"
    "  const msg = $('routes-msg');\n"
    "  if(!name){ if(msg) msg.textContent = 'need name'; return; }\n"
    "  const body = {\n"
    "    name, provider,\n"
    "    base_url: $('r-base').value.trim(),\n"
    "    model: $('r-model').value.trim(),\n"
    "    api_key: $('r-key').value.trim()\n"
    "  };\n"
    "  const w = parseFloat($('r-weight').value);\n"
    "  if(!isNaN(w)) body.weight = w;\n"
    "  const r = await call('POST', '/v1/routes', body);\n"
    "  if(msg) msg.textContent = (r.status < 300) ? 'route saved'\n"
    "      : (r.obj && r.obj.error) ? 'error: ' + r.obj.error : 'error ' + r.status;\n"
    "  if(r.status < 300){\n"
    "    $('r-name').value = ''; $('r-base').value = ''; $('r-key').value = ''; $('r-model').value = '';\n"
    "  }\n"
    "  loadModels();\n"
    "}\n"
    "\n"
    "/* Test an arbitrary LLM config against the live provider (no switch, no persist).\n"
    " * 异步探测：POST 启动后台线程探测，GET 轮询结果 — 探测期间服务器可以继续\n"
    " * 响应其他界面请求（issue #3）。 */\n"
    "let LLM_TEST_IN_FLIGHT = false;\n"
    "async function testLlm(body, prefix){\n"
    "  if(LLM_TEST_IN_FLIGHT){ toast('已有模型测试进行中，请等待结果'); return; }\n"
    "  LLM_TEST_IN_FLIGHT = true;\n"
    "  prefix = prefix || '';\n"
    "  const st = $('models-stat'); if(st) st.textContent = '测试 ' + prefix + '请求中…';\n"
    "  const started = Date.now();\n"
    "  const slowNvidiaModel = (body.model || '').toLowerCase().includes('deepseek-v4.1-flash')\n"
    "    && (body.base_url || '').toLowerCase().includes('integrate.api.nvidia.com');\n"
    "  const deadline = started + (slowNvidiaModel ? 300000 : 60000);\n"
    "  try {\n"
    "  const r0 = await call('POST', '/v1/config/llm/test', body, deadline-Date.now());\n"
    "  if(r0.status === 0 || r0.status >= 300 || r0.obj?.error)\n"
    "    throw new Error(r0.obj?.error || ('HTTP ' + r0.status));\n"
    "  const requestId = r0.obj?.request_id;\n"
    "  if(!requestId) throw new Error('后端没有返回测试编号，请刷新页面并确认程序版本一致');\n"
    "  while(Date.now() < deadline){\n"
    "    const r = await call('GET', '/v1/config/llm/test?request_id=' + encodeURIComponent(requestId), null, deadline-Date.now());\n"
    "    const o = r.obj || {};\n"
    "    if(r.status === 0 || r.status >= 300) throw new Error(o.error || ('HTTP ' + r.status));\n"
    "    if(o.request_id !== requestId) throw new Error('测试结果编号不匹配，请重新测试');\n"
    "    if(o.pending){\n"
    "      if(st) st.textContent = '测试 ' + prefix + (o.model || body.model || '') + ' 请求中… 已等待 ' + Math.floor((Date.now()-started)/1000) + ' 秒';\n"
    "      await new Promise(res => setTimeout(res, Math.min(500,Math.max(0,deadline-Date.now())))); continue;\n"
    "    }\n"
    "    const ok = o.ok;\n"
    "    const detail = o.reply || o.error || ('HTTP ' + r.status);\n"
    "    if(st) st.textContent = (ok ? '✅ 测试通过 ' : '❌ 测试失败 ') + prefix + detail;\n"
    "    toast((ok ? '✅ ' : '❌ ') + prefix + detail);\n"
    "    return;\n"
    "  }\n"
    "  if(st) st.textContent = '❌ 测试超时 ' + prefix;\n"
    "  toast('❌ ' + prefix + '测试超时');\n"
    "  } catch(e) {\n"
    "    if(st) st.textContent = '❌ 测试失败 ' + prefix + e.message;\n"
    "    toast('❌ ' + prefix + e.message);\n"
    "  } finally { LLM_TEST_IN_FLIGHT = false; }\n"
    "}\n"
    "\n"
    "async function testRoute(i){\n"
    "  const x = ROUTES[i]; if(!x) return;\n"
    "  await testLlm({provider: x.provider, base_url: x.base_url || '', model: x.model || '', api_key: x.api_key || ''},\n"
    "                '路由 ' + x.name + ' ');\n"
    "}\n"
    "\n"
    "async function testForm(){\n"
    "  const provider = presetProvider();\n"
    "  await testLlm({\n"
    "    provider,\n"
    "    base_url: $('r-base').value.trim(),\n"
    "    model: $('r-model').value.trim(),\n"
    "    api_key: ($('r-key') && $('r-key').value.trim()) || ''\n"
    "  }, '表单配置 ');\n"
    "}\n"
    "\n"
    "/* ================= 导航 ================= */\n"
    "\n"
    "const TITLES = {dashboard:'Dashboard', chat:'对话', cron:'定时任务', agents:'多 Agent & Flow', policy:'策略', flow:'Flow', models:'Models', mcp:'MCP', skills:'Skills', plugins:'Plugins', im:'IM', memory:'Memory', snapshots:'Execution', trace:'Monitor', cluster:'Cluster', metrics:'Metrics'};\n"
    "let current = 'dashboard';\n"
    "\n"
    "function switchPanel(p){\n"
    "  /* Flow 状态镜像：合并后的 agents 面板也包含 Flow 编辑器 */\n"
    "  if((current === 'flow' || current === 'agents') && p !== 'agents' && p !== 'flow') flowSaveState();\n"
    "  current = p;\n"
    "  /* 分组折叠只由用户点击分组头控制（2026-09-18：切面板不再自动收起） */\n"
    "  document.querySelectorAll('#nav button').forEach(b => {\n"
    "    const on = b.dataset.p === p;\n"
    "    b.classList.toggle('on', on);\n"
    "    if(on) b.setAttribute('aria-current', 'true'); else b.removeAttribute('aria-current');\n"
    "  });\n"
    "  const t = $('pageTitle'); if(t) t.textContent = TITLES[p] || p;\n"
    "  const content = $('content');\n"
    "  content.classList.toggle('chat-content', p === 'chat');\n"
    "  content.innerHTML = panels[p];\n"
    "  if(p === 'skills' || p === 'plugins') enhanceMarketAdvanced(content);\n"
    "  load(p);\n"
    "  if(p === 'flow' || p === 'agents'){flowRestoreState();void workspaceLoad();}\n"
    "  if(window.innerWidth < 900) toggleSidebar(false);\n"
    "}\n"
    "\n"
    "document.querySelectorAll('#nav button').forEach(b => {\n"
    "  b.addEventListener('click', () => {\n"
    "    if(b.id === 'nav-newchat'){\n"
    "      /* Start first so loadChat's automatic ensure joins this exact creation. */\n"
    "      const creation = chatNewSession();\n"
    "      if(current !== 'chat') switchPanel('chat');\n"
    "      void creation;\n"
    "      return;\n"
    "    }\n"
    "    if(b.classList.contains('navgroup')){\n"
    "      /* 分组头：再点一次收起（issue #11 折叠） */\n"
    "      const sub = $(b.dataset.g);\n"
    "      const wasOpen = sub ? sub.classList.contains('open') : false;\n"
    "      document.querySelectorAll('nav .navsub').forEach(s => s.classList.remove('open'));\n"
    "      document.querySelectorAll('nav .navgroup').forEach(g => g.classList.remove('open'));\n"
    "      if(sub && !wasOpen){ sub.classList.add('open'); b.classList.add('open'); }\n"
    "      return;\n"
    "    }\n"
    "    /* 面板切换由 switchPanel 统一收起分组 */\n"
    "    switchPanel(b.dataset.p);\n"
    "  });\n"
    "});\n"
    "\n"
    "function toggleSidebar(force){\n"
    "  const open = typeof force === 'boolean' ? force : !$('sidebar').classList.contains('open');\n"
    "  $('sidebar').classList.toggle('open', open);\n"
    "  $('navToggle').setAttribute('aria-expanded', open ? 'true' : 'false');\n"
    "  $('backdrop').classList.toggle('on', open && window.innerWidth < 900);\n"
    "}\n"
    "$('navToggle').addEventListener('click', () => toggleSidebar());\n"
    "$('backdrop').addEventListener('click', () => toggleSidebar(false));\n"
    "\n"
    "$('btnRefresh').addEventListener('click', () => {\n"
    "  if(current === 'tasks'){ toast('已在 Tasks 页'); return; }\n"
    "  if(current === 'models') loadModels(); else load(current);\n"
    "  toast('已刷新');\n"
    "});\n"
    "\n"
    "/* ================= 主题 ================= */\n"
    "\n"
    "const THEMES = ['dark', 'light', 'ocean', 'forest', 'sunset', 'dragongirl'];\n"
    "function applyTheme(t){\n"
    "  if(!THEMES.includes(t)) t = 'dark';\n"
    "  document.body.dataset.theme = t;\n"
    "  try { localStorage.setItem('cognitive-os-agent-theme', t); } catch(e) {}\n"
    "  const sel = $('theme'); if(sel) sel.value = t;\n"
    "  for(const id of ['sidebar-theme','appearance-theme']){const el=$(id);if(el)el.value=t;}\n"
    "}\n"
    "$('theme').addEventListener('change', e => applyTheme(e.target.value));\n"
    "/* Task-local presentation. No model reasoning or raw planner logs are rendered. */\n"
    "const CHAT_SUBMITTING = new Set();\n"
    "const CHAT_POLLERS = new Set();\n"
    "const CHAT_ENTRIES = new Map();\n"
    "const STAGE_LABELS = {\n"
    "  steering:'已收到补充，等待当前操作结束', replanning:'正在根据补充调整任务',\n"
    "  submitting:'已收到，正在准备', waiting_for_executor:'等待可用执行器', queued:'等待执行', analyzing:'正在分析需求',\n"
    "  preparing_context:'正在准备会话上下文', planning:'正在等待模型回复', plan_ready:'已收到执行计划',\n"
    "  response_ready:'已收到模型答复', executing:'正在执行',\n"
    "  summarizing:'正在整理结果', completed:'执行完成', failed:'执行失败',\n"
    "  cancelled:'已取消', timed_out:'执行超时', interrupted:'执行中断，可恢复', reconnecting:'连接中断，正在重试', recovering:'正在调整执行计划', rolled_back:'本轮文件修改已回滚',\n"
    "  cancelling:'正在取消，等待当前操作结束'\n"
    "};\n"
    "const STAGE_NOTES = {\n"
    "  submitting:'正在创建这次任务记录。', queued:'任务已进入队列，等待可用执行器。',\n"
    "  analyzing:'正在识别目标、约束和需要完成的工作。',\n"
    "  preparing_context:'正在整理本会话的已完成工作与相关上下文。',\n"
    "  planning:'正在请求模型生成下一步可执行计划。',\n"
    "  plan_ready:'模型已生成可执行计划，准备开始工具操作。',\n"
    "  response_ready:'模型已给出答复，正在整理展示。',\n"
    "  executing:'正在执行计划中的动作，完成后会记录结果。',\n"
    "  summarizing:'正在整理执行结果、验证状态和未完成项。',\n"
    "  replanning:'已收到新的补充要求，正在保留已完成工作并调整剩余计划。',\n"
    "  steering:'已收到补充，当前操作结束后会重新规划。',\n"
    "  cancelling:'正在安全停止当前任务。', reconnecting:'连接暂时中断，正在恢复任务状态。', recovering:'工具执行失败，正在分析错误并调整下一步。',\n"
    "  completed:'任务已完成，结果已整理。', failed:'任务未能完成，已保留执行记录。',\n"
    "  cancelled:'任务已取消。', timed_out:'任务执行超时。', interrupted:'任务已离开当前执行器，运行状态无法确认；会话记录已保留，可点击“恢复”继续。',\n"
    "  rolled_back:'本轮操作失败，事务内的文件修改已回滚；正在检查后续处理方式。'\n"
    "};\n"
    "const TOOL_LABELS = {file_read:'读取文件', file_write:'写入文件', file_edit:'修改文件',\n"
    "  list_dir:'浏览目录',\n"
    "  shell:'运行命令', ssh:'远程执行', git:'检查代码仓库', glob:'查找文件', grep:'搜索代码',\n"
    "  search:'检索资料', web_search:'搜索网页', mcp:'调用连接工具', skill:'执行技能'};\n"
    "function toolLabel(name){ return TOOL_LABELS[name] || (name && name.startsWith('file_') ? '处理文件' : name || '执行操作'); }\n"
    "function durationLabel(ms){\n"
    "  const sec = Math.max(0, Math.floor((ms || 0) / 1000));\n"
    "  if(ms > 0 && sec === 0) return '<1 秒';\n"
    "  return sec >= 60 ? Math.floor(sec / 60) + ' 分 ' + sec % 60 + ' 秒' : sec + ' 秒';\n"
    "}\n"
    "function progressLabel(p){\n"
    "  if(['completed','failed','cancelled','timed_out','interrupted'].includes(p.stage)) return STAGE_LABELS[p.stage];\n"
    "  if(p.stage === 'planning') return '正在规划下一步';\n"
    "  if(p.stage === 'executing' && p.cur_tool) return '正在' + toolLabel(p.cur_tool);\n"
    "  if(p.commentary) return p.commentary;\n"
    "  if(p.activity) return p.activity;\n"
    "  if(p.stage === 'planning' || p.stage === 'preparing_context'){\n"
    "    return (p.round > 0 ? '第 ' + p.round + ' 轮 · ' : '') + STAGE_LABELS[p.stage];\n"
    "  }\n"
    "  return p.stage === 'executing' && p.cur_tool\n"
    "    ? toolLabel(p.cur_tool) + ' · ' + p.cur_tool\n"
    "    : (STAGE_LABELS[p.stage] || '正在处理');\n"
    "}\n"
    "function progressNarrative(p){\n"
    "  if(p.stage === 'completed'){\n"
    "    const steps = Array.isArray(p.steps) ? p.steps : [];\n"
    "    const files = new Set(steps.filter(s => s.ok === 1 && (s.tool === 'file_write' || s.tool === 'file_edit') && s.target).map(s => s.target));\n"
    "    if(files.size) return '任务已完成，修改了 ' + files.size + ' 个文件；结果和执行记录已整理。';\n"
    "    if(steps.length) return '任务已完成，执行了 ' + steps.length + ' 个工具动作；结果已整理。';\n"
    "  }\n"
    "  if(['completed','failed','cancelled','timed_out','interrupted'].includes(p.stage)) return STAGE_NOTES[p.stage];\n"
    "  if(p.commentary) return p.commentary;\n"
    "  if(p.activity) return p.activity;\n"
    "  let note = STAGE_NOTES[p.stage] || '正在推进任务。';\n"
    "  if(p.stage === 'executing' && p.cur_tool) note = '正在' + toolLabel(p.cur_tool) + '（' + p.cur_tool + '），完成后会继续下一步。';\n"
    "  return note;\n"
    "}\n"
    "function progressPhase(stage){\n"
    "  if(['planning','plan_ready','steering','replanning','reconnecting'].includes(stage)) return 1;\n"
    "  if(['executing','recovering','rolled_back'].includes(stage)) return 2;\n"
    "  if(['response_ready','summarizing','completed'].includes(stage)) return 3;\n"
    "  return 0;\n"
    "}\n"
    "function currentCommandNote(step){\n"
    "  let detail = '';\n"
    "  try {\n"
    "    const a = typeof step.args === 'string' ? JSON.parse(step.args) : (step.args || {});\n"
    "    detail = a.command || a.path || a.pattern || a.query || '';\n"
    "  } catch(e) { /* args unavailable: fall back to the tool label */ }\n"
    "  const label = toolLabel(step.tool);\n"
    "  detail = String(detail || '').trim();\n"
    "  return detail ? label + '：' + (detail.length > 140 ? detail.slice(0,140) + '…' : detail) : label;\n"
    "}\n"
    "function progressOutline(entry,p){\n"
    "  const steps = Array.isArray(p.steps) ? p.steps : [];\n"
    "  const events = entry.progressEvents || [];\n"
    "  const terminal = ['completed','failed','cancelled','timed_out','interrupted'].includes(p.stage);\n"
    "  const last = terminal ? [...events].reverse().find(e => !['completed','failed','cancelled','timed_out','interrupted'].includes(e.stage)) : p;\n"
    "  const phase = progressPhase(last?.stage || p.stage);\n"
    "  const reads = steps.filter(s => ['file_read','list_dir','glob','grep','search','web_search'].includes(s.tool));\n"
    "  const operations = steps.filter(s => !reads.includes(s));\n"
    "  const failed = steps.filter(s => s.ok === 0).length;\n"
    "  const plans = (p.planned_tools || [...events].reverse().find(e => e.planned_tools?.length)?.planned_tools || []).map(toolLabel);\n"
    "  const lastTarget = [...steps].reverse().find(s => s.target)?.target;\n"
    "  const lastStep = !terminal && steps.length ? steps[steps.length-1] : null;\n"
    "  const planNote = p.stage === 'planning'\n"
    "    ? '等待 ' + (p.model || '模型') + ' 回复' + (p.model_call ? ' · 第 ' + p.model_call + ' 次请求' : '')\n"
    "    : plans.length ? '计划：' + [...new Set(plans)].join('、') : '结合任务要求与执行结果，确定下一步。';\n"
    "  const actionNotes = [];\n"
    "  if(reads.length) actionNotes.push('读取与检索 ' + reads.length + ' 次');\n"
    "  if(operations.length) actionNotes.push('执行操作 ' + operations.length + ' 次');\n"
    "  if(failed) actionNotes.push(failed + ' 次失败已记录');\n"
    "  let actionNote = actionNotes.join(' · ');\n"
    "  if(lastTarget) actionNote += (actionNote ? '。最近处理：' : '最近处理：') + lastTarget;\n"
    "  if(!actionNote) actionNote = terminal ? '本次未调用工具。' : '收到计划后开始操作，结果会持续记录。';\n"
    "  const rows = [\n"
    "    ['梳理目标与上下文','整理当前要求、会话信息和可用能力。'],\n"
    "    [p.stage === 'replanning' || p.stage === 'steering' ? '根据补充调整计划' : '规划下一步',lastStep ? currentCommandNote(lastStep) : planNote],\n"
    "    ['执行与核对',actionNote],\n"
    "    ['整理结果',terminal ? STAGE_NOTES[p.stage] : '根据实际执行结果整理答复和未完成项。']\n"
    "  ];\n"
    "  return rows.map(([title,note],index) => ({title,note,state:\n"
    "    p.stage === 'completed' ? 'done' : terminal ? (index === phase ? 'failed' : index < phase ? 'done' : 'idle') :\n"
    "    index === phase ? 'running' : index < phase || (index === 2 && steps.length) ? 'done' : 'idle'}));\n"
    "}\n"
    "function chatProgressClock(entry){\n"
    "  const p = entry.progress;\n"
    "  if(!p || !entry.el?.isConnected) return;\n"
    "  const elapsed = entry.el.querySelector('.run-time');\n"
    "  if(elapsed) elapsed.textContent = '用时 ' + durationLabel(entry.pending && p.started_ms ? Date.now()-p.started_ms : p.elapsed_ms || 0);\n"
    "  const waiting = entry.el.querySelector('.run-stage-time');\n"
    "  if(waiting && entry.pending && entry.stageSince) waiting.textContent = ' · 已等待 ' + durationLabel(Date.now()-entry.stageSince);\n"
    "}\n"
    "function chatPersist(){\n"
    "  try {\n"
    "    const records = Object.entries(CHAT_CACHE).slice(-12).map(([session, msgs]) => [session,\n"
    "      msgs.slice(-40).map(({role,text,images,pending,progress,progressEvents,taskId,detailsOpen,outlineOpen,timelineOpen,actionsOpen,expandedSteps,stageSince,timestamp_ms}) => ({role,text,images,pending,progress,progressEvents,taskId,detailsOpen,outlineOpen,timelineOpen,actionsOpen,expandedSteps,stageSince,timestamp_ms}))]);\n"
    "    sessionStorage.setItem('cognitive-progress-v1', JSON.stringify({records,tasks:CHAT_TASKS}));\n"
    "  } catch(e) { /* storage quota/private mode: in-memory state remains usable */ }\n"
    "}\n"
    "function chatRestore(){\n"
    "  try {\n"
    "    const saved = JSON.parse(sessionStorage.getItem('cognitive-progress-v1') || 'null');\n"
    "    if(!saved || !Array.isArray(saved.records)) return;\n"
    "    for(const [session,msgs] of saved.records){\n"
    "      if(!Array.isArray(msgs)) continue;\n"
    "      CHAT_CACHE[session] = msgs;\n"
    "      for(const entry of msgs){\n"
    "        if(Number.isInteger(entry.taskId) && entry.pending && saved.tasks?.[session] === entry.taskId){\n"
    "          CHAT_TASKS[session] = entry.taskId;\n"
    "          CHAT_ENTRIES.set(entry.taskId, {session,entry});\n"
    "          void chatPollTask(session, entry.taskId, entry);\n"
    "        }\n"
    "      }\n"
    "    }\n"
    "  } catch(e) { /* ignore invalid/old stored state */ }\n"
    "}\n"
    "function chatRenderTimestamp(entry){\n"
    "  const el=entry.el;if(!el?.isConnected)return;\n"
    "  el.querySelector(':scope > .chat-date-time')?.remove();\n"
    "  const stamp=Number(entry.timestamp_ms),date=new Date(stamp);\n"
    "  const time=document.createElement('time');time.className='chat-date-time';\n"
    "  if(Number.isFinite(stamp) && stamp>0 && !Number.isNaN(date.getTime())){\n"
    "    time.dateTime=date.toISOString();\n"
    "    time.textContent=date.toLocaleString(undefined,{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false});\n"
    "    time.title=Intl.DateTimeFormat().resolvedOptions().timeZone;\n"
    "  }else{time.textContent='时间未记录';}\n"
    "  el.append(time);\n"
    "}\n"
    "function renderChatEntry(entry){\n"
    "  const el = entry.el;\n"
    "  if(!el?.isConnected)return;\n"
    "  if(entry.role !== 'bot'){chatRenderTimestamp(entry);return;}\n"
    "  const follow = CHAT_FOLLOW || chatNearBottom();\n"
    "  const previous = el.querySelector('.run-details');\n"
    "  const wasOpen = previous?.open ?? entry.detailsOpen ?? false;\n"
    "  const wasOutlineOpen = el.querySelector('.run-plan')?.open ?? entry.outlineOpen ?? true;\n"
    "  const actionsOpen = previous?.querySelector('.run-actions')?.open ?? entry.actionsOpen ?? true;\n"
    "  const timelineOpen = previous?.querySelector('.run-timeline')?.open ?? entry.timelineOpen ?? true;\n"
    "  const expandedSteps = new Set(entry.expandedSteps || []);\n"
    "  for(const d of el.querySelectorAll('.run-step-detail')){\n"
    "    if(d.open) expandedSteps.add(d.dataset.step); else expandedSteps.delete(d.dataset.step);\n"
    "  }\n"
    "  el.replaceChildren();\n"
    "  const updates=[...(entry.progressEvents||[]),entry.progress||{}].map(p=>p.commentary).filter(Boolean);\n"
    "  if(updates.length){\n"
    "    const log=document.createElement('div');log.className='chat-stage-updates';log.setAttribute('role','log');log.setAttribute('aria-label','阶段性结论');\n"
    "    log.style.cssText='color:var(--muted);font-size:13px;line-height:1.7;border-left:2px solid var(--border);padding:8px 14px;margin-bottom:14px;white-space:pre-wrap';\n"
    "    let previous='';for(const text of updates){if(text===previous)continue;previous=text;const row=document.createElement('div');row.textContent=text;row.style.marginBottom='8px';log.append(row);}\n"
    "    el.append(log);\n"
    "  }\n"
    "  const p = entry.progress;\n"
    "  if(p){\n"
    "    const panel = document.createElement('section'); panel.className = 'run-card';\n"
    "    panel.dataset.active = String(!!entry.pending);\n"
    "    const summary = document.createElement('div'); summary.className = 'run-header';\n"
    "    const dot = document.createElement('span');\n"
    "    dot.className = 'run-dot' + (entry.pending ? ' active' : '') + (['failed','timed_out'].includes(p.stage) ? ' error' : '');\n"
    "    const label = document.createElement('span'); label.className = 'run-label';\n"
    "    label.textContent = progressLabel(p);\n"
    "    label.setAttribute('role','status'); label.setAttribute('aria-live','polite');\n"
    "    const elapsed = document.createElement('span'); elapsed.className = 'run-time';\n"
    "    const ms = entry.pending && p.started_ms ? Math.max(0,Date.now()-p.started_ms) : (p.elapsed_ms || 0);\n"
    "    elapsed.textContent = '用时 ' + durationLabel(ms);\n"
    "    summary.append(dot,label,elapsed); panel.append(summary);\n"
    "    const context = document.createElement('div'); context.className = 'run-context';\n"
    "    context.textContent = p.stage === 'planning' ? '正在结合任务要求和已有结果，规划下一步。' : progressNarrative(p);\n"
    "    if(entry.pending && ['planning','queued','reconnecting'].includes(p.stage)){\n"
    "      const waiting = document.createElement('span'); waiting.className = 'run-stage-time'; context.append(waiting);\n"
    "    }\n"
    "    panel.append(context);\n"
    "    const outline = document.createElement('ol'); outline.className = 'run-outline';\n"
    "    outline.setAttribute('aria-label','思考与执行脉络');\n"
    "    for(const row of progressOutline(entry,p)){\n"
    "      const item = document.createElement('li'); item.dataset.state = row.state;\n"
    "      const title = document.createElement('div'); title.className = 'run-outline-title'; title.textContent = row.title;\n"
    "      const note = document.createElement('p'); note.className = 'run-outline-note'; note.textContent = row.note;\n"
    "      item.append(title,note); outline.append(item);\n"
    "    }\n"
    "    const plan = document.createElement('details'); plan.className = 'run-plan'; plan.open = wasOutlineOpen;\n"
    "    const planSummary = document.createElement('summary'); planSummary.textContent = '思考与执行脉络';\n"
    "    plan.append(planSummary,outline);\n"
    "    plan.addEventListener('toggle',() => { if(plan.isConnected){entry.outlineOpen = plan.open; chatPersist();} });\n"
    "    panel.append(plan);\n"
    "    const detailBody = document.createElement('details'); detailBody.className = 'run-details'; detailBody.open = wasOpen;\n"
    "    const detailSummary = document.createElement('summary');\n"
    "    detailSummary.textContent = '详细执行记录' + (p.tool_calls ? ' · ' + p.tool_calls + ' 个动作' : '');\n"
    "    detailBody.append(detailSummary);\n"
    "    detailBody.addEventListener('toggle', () => { if(detailBody.isConnected){entry.detailsOpen = detailBody.open; chatPersist();} });\n"
    "    const metrics = document.createElement('div'); metrics.className = 'run-metrics';\n"
    "    if(p.round) { const m = document.createElement('span'); m.textContent = '规划轮次 ' + p.round; metrics.append(m); }\n"
    "    if(p.tool_calls) { const m = document.createElement('span'); m.textContent = p.tool_calls + ' 个动作'; metrics.append(m); }\n"
    "    if(ms) { const m = document.createElement('span'); m.textContent = '用时 ' + durationLabel(ms); metrics.append(m); }\n"
    "    if(p.llm_ms) { const m = document.createElement('span'); m.textContent = '模型 ' + durationLabel(p.llm_ms); metrics.append(m); }\n"
    "    if(p.model) { const m = document.createElement('span'); m.textContent = '模型 ' + p.model; metrics.append(m); }\n"
    "    if(p.thinking) { const m = document.createElement('span'); m.textContent = '深度思考'; metrics.append(m); }\n"
    "    if(p.model_call) { const m = document.createElement('span'); m.textContent = '模型请求 ' + p.model_call + ' 次'; metrics.append(m); }\n"
    "    if(p.model_failures) { const m = document.createElement('span'); m.textContent = '请求失败 ' + p.model_failures + ' 次'; metrics.append(m); }\n"
    "    if(p.tool_ms) { const m = document.createElement('span'); m.textContent = '工具 ' + durationLabel(p.tool_ms); metrics.append(m); }\n"
    "    if(metrics.children.length) detailBody.append(metrics);\n"
    "    const events = Array.isArray(entry.progressEvents) ? entry.progressEvents : [];\n"
    "    const milestones = events.filter(e => !['executing','preparing_context','completed'].includes(e.stage));\n"
    "    const timeline = document.createElement('details'); timeline.className = 'run-timeline';\n"
    "    timeline.open = timelineOpen;\n"
    "    timeline.addEventListener('toggle', () => { if(timeline.isConnected){entry.timelineOpen = timeline.open; chatPersist();} });\n"
    "    const timelineTitle = document.createElement('summary');\n"
    "    timelineTitle.textContent = entry.pending ? '正在执行 · ' + milestones.length + ' 个阶段' : '执行过程 · ' + milestones.length + ' 个阶段';\n"
    "    timeline.append(timelineTitle);\n"
    "    const list = document.createElement('ol'); list.className = 'run-steps';\n"
    "    for(const event of milestones.slice(-20)){\n"
    "      const item = document.createElement('li');\n"
    "      item.dataset.state = event.stage === 'failed' || event.stage === 'reconnecting' ? 'failed' :\n"
    "        (entry.pending && event.seq === p.seq ? 'running' : 'done');\n"
    "      const main = document.createElement('span'); main.className = 'run-step-main';\n"
    "      const title = document.createElement('span'); title.className = 'run-step-name';\n"
    "      title.textContent = event.activity || progressLabel(event); main.append(title);\n"
    "      const meta = document.createElement('small');\n"
    "      const parts = [];\n"
    "      if(event.round) parts.push('第 ' + event.round + ' 轮');\n"
    "      if(Number.isFinite(event.elapsed_ms)) parts.push(durationLabel(event.elapsed_ms));\n"
    "      if(event.model_failures) parts.push('失败 ' + event.model_failures + ' 次');\n"
    "      meta.textContent = parts.join(' · ');\n"
    "      item.append(main,meta); list.append(item);\n"
    "    }\n"
    "    if(entry.pending && p.cur_tool){\n"
    "      const item = document.createElement('li'); item.dataset.state = 'running';\n"
    "      const name = document.createElement('span'); name.className = 'run-step-name';\n"
    "      name.textContent = '正在' + toolLabel(p.cur_tool); item.append(name); list.append(item);\n"
    "    }\n"
    "    if(list.children.length){ timeline.append(list); detailBody.append(timeline); }\n"
    "    const steps = Array.isArray(p.steps) ? p.steps : [];\n"
    "    const files = new Map();\n"
    "    for(const s of steps){\n"
    "      if(s.ok === 1 && (s.tool === 'file_write' || s.tool === 'file_edit') && s.target)\n"
    "        files.set(s.target, {action:s.tool === 'file_write' ? '已写入' : '已编辑', step:s});\n"
    "    }\n"
    "    if(files.size){\n"
    "      const fileCard = document.createElement('section'); fileCard.className = 'run-files';\n"
    "      const head = document.createElement('div'); head.className = 'run-files-head';\n"
    "      const icon = document.createElement('span'); icon.className = 'run-files-icon'; icon.textContent = '✎'; icon.setAttribute('aria-hidden','true');\n"
    "      const title = document.createElement('span'); title.textContent = '已修改 ' + files.size + ' 个文件';\n"
    "      head.append(icon,title); fileCard.append(head);\n"
    "      for(const [path,{action,step}] of files){\n"
    "        const detail = document.createElement('details'); detail.className = 'run-file-detail';\n"
    "        const row = document.createElement('summary'); row.className = 'run-file';\n"
    "        const name = document.createElement('code'); name.textContent = path;\n"
    "        const status = document.createElement('span'); status.textContent = action;\n"
    "        row.append(name,status); detail.append(row);\n"
    "        const info = document.createElement('pre');\n"
    "        info.textContent = [step.args ? '参数：' + step.args : '', step.out ? '结果：' + step.out : ''].filter(Boolean).join('\\n');\n"
    "        detail.append(info); fileCard.append(detail);\n"
    "      }\n"
    "      detailBody.append(fileCard);\n"
    "    }\n"
    "    if(steps.length){\n"
    "      const actions = document.createElement('details'); actions.className = 'run-actions';\n"
    "      actions.open = actionsOpen;\n"
    "      actions.addEventListener('toggle', () => { if(actions.isConnected){entry.actionsOpen = actions.open; chatPersist();} });\n"
    "      const actionSummary = document.createElement('summary'); actionSummary.textContent = '查看 ' + steps.length + ' 个工具动作'; actions.append(actionSummary);\n"
    "      const actionList = document.createElement('ol'); actionList.className = 'run-steps';\n"
    "    for(const [index,s] of steps.entries()){\n"
    "      const item = document.createElement('li');\n"
    "      item.dataset.state = s.ok === 1 ? 'done' : s.ok === 0 ? 'failed' : 'skipped';\n"
    "      const main = document.createElement('span'); main.className = 'run-step-main';\n"
    "      const title = document.createElement('span'); title.className = 'run-step-name';\n"
    "      title.textContent = (s.ok === 1 ? '已完成 · ' : s.ok === 0 ? '失败 · ' : '已跳过 · ') + toolLabel(s.tool) + (s.target ? ' · ' + s.target : '');\n"
    "      main.append(title);\n"
    "      if(s.args || s.out){\n"
    "        const detail = document.createElement('details'); detail.className = 'run-step-detail';\n"
    "        detail.dataset.step = String(s.id ?? index);\n"
    "        detail.open = expandedSteps.has(detail.dataset.step);\n"
    "        detail.addEventListener('toggle', () => {\n"
    "          if(!detail.isConnected) return;\n"
    "          const expanded = new Set(entry.expandedSteps || []);\n"
    "          if(detail.open) expanded.add(detail.dataset.step); else expanded.delete(detail.dataset.step);\n"
    "          entry.expandedSteps = [...expanded]; chatPersist();\n"
    "        });\n"
    "        const ds = document.createElement('summary'); ds.textContent = '查看参数与结果摘要'; detail.append(ds);\n"
    "        const body = document.createElement('div');\n"
    "        body.textContent = [s.args ? '参数：' + s.args : '', s.out ? '结果：' + s.out : ''].filter(Boolean).join('\\n');\n"
    "        detail.append(body); main.append(detail);\n"
    "      }\n"
    "      const meta = document.createElement('small');\n"
    "      meta.textContent = (s.ok === 1 ? '已完成' : s.ok === 0 ? '失败' : '已跳过') + ' · ' + ((s.ms || 0)/1000).toFixed(1) + ' 秒';\n"
    "      item.append(main,meta); actionList.append(item);\n"
    "    }\n"
    "      actions.append(actionList); detailBody.append(actions);\n"
    "    }\n"
    "    if(entry.pending && !events.length && !p.cur_tool){\n"
    "      const item = document.createElement('div'); item.className = 'run-steps-title';\n"
    "      item.textContent = '正在建立执行记录…'; detailBody.append(item);\n"
    "    }\n"
    "    panel.append(detailBody);\n"
    "    el.append(panel);\n"
    "    chatProgressClock(entry);\n"
    "  }\n"
    "  if(entry.text && !entry.pending){\n"
    "    const answer = document.createElement('pre'); answer.className = 'chat-answer';\n"
    "    chatRenderText(answer,entry.text); el.append(answer);\n"
    "    chatAppendCopy(el, () => entry.text);\n"
    "  }\n"
    "  chatRenderTimestamp(entry);\n"
    "  if(entry.role==='bot'){\n"
    "    const images=[...(entry.progress?.images || []),...(entry.progress?.steps || []).filter(s=>s.ok===1 && s.image_preview).map(s=>s.image_preview)];\n"
    "    const merged=new Map([...(entry.images || []),...images].filter(i=>i?.id && i?.session).map(i=>[i.session+':'+i.id,i]));\n"
    "    if(merged.size){entry.images=[...merged.values()];chatRenderImages(el,entry.images);}\n"
    "  }\n"
    "  if(follow) chatScroll(true);\n"
    "}\n"
    "function chatNearBottom(){\n"
    "  const box = $('chat-box'); return !box || box.scrollHeight-box.scrollTop-box.clientHeight < 100;\n"
    "}\n"
    "function chatApplyProgress(session,id,p){\n"
    "  const binding = CHAT_ENTRIES.get(id);\n"
    "  if(!binding || binding.session !== session || !binding.entry.pending) return;\n"
    "  const entry = binding.entry;\n"
    "  if(p.session_id && p.session_id !== session) return;\n"
    "  if(p.seq && entry.progress?.seq > p.seq) return;\n"
    "  if(p.seq && entry.progress?.seq === p.seq && entry.progress.stage === p.stage){\n"
    "    entry.progress = {...entry.progress,...p}; chatProgressClock(entry); return;\n"
    "  }\n"
    "  if(!entry.stageSince || entry.progress?.stage !== p.stage ||\n"
    "     (p.stage === 'planning' && entry.progress?.model_call !== p.model_call)) entry.stageSince = Date.now();\n"
    "  if(p.seq && (!entry.progressEvents?.length || entry.progressEvents[entry.progressEvents.length-1].seq !== p.seq)){\n"
    "    entry.progressEvents = [...(entry.progressEvents || []), {\n"
    "      seq:p.seq, stage:p.stage, activity:p.activity, round:p.round, model:p.model, thinking:p.thinking,\n"
    "      model_call:p.model_call, model_failures:p.model_failures, elapsed_ms:p.elapsed_ms,\n"
    "      cur_tool:p.cur_tool, tool_calls:p.tool_calls, planned_tools:p.planned_tools\n"
    "    }].slice(-64);\n"
    "  }\n"
    "  entry.progress = {...entry.progress, ...p};\n"
    "  if(entry.steeringRevision > (p.applied_updates || 0)) entry.progress.stage = 'steering';\n"
    "  if(entry.cancelling) entry.progress.stage = 'cancelling';\n"
    "  renderChatEntry(entry); chatPersist(); sideRecent(CHAT_TABS_CACHE);\n"
    "}\n"
    "function chatFinish(session,id,entry,text,stage){\n"
    "  entry.pending = false; entry.text = text;entry.timestamp_ms=Date.now();\n"
    "  entry.progress = {...entry.progress, stage,\n"
    "    elapsed_ms: entry.progress?.started_ms ? Date.now()-entry.progress.started_ms : 0};\n"
    "  delete CHAT_TASKS[session]; CHAT_ENTRIES.delete(id);\n"
    "  renderChatEntry(entry);\n"
    "  if(CHAT_SESSION === session){\n"
    "    CHAT_TASK_ID = null; CHAT_RESUME_OK = stage !== 'completed'; chatBusyUI(false);\n"
    "    const status = $('chat-status'); if(status) status.textContent = '';\n"
    "  }\n"
    "  chatPersist(); sideRecent(CHAT_TABS_CACHE); void loadChatSessions();\n"
    "}\n"
    "async function chatPollTask(session,id,entry){\n"
    "  if(CHAT_POLLERS.has(id)) return;\n"
    "  CHAT_POLLERS.add(id);\n"
    "  let failures = 0;\n"
    "  try {\n"
    "    while(CHAT_TASKS[session] === id){\n"
    "      const r = await call('GET','/v1/tasks/' + id);\n"
    "      if(r.status === 404){\n"
    "        /* A finished task may have left the scheduler after a restart while\n"
    "         * its durable chat turn already exists. Reconcile before claiming it\n"
    "         * failed; the thinking toggle itself never submits a task. */\n"
    "        const history = await call('GET', '/v1/chat/history?session=' + encodeURIComponent(session));\n"
    "        const messages = CHAT_CACHE[session] || (session === CHAT_SESSION ? CHAT_MSGS : []);\n"
    "        const at = messages.indexOf(entry);\n"
    "        const question = at > 0 ? messages.slice(0, at).reverse().find(m => m.role === 'user')?.text : null;\n"
    "        const turns = history.obj?.turns;\n"
    "        const last = Array.isArray(turns) ? turns[turns.length - 1] : null;\n"
    "        const archived = chatLatestRuns(history.obj?.runs).find(run =>\n"
    "          run.id === id && question && run.input === question);\n"
    "        if(archived){\n"
    "          const stage = {DONE:'completed',FAILED:'failed',CANCELLED:'cancelled',TIMEOUT:'timed_out',\n"
    "            INTERRUPTED:'interrupted',RUNNING:'interrupted',QUEUED:'interrupted'}[archived.status] || 'interrupted';\n"
    "          const output = archived.output || (stage === 'interrupted'\n"
    "            ? '任务已离开当前执行器，运行状态无法确认。会话记录已保留，可点击“恢复”继续。'\n"
    "            : STAGE_LABELS[stage]);\n"
    "          chatFinish(session,id,entry,output,stage);\n"
    "          if(CHAT_SESSION === session) void chatLoadHistory();\n"
    "        } else if(last?.a && question && last.q === question)\n"
    "          chatFinish(session,id,entry,last.a,'completed');\n"
    "        else\n"
    "          chatFinish(session,id,entry,'任务运行状态已丢失（服务可能重启）。会话记录已保留，可点击“恢复”继续。','interrupted');\n"
    "        return;\n"
    "      }\n"
    "      if(r.status === 401 || r.status === 403){\n"
    "        chatApplyProgress(session,id,{stage:'reconnecting'});\n"
    "        if(CHAT_SESSION === session) $('chat-status').textContent = '访问被拒绝，请检查连接权限；恢复后将继续同步';\n"
    "        await sleep(15000); continue;\n"
    "      }\n"
    "      if(r.status !== 200 || !r.obj?.status){\n"
    "        failures++;\n"
    "        chatApplyProgress(session,id,{stage:'reconnecting'});\n"
    "        await sleep(Math.min(10000,500 * 2 ** Math.min(failures,5))); continue;\n"
    "      }\n"
    "      failures = 0;\n"
    "      const t = r.obj;\n"
    "      if(CHAT_SESSION===session)chatApproval(t,session);\n"
    "      chatApplyProgress(session,id,t);\n"
    "      const final = {DONE:'completed',FAILED:'failed',CANCELLED:'cancelled',TIMEOUT:'timed_out'}[t.status];\n"
    "      if(final){\n"
    "        chatFinish(session,id,entry,t.output && t.output !== '(no output)' ? t.output : (STAGE_LABELS[final] + '，没有返回内容。'),final);\n"
    "        return;\n"
    "      }\n"
    "      await sleep(800);\n"
    "    }\n"
    "  } finally { CHAT_POLLERS.delete(id); }\n"
    "}\n"
    "async function chatSubmit(resume = false){\n"
    "  const executionWorkspace=CHAT_WORKSPACE;\n"
    "  if(chatIsBusy()){\n"
    "    if(!resume && !CHAT_SUBMITTING.has(CHAT_SESSION)) return chatSteer();\n"
    "    toast('正在提交消息，请稍候'); return;\n"
    "  }\n"
    "  const session = CHAT_SESSION, input = $('chat-input');\n"
    "  if(!resume && input?.disabled) { toast('请先配置对话模型'); return; }\n"
    "  const msg = input?.value.trim() || '';\n"
    "  if(!resume && !msg && !CHAT_ATTACH.length) return;\n"
    "  const settings=chatOptions(session),thinking=chatThinkingEnabled();\n"
    "  const permission=$('chat-permission')?.value || settings.permission || 'auto';\n"
    "  const route=settings.route || undefined;\n"
    "  const destination=CHAT_MSGS;\n"
    "  const attachments = resume ? [] : CHAT_ATTACH.slice();\n"
    "  CHAT_SUBMITTING.add(session); chatBusyUI(true);\n"
    "  await Promise.all(attachments.map(a=>a.upload).filter(Boolean));\n"
    "  if(attachments.some(a=>a.status !== 'ready' || !a.id)){\n"
    "    CHAT_SUBMITTING.delete(session);\n"
    "    if(CHAT_SESSION===session) chatBusyUI(chatIsBusy(session));\n"
    "    toast('附件尚不可用，请移除失败的附件后重试'); return;\n"
    "  }\n"
    "  const full = resume ? '（恢复）继续上一次任务' :\n"
    "    (attachments.length ? '[附件: ' + attachments.map(a=>a.name).join(', ') + ']\\n' : '') + msg;\n"
    "  let userEntry,entry;\n"
    "  if(CHAT_SESSION===session){\n"
    "    if(input && !resume && input.value.trim()===msg)input.value='';\n"
    "    CHAT_FOLLOW=true;chatAddBubble('user',full);userEntry=CHAT_MSGS[CHAT_MSGS.length-1];\n"
    "    chatAddBubble('bot','');entry=CHAT_MSGS[CHAT_MSGS.length-1];\n"
    "  }else{\n"
    "    userEntry={role:'user',text:full,pending:false,el:null};entry={role:'bot',text:'',el:null};destination.push(userEntry,entry);\n"
    "  }\n"
    "  userEntry.images=attachments.filter(a=>a.kind==='image').map(a=>({id:a.id,name:a.name,session}));\n"
    "  if(userEntry.el)chatRenderImages(userEntry.el,userEntry.images);\n"
    "  entry.pending = true; entry.progress = {stage:'submitting'};\n"
    "  CHAT_CACHE[session] = CHAT_SESSION===session?CHAT_MSGS:destination; renderChatEntry(entry);\n"
    "  const r = await call('POST',resume ? '/v1/chat/sessions/' + encodeURIComponent(session) + '/resume' : '/v1/chat',\n"
    "    resume ? {thinking,route,permission_mode:permission} : {message:full,session,route,workspace:executionWorkspace || undefined,permission_mode:permission,thinking,attachments:attachments.map(a=>a.id)});\n"
    "  CHAT_SUBMITTING.delete(session);\n"
    "  if(!Number.isInteger(r.obj?.id)){\n"
    "    entry.pending = false; entry.progress.stage = 'failed';\n"
    "    entry.text = r.status === 0 ? '连接中断，无法确认是否已提交。请检查任务列表后重试，避免重复执行。' : '提交失败：' + (r.obj?.error || r.status);\n"
    "    renderChatEntry(entry); chatPersist();\n"
    "    if(CHAT_SESSION === session) chatBusyUI(false);\n"
    "    return;\n"
    "  }\n"
    "  CHAT_ATTACH_DRAFTS.set(session,(CHAT_ATTACH_DRAFTS.get(session)||[]).filter(a=>!attachments.includes(a)));\n"
    "  const id = r.obj.id; entry.taskId = id; entry.progress = {stage:'queued'};\n"
    "  CHAT_TASKS[session] = id; CHAT_ENTRIES.set(id,{session,entry});\n"
    "  sideRecent(CHAT_TABS_CACHE);\n"
    "  if(CHAT_SESSION === session){\n"
    "    CHAT_TASK_ID = id; CHAT_NEW_SESSION = false; CHAT_RESUME_OK = false;\n"
    "    CHAT_ATTACH = CHAT_ATTACH_DRAFTS.get(session) || []; chatAttachRender(); chatBusyUI(true);\n"
    "  }\n"
    "  renderChatEntry(entry); chatPersist(); void loadChatSessions();\n"
    "  await chatPollTask(session,id,entry);\n"
    "}\n"
    "async function chatSteer(){\n"
    "  const session = CHAT_SESSION, id = chatTaskOf(session), input = $('chat-input');\n"
    "  const message = input?.value.trim();\n"
    "  if(!message || id === null) return;\n"
    "  if(CHAT_ATTACH.length){ toast('任务补充暂不支持新附件，请先移除附件或等待任务完成'); return; }\n"
    "  CHAT_SUBMITTING.add(session); chatBusyUI(true);\n"
    "  const r = await call('POST','/v1/tasks/' + id + '/messages',{message,session});\n"
    "  CHAT_SUBMITTING.delete(session);\n"
    "  if(CHAT_SESSION === session) chatBusyUI(chatIsBusy(session));\n"
    "  if(r.status !== 202){\n"
    "    toast(r.status === 409 ? '任务已进入收尾，请在完成后发送；内容已保留' : '补充未确认送达，内容已保留，请检查连接'); return;\n"
    "  }\n"
    "  if(CHAT_SESSION === session){ input.value = ''; chatAddBubble('user',message); }\n"
    "  else (CHAT_CACHE[session] ||= []).push({role:'user',text:message,pending:false,timestamp_ms:Date.now()});\n"
    "  const binding = CHAT_ENTRIES.get(id);\n"
    "  if(binding){ binding.entry.steeringRevision = r.obj.revision; chatApplyProgress(session,id,{stage:'steering'}); }\n"
    "  chatPersist();\n"
    "}\n"
    "function chatSend(){ return chatSubmit(false); }\n"
    "function chatResume(){ return chatSubmit(true); }\n"
    "async function chatCancel(){\n"
    "  const id = CHAT_TASK_ID, binding = CHAT_ENTRIES.get(id);\n"
    "  if(id === null) return;\n"
    "  const r = await call('DELETE','/v1/tasks/' + id);\n"
    "  if(r.status >= 200 && r.status < 300){\n"
    "    if(binding){ binding.entry.cancelling = true; chatApplyProgress(binding.session,id,{stage:'cancelling'}); }\n"
    "  } else toast('取消请求未成功，请检查连接后重试');\n"
    "}\n"
    "chatRestore();\n"
    "\n"
    "applyTheme(localStorage.getItem('cognitive-os-agent-theme') || 'dark');\n"
    "void appearanceLoad();\n"
    "\n"
    "/* ================= 连接状态 ================= */\n"
    "\n"
    "async function pingServer(){\n"
    "  const r = await call('GET', '/v1/config/llm');\n"
    "  const ok = r.status !== 0;\n"
    "  const dot = $('connDot'), txt = $('connText');\n"
    "  if(dot){ dot.className = 'dot ' + (ok ? 'ok' : 'err'); }\n"
    "  if(txt) txt.textContent = ok ? '已连接' : '离线';\n"
    "}\n"
    "setInterval(pingServer, 8000);\n"
    "setInterval(() => { for(const {entry} of CHAT_ENTRIES.values()) if(entry.pending) chatProgressClock(entry); }, 1000);\n"
    "setInterval(() => { if(current === 'trace' && !document.hidden) loadTrace(); }, 3000);\n"
    "setInterval(() => { if((current === 'agents' || current === 'flow') && !document.hidden) refreshFlowTaskProgress(); }, 2000);\n"
    "\n"
    "/* ================= 初始化 ================= */\n"
    "/* ChatGPT 风格：对话是默认首页 */\n"
    "switchPanel('chat');\n"
    "const imInput = $('im-input');\n"
    "if(imInput) imInput.addEventListener('keydown', e => { if(e.key === 'Enter') imSend(); });\n"
    "pingServer();\n"
    "wsConnect();\n"
    "</script>\n"
    "</body>\n"
    "</html>\n"
    "\n"
    ;
